export default "adata}\\\")\\n            if isinstance(self.docs_metadata[-1], Data):\\n                logger.debug(f\\\"[LF] Docs metadata is a Data object {self.docs_metadata}\\\")\\n                self.docs_metadata = self.docs_metadata[-1].data\\n                logger.debug(f\\\"[LF] Docs metadata is a Data object {self.docs_metadata}\\\")\\n                additional_metadata.update(self.docs_metadata)\\n            else:\\n                for item in self.docs_metadata:\\n                    if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                        additional_metadata[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n        # Replace string \\\"None\\\" values with actual None\\n        for key, value in additional_metadata.items():\\n            if value == \\\"None\\\":\\n                additional_metadata[key] = None\\n        logger.debug(f\\\"[LF] Additional metadata {additional_metadata}\\\")\\n        for doc_obj in docs:\\n            data_copy = json.loads(doc_obj.model_dump_json())\\n            text = data_copy.pop(doc_obj.text_key, doc_obj.default_value)\\n            texts.append(text)\\n\\n            # Merge additional metadata from table input\\n            data_copy.update(additional_metadata)\\n\\n            metadatas.append(data_copy)\\n        self.log(metadatas)\\n        if not self.embedding:\\n            msg = \\\"Embedding handle is required to embed documents.\\\"\\n            raise ValueError(msg)\\n\\n        # Generate embeddings\\n        vectors = self.embedding.embed_documents(texts)\\n\\n        if not vectors:\\n            self.log(\\\"No vectors generated from documents.\\\")\\n            return\\n\\n        # Get vector dimension for mapping\\n        dim = len(vectors[0]) if vectors else 768  # default fallback\\n\\n        # Check for AOSS\\n        auth_kwargs = self._build_auth_kwargs()\\n        is_aoss = self._is_aoss_enabled(auth_kwargs.get(\\\"http_auth\\\"))\\n\\n        # Validate engine with AOSS\\n        engine = getattr(self, \\\"engine\\\", \\\"jvector\\\")\\n        self._validate_aoss_with_engines(is_aoss=is_aoss, engine=engine)\\n\\n        # Create mapping with proper KNN settings\\n        space_type = getattr(self, \\\"space_type\\\", \\\"l2\\\")\\n        ef_construction = getattr(self, \\\"ef_construction\\\", 512)\\n        m = getattr(self, \\\"m\\\", 16)\\n\\n        mapping = self._default_text_mapping(\\n            dim=dim,\\n            engine=engine,\\n            space_type=space_type,\\n            ef_construction=ef_construction,\\n            m=m,\\n            vector_field=self.vector_field,\\n        )\\n\\n        # Ensure index exists with proper KNN mapping (index.knn: true is required for vector search)\\n        try:\\n            if not client.indices.exists(index=self.index_name):\\n                self.log(f\\\"Creating index '{self.index_name}' with KNN mapping (index.knn: true)\\\")\\n                client.indices.create(index=self.index_name, body=mapping)\\n        except RequestError as creation_error:\\n            error_msg = str(creation_error).lower()\\n            if \\\"invalid engine\\\" in error_msg or \\\"illegal_argument\\\" in error_msg:\\n                if \\\"jvector\\\" in error_msg:\\n                    msg = (\\n                        \\\"The 'jvector' engine is not available in your OpenSearch installation. \\\"\\n                        \\\"Use 'nmslib' or 'faiss' for standard OpenSearch, or upgrade to OpenSearch 2.9+.\\\"\\n                    )\\n                    raise ValueError(msg) from creation_error\\n                if \\\"index.knn\\\" in error_msg:\\n                    msg = (\\n                        \\\"The index has index.knn: false. Delete the existing index and let the \\\"\\n                        \\\"component recreate it, or create a new index with a different name.\\\"\\n                    )\\n                    raise ValueError(msg) from creation_error\\n            raise\\n\\n        self.log(f\\\"Indexing {len(texts)} documents into '{self.index_name}' with proper KNN mapping...\\\")\\n\\n        # Use the LangChain-style bulk ingestion\\n        return_ids = self._bulk_ingest_embeddings(\\n            client=client,\\n            index_name=self.index_name,\\n            embeddings=vectors,\\n            texts=texts,\\n            metadatas=metadatas,\\n            vector_field=self.vector_field,\\n            text_field=\\\"text\\\",\\n            mapping=mapping,\\n            is_aoss=is_aoss,\\n        )\\n        self.log(metadatas)\\n\\n        self.log(f\\\"Successfully indexed {len(return_ids)} documents.\\\")\\n\\n    # ---------- helpers for filters ----------\\n    def _is_placeholder_term(self, term_obj: dict) -> bool:\\n        # term_obj like {\\\"filename\\\": \\\"__IMPOSSIBLE_VALUE__\\\"}\\n        return any(v == \\\"__IMPOSSIBLE_VALUE__\\\" for v in term_obj.values())\\n\\n    def _coerce_filter_clauses(self, filter_obj: dict | None) -> list[dict]:\\n        \\\"\\\"\\\"Convert filter expressions into OpenSearch-compatible filter clauses.\\n\\n        This method accepts two filter formats and converts them to standardized\\n        OpenSearch query clauses:\\n\\n        Format A - Explicit filters:\\n        {\\\"filter\\\": [{\\\"term\\\": {\\\"field\\\": \\\"value\\\"}}, {\\\"terms\\\": {\\\"field\\\": [\\\"val1\\\", \\\"val2\\\"]}}],\\n         \\\"limit\\\": 10, \\\"score_threshold\\\": 1.5}\\n\\n        Format B - Context-style mapping:\\n        {\\\"data_sources\\\": [\\\"file1.pdf\\\"], \\\"document_types\\\": [\\\"pdf\\\"], \\\"owners\\\": [\\\"user1\\\"]}\\n\\n        Args:\\n            filter_obj: Filter configuration dictionary or None\\n\\n        Returns:\\n            List of OpenSearch filter clauses (term/terms objects)\\n            Placeholder values with \\\"__IMPOSSIBLE_VALUE__\\\" are ignored\\n        \\\"\\\"\\\"\\n        if not filter_obj:\\n            return []\\n\\n        # If it is a string, try to parse it once\\n        if isinstance(filter_obj, str):\\n            try:\\n                filter_obj = json.loads(filter_obj)\\n            except json.JSONDecodeError:\\n                # Not valid JSON - treat as no filters\\n                return []\\n\\n        # Case A: already an explicit list/dict under \\\"filter\\\"\\n        if \\\"filter\\\" in filter_obj:\\n            raw = filter_obj[\\\"filter\\\"]\\n            if isinstance(raw, dict):\\n                raw = [raw]\\n            explicit_clauses: list[dict] = []\\n            for f in raw or []:\\n                if \\\"term\\\" in f and isinstance(f[\\\"term\\\"], dict) and not self._is_placeholder_term(f[\\\"term\\\"]):\\n                    explicit_clauses.append(f)\\n                elif \\\"terms\\\" in f and isinstance(f[\\\"terms\\\"], dict):\\n                    field, vals = next(iter(f[\\\"terms\\\"].items()))\\n                    if isinstance(vals, list) and len(vals) > 0:\\n                        explicit_clauses.append(f)\\n            return explicit_clauses\\n\\n        # Case B: convert context-style maps into clauses\\n        field_mapping = {\\n            \\\"data_sources\\\": \\\"filename\\\",\\n            \\\"document_types\\\": \\\"mimetype\\\",\\n            \\\"owners\\\": \\\"owner\\\",\\n        }\\n        context_clauses: list[dict] = []\\n        for k, values in filter_obj.items():\\n            if not isinstance(values, list):\\n                continue\\n            field = field_mapping.get(k, k)\\n            if len(values) == 0:\\n                # Match-nothing placeholder (kept to mirror your tool semantics)\\n                context_clauses.append({\\\"term\\\": {field: \\\"__IMPOSSIBLE_VALUE__\\\"}})\\n            elif len(values) == 1:\\n                if values[0] != \\\"__IMPOSSIBLE_VALUE__\\\":\\n                    context_clauses.append({\\\"term\\\": {field: values[0]}})\\n            else:\\n                context_clauses.append({\\\"terms\\\": {field: values}})\\n        return context_clauses\\n\\n    # ---------- search (single hybrid path matching your tool) ----------\\n    def search(self, query: str | None = None) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Perform hybrid search combining vector similarity and keyword matching.\\n\\n        This method executes a sophisticated search that combines:\\n        - K-nearest neighbor (KNN) vector similarity search (70% weight)\\n        - Multi-field keyword search with fuzzy matching (30% weight)\\n        - Optional filtering and score thresholds\\n        - Aggregations for faceted search results\\n\\n        Args:\\n            query: Search query string (used for both vector embedding and keyword search)\\n\\n        Returns:\\n            List of search results with page_content, metadata, and relevance scores\\n\\n        Raises:\\n            ValueError: If embedding component is not provided or filter JSON is invalid\\n        \\\"\\\"\\\"\\n        logger.info(self.ingest_data)\\n        client = self.build_client()\\n        q = (query or \\\"\\\").strip()\\n\\n        # Parse optional filter expression (can be either A or B shape; see _coerce_filter_clauses)\\n        filter_obj = None\\n        if getattr(self, \\\"filter_expression\\\", \\\"\\\") and self.filter_expression.strip():\\n            try:\\n                filter_obj = json.loads(self.filter_expression)\\n            except json.JSONDecodeError as e:\\n                msg = f\\\"Invalid filter_expression JSON: {e}\\\"\\n                raise ValueError(msg) from e\\n\\n        if not self.embedding:\\n            msg = \\\"Embedding is required to run hybrid search (KNN + keyword).\\\"\\n            raise ValueError(msg)\\n\\n        # Embed the query\\n        vec = self.embedding.embed_query(q)\\n\\n        # Build filter clauses (accept both shapes)\\n        filter_clauses = self._coerce_filter_clauses(filter_obj)\\n\\n        # Respect the tool's limit/threshold defaults\\n        limit = (filter_obj or {}).get(\\\"limit\\\", self.number_of_results)\\n        score_threshold = (filter_obj or {}).get(\\\"score_threshold\\\", 0)\\n\\n        # Build the same hybrid body as your SearchService\\n        body = {\\n            \\\"query\\\": {\\n                \\\"bool\\\": {\\n                    \\\"should\\\": [\\n                        {\\n                            \\\"knn\\\": {\\n                                self.vector_field: {\\n                                    \\\"vector\\\": vec,\\n                                    \\\"k\\\": 10,  # fixed to match the tool\\n                                    \\\"boost\\\": 0.7,\\n                                }\\n                            }\\n                        },\\n                        {\\n                            \\\"multi_match\\\": {\\n                                \\\"query\\\": q,\\n                                \\\"fields\\\": [\\\"text^2\\\", \\\"filename^1.5\\\"],\\n                                \\\"type\\\": \\\"best_fields\\\",\\n                                \\\"fuzziness\\\": \\\"AUTO\\\",\\n                                \\\"boost\\\": 0.3,\\n                            }\\n                        },\\n                    ],\\n                    \\\"minimum_should_match\\\": 1,\\n                }\\n            },\\n            \\\"aggs\\\": {\\n                \\\"data_sources\\\": {\\\"terms\\\": {\\\"field\\\": \\\"filename\\\", \\\"size\\\": 20}},\\n                \\\"document_types\\\": {\\\"terms\\\": {\\\"field\\\": \\\"mimetype\\\", \\\"size\\\": 10}},\\n                \\\"owners\\\": {\\\"terms\\\": {\\\"field\\\": \\\"owner\\\", \\\"size\\\": 10}},\\n            },\\n            \\\"_source\\\": [\\n                \\\"filename\\\",\\n                \\\"mimetype\\\",\\n                \\\"page\\\",\\n                \\\"text\\\",\\n                \\\"source_url\\\",\\n                \\\"owner\\\",\\n                \\\"allowed_users\\\",\\n                \\\"allowed_groups\\\",\\n            ],\\n            \\\"size\\\": limit,\\n        }\\n        if filter_clauses:\\n            body[\\\"query\\\"][\\\"bool\\\"][\\\"filter\\\"] = filter_clauses\\n\\n        if isinstance(score_threshold, (int, float)) and score_threshold > 0:\\n            # top-level min_score (matches your tool)\\n            body[\\\"min_score\\\"] = score_threshold\\n\\n        resp = client.search(index=self.index_name, body=body)\\n        hits = resp.get(\\\"hits\\\", {}).get(\\\"hits\\\", [])\\n        return [\\n            {\\n                \\\"page_content\\\": hit[\\\"_source\\\"].get(\\\"text\\\", \\\"\\\"),\\n                \\\"metadata\\\": {k: v for k, v in hit[\\\"_source\\\"].items() if k != \\\"text\\\"},\\n                \\\"score\\\": hit.get(\\\"_score\\\"),\\n            }\\n            for hit in hits\\n        ]\\n\\n    def search_documents(self) -> list[Data]:\\n        \\\"\\\"\\\"Search documents and return results as Data objects.\\n\\n        This is the main interface method that performs the search using the\\n        configured search_query and returns results in Langflow's Data format.\\n\\n        Returns:\\n            List of Data objects containing search results with text and metadata\\n\\n        Raises:\\n            Exception: If search operation fails\\n        \\\"\\\"\\\"\\n        try:\\n            raw = self.search(self.search_query or \\\"\\\")\\n            return [Data(text=hit[\\\"page_content\\\"], **hit[\\\"metadata\\\"]) for hit in raw]\\n            self.log(self.ingest_data)\\n        except Exception as e:\\n            self.log(f\\\"search_documents error: {e}\\\")\\n            raise\\n\\n    # -------- dynamic UI handling (auth switch) --------\\n    async def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None) -> dict:\\n        \\\"\\\"\\\"Dynamically update component configuration based on field changes.\\n\\n        This method handles real-time UI updates, particularly for authentication\\n        mode changes that show/hide relevant input fields.\\n\\n        Args:\\n            build_config: Current component configuration\\n            field_value: New value for the changed field\\n            field_name: Name of the field that changed\\n\\n        Returns:\\n            Updated build configuration with appropriate field visibility\\n        \\\"\\\"\\\"\\n        try:\\n            if field_name == \\\"auth_mode\\\":\\n                mode = (field_value or \\\"basic\\\").strip().lower()\\n                is_basic = mode == \\\"basic\\\"\\n                is_jwt = mode == \\\"jwt\\\"\\n\\n                build_config[\\\"username\\\"][\\\"show\\\"] = is_basic\\n                build_config[\\\"password\\\"][\\\"show\\\"] = is_basic\\n\\n                build_config[\\\"jwt_token\\\"][\\\"show\\\"] = is_jwt\\n                build_config[\\\"jwt_header\\\"][\\\"show\\\"] = is_jwt\\n                build_config[\\\"bearer_prefix\\\"][\\\"show\\\"] = is_jwt\\n\\n                build_config[\\\"username\\\"][\\\"required\\\"] = is_basic\\n                build_config[\\\"password\\\"][\\\"required\\\"] = is_basic\\n\\n                build_config[\\\"jwt_token\\\"][\\\"required\\\"] = is_jwt\\n                build_config[\\\"jwt_header\\\"][\\\"required\\\"] = is_jwt\\n                build_config[\\\"bearer_prefix\\\"][\\\"required\\\"] = False\\n\\n                if is_basic:\\n                    build_config[\\\"jwt_token\\\"][\\\"value\\\"] = \\\"\\\"\\n\\n                return build_config\\n\\n        except (KeyError, ValueError) as e:\\n            self.log(f\\\"update_build_config error: {e}\\\")\\n\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/elastic/opensearch_multimodal.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"c7e0bf74f5c0be65bc9efc501ad02603c623e9eb69c3edd34d7997fe3d2aa24d\",\"content\":\"from __future__ import annotations\\n\\nimport copy\\nimport json\\nimport time\\nimport uuid\\nfrom concurrent.futures import ThreadPoolExecutor, as_completed\\nfrom typing import Any\\n\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom lfx.base.vectorstores.vector_store_connection_decorator import vector_store_connection\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    HandleInput,\\n    IntInput,\\n    MultilineInput,\\n    Output,\\n    SecretStrInput,\\n    StrInput,\\n    TableInput,\\n)\\nfrom lfx.log import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import Table\\nfrom opensearchpy import OpenSearch, helpers\\nfrom opensearchpy.exceptions import OpenSearchException, RequestError\\n\\nREQUEST_TIMEOUT = 60\\nMAX_RETRIES = 5\\n\\n\\ndef normalize_model_name(model_name: str) -> str:\\n    \\\"\\\"\\\"Normalize embedding model name for use as field suffix.\\n\\n    Converts model names to valid OpenSearch field names by replacing\\n    special characters and ensuring alphanumeric format.\\n\\n    Args:\\n        model_name: Original embedding model name (e.g., \\\"text-embedding-3-small\\\")\\n\\n    Returns:\\n        Normalized field suffix (e.g., \\\"text_embedding_3_small\\\")\\n    \\\"\\\"\\\"\\n    normalized = model_name.lower()\\n    # Replace common separators with underscores\\n    normalized = normalized.replace(\\\"-\\\", \\\"_\\\").replace(\\\":\\\", \\\"_\\\").replace(\\\"/\\\", \\\"_\\\").replace(\\\".\\\", \\\"_\\\")\\n    # Remove any non-alphanumeric characters except underscores\\n    normalized = \\\"\\\".join(c if c.isalnum() or c == \\\"_\\\" else \\\"_\\\" for c in normalized)\\n    # Remove duplicate underscores\\n    while \\\"__\\\" in normalized:\\n        normalized = normalized.replace(\\\"__\\\", \\\"_\\\")\\n    return normalized.strip(\\\"_\\\")\\n\\n\\ndef get_embedding_field_name(model_name: str) -> str:\\n    \\\"\\\"\\\"Get the dynamic embedding field name for a model.\\n\\n    Args:\\n        model_name: Embedding model name\\n\\n    Returns:\\n        Field name in format: chunk_embedding_{normalized_model_name}\\n    \\\"\\\"\\\"\\n    logger.info(f\\\"chunk_embedding_{normalize_model_name(model_name)}\\\")\\n    return f\\\"chunk_embedding_{normalize_model_name(model_name)}\\\"\\n\\n\\n@vector_store_connection\\nclass OpenSearchVectorStoreComponentMultimodalMultiEmbedding(LCVectorStoreComponent):\\n    \\\"\\\"\\\"OpenSearch Vector Store Component with Multi-Model Hybrid Search Capabilities.\\n\\n    This component provides vector storage and retrieval using OpenSearch, combining semantic\\n    similarity search (KNN) with keyword-based search for optimal results. It supports:\\n    - Multiple embedding models per index with dynamic field names\\n    - Automatic detection and querying of all available embedding models\\n    - Parallel embedding generation for multi-model search\\n    - Document ingestion with model tracking\\n    - Advanced filtering and aggregations\\n    - Flexible authentication options\\n\\n    Features:\\n    - Multi-model vector storage with dynamic fields (chunk_embedding_{model_name})\\n    - Hybrid search combining multiple KNN queries (dis_max) + keyword matching\\n    - Auto-detection of available models in the index\\n    - Parallel query embedding generation for all detected models\\n    - Vector storage with configurable engines (jvector, nmslib, faiss, lucene)\\n    - Flexible authentication (Basic auth, JWT tokens)\\n\\n    Model Name Resolution:\\n    - Priority: deployment > model > model_name attributes\\n    - This ensures correct matching between embedding objects and index fields\\n    - When multiple embeddings are provided, specify embedding_model_name to select which one to use\\n    - During search, each detected model in the index is matched to its corresponding embedding object\\n    \\\"\\\"\\\"\\n\\n    display_name: str = \\\"OpenSearch (Multi-Model Multi-Embedding)\\\"\\n    icon: str = \\\"OpenSearch\\\"\\n    description: str = (\\n        \\\"Store and search documents using OpenSearch with multi-model hybrid semantic and keyword search. \\\"\\n        \\\"To search use the tools search_documents and raw_search. \\\"\\n        \\\"Search documents takes a query for vector search, for example\\\\n\\\"\\n        '  {search_query: \\\"components in openrag\\\"}'\\n    )\\n\\n    # Keys we consider baseline\\n    default_keys: list[str] = [\\n        \\\"opensearch_url\\\",\\n        \\\"index_name\\\",\\n        *[i.name for i in LCVectorStoreComponent.inputs],  # search_query, add_documents, etc.\\n        \\\"embedding\\\",\\n        \\\"embedding_model_name\\\",\\n        \\\"vector_field\\\",\\n        \\\"number_of_results\\\",\\n        \\\"auth_mode\\\",\\n        \\\"username\\\",\\n        \\\"password\\\",\\n        \\\"jwt_token\\\",\\n        \\\"jwt_header\\\",\\n        \\\"bearer_prefix\\\",\\n        \\\"use_ssl\\\",\\n        \\\"verify_certs\\\",\\n        \\\"filter_expression\\\",\\n        \\\"engine\\\",\\n        \\\"space_type\\\",\\n        \\\"ef_construction\\\",\\n        \\\"m\\\",\\n        \\\"num_candidates\\\",\\n        \\\"docs_metadata\\\",\\n        \\\"request_timeout\\\",\\n        \\\"max_retries\\\",\\n    ]\\n\\n    inputs = [\\n        TableInput(\\n            name=\\\"docs_metadata\\\",\\n            display_name=\\\"Document Metadata\\\",\\n            info=(\\n                \\\"Additional metadata key-value pairs to be added to all ingested documents. \\\"\\n                \\\"Useful for tagging documents with source information, categories, or other custom attributes.\\\"\\n            ),\\n            table_schema=[\\n                {\\n                    \\\"name\\\": \\\"key\\\",\\n                    \\\"display_name\\\": \\\"Key\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Key name\\\",\\n                },\\n                {\\n                    \\\"name\\\": \\\"value\\\",\\n                    \\\"display_name\\\": \\\"Value\\\",\\n                    \\\"type\\\": \\\"str\\\",\\n                    \\\"description\\\": \\\"Value of the metadata\\\",\\n                },\\n            ],\\n            value=[],\\n            input_types=[\\\"Data\\\", \\\"JSON\\\"],\\n        ),\\n        StrInput(\\n            name=\\\"opensearch_url\\\",\\n            display_name=\\\"OpenSearch URL\\\",\\n            value=\\\"http://localhost:9200\\\",\\n            info=(\\n                \\\"The connection URL for your OpenSearch cluster \\\"\\n                \\\"(e.g., http://localhost:9200 for local development or your cloud endpoint).\\\"\\n            ),\\n        ),\\n        StrInput(\\n            name=\\\"index_name\\\",\\n            display_name=\\\"Index Name\\\",\\n            value=\\\"langflow\\\",\\n            info=(\\n                \\\"The OpenSearch index name where documents will be stored and searched. \\\"\\n                \\\"Will be created automatically if it doesn't exist.\\\"\\n            ),\\n        ),\\n        DropdownInput(\\n            name=\\\"engine\\\",\\n            display_name=\\\"Vector Engine\\\",\\n            options=[\\\"nmslib\\\", \\\"faiss\\\", \\\"lucene\\\", \\\"jvector\\\"],\\n            value=\\\"jvector\\\",\\n            info=(\\n                \\\"Vector search engine for similarity calculations. 'nmslib' works with standard \\\"\\n                \\\"OpenSearch. 'jvector' requires OpenSearch 2.9+. 'lucene' requires index.knn: true. \\\"\\n                \\\"Amazon OpenSearch Serverless only supports 'nmslib' or 'faiss'.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"space_type\\\",\\n            display_name=\\\"Distance Metric\\\",\\n            options=[\\\"l2\\\", \\\"l1\\\", \\\"cosinesimil\\\", \\\"linf\\\", \\\"innerproduct\\\"],\\n            value=\\\"l2\\\",\\n            info=(\\n                \\\"Distance metric for calculating vector similarity. 'l2' (Euclidean) is most common, \\\"\\n                \\\"'cosinesimil' for cosine similarity, 'innerproduct' for dot product.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"ef_construction\\\",\\n            display_name=\\\"EF Construction\\\",\\n            value=512,\\n            info=(\\n                \\\"Size of the dynamic candidate list during index construction. \\\"\\n                \\\"Higher values improve recall but increase indexing time and memory usage.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"m\\\",\\n            display_name=\\\"M Parameter\\\",\\n            value=16,\\n            info=(\\n                \\\"Number of bidirectional connections for each vector in the HNSW graph. \\\"\\n                \\\"Higher values improve search quality but increase memory usage and indexing time.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"num_candidates\\\",\\n            display_name=\\\"Candidate Pool Size\\\",\\n            value=1000,\\n            info=(\\n                \\\"Number of approximate neighbors to consider for each KNN query. \\\"\\n                \\\"Some OpenSearch deployments do not support this parameter; set to 0 to disable.\\\"\\n            ),\\n            advanced=True,\\n        ),\\n        *LCVectorStoreComponent.inputs,  # includes search_query, add_documents, etc.\\n        HandleInput(name=\\\"embedding\\\", display_name=\\\"Embedding\\\", input_types=[\\\"Embeddings\\\"], is_list=True),\\n        StrInput(\\n            name=\\\"embedding_model_name\\\",\\n            display_name=\\\"Embedding Model Name\\\",\\n            value=\\\"\\\",\\n            info=(\\n                \\\"Name of the embedding model to use for ingestion. This selects which embedding from the list \\\"\\n                \\\"will be used to embed documents. Matches on deployment, model, model_id, or model_name. \\\"\\n                \\\"For duplicate deployments, use combined format: 'deployment:model' \\\"\\n                \\\"(e.g., 'text-embedding-ada-002:text-embedding-3-large'). \\\"\\n                \\\"Leave empty to use the first embedding. Error message will show all available identifiers.\\\"\\n            ),\\n            advanced=False,\\n        ),\\n        StrInput(\\n            name=\\\"vector_field\\\",\\n            display_name=\\\"Legacy Vector Field Name\\\",\\n            value=\\\"chunk_embedding\\\",\\n            advanced=True,\\n            info=(\\n                \\\"Legacy field name for backward compatibility. New documents use dynamic fields \\\"\\n                \\\"(chunk_embedding_{model_name}) based on the embedding_model_name.\\\"\\n            ),\\n        ),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Default Result Limit\\\",\\n            value=10,\\n            advanced=True,\\n            info=(\\n                \\\"Default maximum number of search results to return when no limit is \\\"\\n                \\\"specified in the filter expression.\\\"\\n            ),\\n        ),\\n        MultilineInput(\\n            name=\\\"filter_expression\\\",\\n            display_name=\\\"Search Filters (JSON)\\\",\\n            value=\\\"\\\",\\n            info=(\\n                \\\"Optional JSON configuration for search filtering, result limits, and score thresholds.\\\\n\\\\n\\\"\\n                \\\"Format 1 - Explicit filters:\\\\n\\\"\\n                '{\\\"filter\\\": [{\\\"term\\\": {\\\"filename\\\":\\\"doc.pdf\\\"}}, '\\n                '{\\\"terms\\\":{\\\"owner\\\":[\\\"user1\\\",\\\"user2\\\"]}}], \\\"limit\\\": 10, \\\"score_threshold\\\": 1.6}\\\\n\\\\n'\\n                \\\"Format 2 - Context-style mapping:\\\\n\\\"\\n                '{\\\"data_sources\\\":[\\\"file.pdf\\\"], \\\"document_types\\\":[\\\"application/pdf\\\"], \\\"owners\\\":[\\\"user123\\\"]}\\\\n\\\\n'\\n                \\\"Use __IMPOSSIBLE_VALUE__ as placeholder to ignore specific filters.\\\"\\n            ),\\n        ),\\n        # ----- Auth controls (dynamic) -----\\n        DropdownInput(\\n            name=\\\"auth_mode\\\",\\n            display_name=\\\"Authentication Mode\\\",\\n            value=\\\"jwt\\\",\\n            options=[\\\"basic\\\", \\\"jwt\\\"],\\n            info=(\\n                \\\"Authentication method: 'basic' for username/password authentication, \\\"\\n                \\\"or 'jwt' for JSON Web Token (Bearer) authentication.\\\"\\n            ),\\n            real_time_refresh=True,\\n            advanced=False,\\n        ),\\n        StrInput(\\n            name=\\\"username\\\",\\n            display_name=\\\"Username\\\",\\n            value=\\\"admin\\\",\\n            show=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"password\\\",\\n            display_name=\\\"OpenSearch Password\\\",\\n            value=\\\"admin\\\",\\n            show=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"jwt_token\\\",\\n            display_name=\\\"JWT Token\\\",\\n            value=\\\"JWT\\\",\\n            load_from_db=False,\\n            show=False,\\n            info=(\\n                \\\"Valid JSON Web Token for authentication. \\\"\\n                \\\"Will be sent in the Authorization header (with optional 'Bearer ' prefix).\\\"\\n            ),\\n        ),\\n        StrInput(\\n            name=\\\"jwt_header\\\",\\n            display_name=\\\"JWT Header Name\\\",\\n            value=\\\"Authorization\\\",\\n            show=False,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"bearer_prefix\\\",\\n            display_name=\\\"Prefix 'Bearer '\\\",\\n            value=False,\\n            show=False,\\n            advanced=True,\\n        ),\\n        # ----- TLS -----\\n        BoolInput(\\n            name=\\\"use_ssl\\\",\\n            display_name=\\\"Use SSL/TLS\\\",\\n            value=True,\\n            advanced=True,\\n            info=\\\"Enable SSL/TLS encryption for secure connections to OpenSearch.\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"verify_certs\\\",\\n            display_name=\\\"Verify SSL Certificates\\\",\\n            value=False,\\n            advanced=True,\\n            info=(\\n                \\\"Verify SSL certificates when connecting. \\\"\\n                \\\"Disable for self-signed certificates in development environments.\\\"\\n            ),\\n        ),\\n        # ----- Timeout / Retry -----\\n        StrInput(\\n            name=\\\"request_timeout\\\",\\n            display_name=\\\"Request Timeout (seconds)\\\",\\n            value=\\\"60\\\",\\n            advanced=True,\\n            info=(\\n                \\\"Time in seconds to wait for a response from OpenSearch. \\\"\\n                \\\"Increase for large bulk ingestion or complex hybrid queries.\\\"\\n            ),\\n        ),\\n        StrInput(\\n            name=\\\"max_retries\\\",\\n            display_name=\\\"Max Retries\\\",\\n            value=\\\"3\\\",\\n            advanced=True,\\n            info=\\\"Number of retries for failed connections before raising an error.\\\",\\n        ),\\n    ]\\n    outputs = [\\n        Output(\\n            display_name=\\\"Search Results\\\",\\n            name=\\\"search_results\\\",\\n            method=\\\"search_documents\\\",\\n        ),\\n        Output(display_name=\\\"Raw Search\\\", name=\\\"raw_search\\\", method=\\\"raw_search\\\"),\\n    ]\\n\\n    def raw_search(self, query: str | dict | None = None) -> Data:\\n        \\\"\\\"\\\"Execute a raw OpenSearch query against the target index.\\n\\n        Args:\\n            query (dict[str, Any]): The OpenSearch query DSL dictionary.\\n\\n        Returns:\\n            Data: Search results as a Data object.\\n\\n        Raises:\\n            ValueError: If 'query' is not a valid OpenSearch query (must be a non-empty dict).\\n        \\\"\\\"\\\"\\n        raw_query = query if query is not None else self.search_query\\n\\n        if raw_query is None or (isinstance(raw_query, str) and not raw_query.strip()):\\n            self.log(\\\"No query provided for raw search - returning empty results\\\")\\n            return Data(data={})\\n\\n        if isinstance(raw_query, dict):\\n            query_body = copy.deepcopy(raw_query)\\n        elif isinstance(raw_query, str):\\n            s = raw_query.strip()\\n\\n            # First, optimistically try to parse as JSON DSL\\n            try:\\n                query_body = json.loads(s)\\n            except json.JSONDecodeError:\\n                # Fallback: treat as a basic text query over common fields\\n                query_body = {\\n                    \\\"query\\\": {\\n                        \\\"multi_match\\\": {\\n                            \\\"query\\\": s,\\n                            \\\"fields\\\": [\\\"text^2\\\", \\\"filename^1.5\\\"],\\n                            \\\"type\\\": \\\"best_fields\\\",\\n                            \\\"fuzziness\\\": \\\"AUTO\\\",\\n                        }\\n                    }\\n                }\\n        else:\\n            msg = f\\\"Unsupported raw_search query type: {type(raw_query)!r}\\\"\\n            raise TypeError(msg)\\n\\n        filter_obj = self._parse_filter_expression()\\n        filter_clauses = self._coerce_filter_clauses(filter_obj)\\n\\n        if filter_clauses:\\n            if \\\"query\\\" in query_body:\\n                original_query = query_body[\\\"query\\\"]\\n                query_body[\\\"query\\\"] = {\\n                    \\\"bool\\\": {\\n                        \\\"must\\\": [original_query],\\n                        \\\"filter\\\": filter_clauses,\\n                    }\\n                }\\n            else:\\n                query_body[\\\"query\\\"] = {\\n                    \\\"bool\\\": {\\n                        \\\"must\\\": [{\\\"match_all\\\": {}}],\\n                        \\\"filter\\\": filter_clauses,\\n                    }\\n                }\\n\\n        if filter_obj:\\n            # Apply limit if not already set in the raw query\\n            if \\\"size\\\" not in query_body:\\n                limit = self._resolve_limit(filter_obj, default_limit=None)\\n                if limit is not None:\\n                    query_body[\\\"size\\\"] = limit\\n\\n            # Apply score_threshold / scoreThreshold as min_score if not already set\\n            if \\\"min_score\\\" not in query_body:\\n                score_threshold = self._resolve_score_threshold(filter_obj)\\n                if score_threshold is not None:\\n                    query_body[\\\"min_score\\\"] = score_threshold\\n\\n        client = self.build_client()\\n        logger.info(f\\\"query: {query_body}\\\")\\n        resp = client.search(\\n            index=self.index_name,\\n            body=query_body,\\n            params={\\\"terminate_after\\\": 0},\\n        )\\n        # Remove any _source keys whose value is a list of floats (embedding vectors)\\n        # Minimum length threshold to identify embedding vectors\\n        min_vector_length = 100\\n\\n        def is_vector(val):\\n            # Accepts if it's a list of numbers (float or int) and has reasonable vector length\\n            return (\\n                isinstance(val, list) and len(val) > min_vector_length and all(isinstance(x, (float, int)) for x in val)\\n            )\\n\\n        if \\\"hits\\\" in resp and \\\"hits\\\" in resp[\\\"hits\\\"]:\\n            for hit in resp[\\\"hits\\\"][\\\"hits\\\"]:\\n                source = hit.get(\\\"_source\\\")\\n                if isinstance(source, dict):\\n                    keys_to_remove = [k for k, v in source.items() if is_vector(v)]\\n                    for k in keys_to_remove:\\n                        source.pop(k)\\n        logger.info(f\\\"Raw search response (all embedding vectors removed): {resp}\\\")\\n        return Data(**resp)\\n\\n    def _get_embedding_model_name(self, embedding_obj=None) -> str:\\n        \\\"\\\"\\\"Get the embedding model name from component config or embedding object.\\n\\n        Priority: deployment > model > model_id > model_name\\n        This ensures we use the actual model being deployed, not just the configured model.\\n        Supports multiple embedding providers (OpenAI, Watsonx, Cohere, etc.)\\n\\n        Args:\\n            embedding_obj: Specific embedding object to get name from (optional)\\n\\n        Returns:\\n            Embedding model name\\n\\n        Raises:\\n            ValueError: If embedding model name cannot be determined\\n        \\\"\\\"\\\"\\n        # First try explicit embedding_model_name input\\n        if hasattr(self, \\\"embedding_model_name\\\") and self.embedding_model_name:\\n            return self.embedding_model_name.strip()\\n\\n        # Try to get from provided embedding object\\n        if embedding_obj:\\n            # Priority: deployment > model > model_id > model_name\\n            if hasattr(embedding_obj, \\\"deployment\\\") and embedding_obj.deployment:\\n                return str(embedding_obj.deployment)\\n            if hasattr(embedding_obj, \\\"model\\\") and embedding_obj.model:\\n                return str(embedding_obj.model)\\n            if hasattr(embedding_obj, \\\"model_id\\\") and embedding_obj.model_id:\\n                return str(embedding_obj.model_id)\\n            if hasattr(embedding_obj, \\\"model_name\\\") and embedding_obj.model_name:\\n                return str(embedding_obj.model_name)\\n\\n        # Try to get from embedding component (legacy single embedding)\\n        if hasattr(self, \\\"embedding\\\") and self.embedding:\\n            # Handle list of embeddings\\n            if isinstance(self.embedding, list) and len(self.embedding) > 0:\\n                first_emb = self.embedding[0]\\n                if hasattr(first_emb, \\\"deployment\\\") and first_emb.deployment:\\n                    return str(first_emb.deployment)\\n                if hasattr(first_emb, \\\"model\\\") and first_emb.model:\\n                    return str(first_emb.model)\\n                if hasattr(first_emb, \\\"model_id\\\") and first_emb.model_id:\\n                    return str(first_emb.model_id)\\n                if hasattr(first_emb, \\\"model_name\\\") and first_emb.model_name:\\n                    return str(first_emb.model_name)\\n            # Handle single embedding\\n            elif not isinstance(self.embedding, list):\\n                if hasattr(self.embedding, \\\"deployment\\\") and self.embedding.deployment:\\n                    return str(self.embedding.deployment)\\n                if hasattr(self.embedding, \\\"model\\\") and self.embedding.model:\\n                    return str(self.embedding.model)\\n                if hasattr(self.embedding, \\\"model_id\\\") and self.embedding.model_id:\\n                    return str(self.embedding.model_id)\\n                if hasattr(self.embedding, \\\"model_name\\\") and self.embedding.model_name:\\n                    return str(self.embedding.model_name)\\n\\n        msg = (\\n            \\\"Could not determine embedding model name. \\\"\\n            \\\"Please set the 'embedding_model_name' field or ensure the embedding component \\\"\\n            \\\"has a 'deployment', 'model', 'model_id', or 'model_name' attribute.\\\"\\n        )\\n        raise ValueError(msg)\\n\\n    # ---------- helper functions for index management ----------\\n    def _default_text_mapping(\\n        self,\\n        dim: int,\\n        engine: str = \\\"jvector\\\",\\n        space_type: str = \\\"l2\\\",\\n        ef_search: int = 512,\\n        ef_construction: int = 100,\\n        m: int = 16,\\n        vector_field: str = \\\"vector_field\\\",\\n    ) -> dict[str, Any]:\\n        \\\"\\\"\\\"Create the default OpenSearch index mapping for vector search.\\n\\n        This method generates the index configuration with k-NN settings optimized\\n        for approximate nearest neighbor search using the specified vector engine.\\n        Includes the embedding_model keyword field for tracking which model was used.\\n\\n        Args:\\n            dim: Dimensionality of the vector embeddings\\n            engine: Vector search engine (jvector, nmslib, faiss, lucene)\\n            space_type: Distance metric for similarity calculation\\n            ef_search: Size of dynamic list used during search\\n            ef_construction: Size of dynamic list used during index construction\\n            m: Number of bidirectional links for each vector\\n            vector_field: Name of the field storing vector embeddings\\n\\n        Returns:\\n            Dictionary containing OpenSearch index mapping configuration\\n        \\\"\\\"\\\"\\n        return {\\n            \\\"settings\\\": {\\\"index\\\": {\\\"knn\\\": True, \\\"knn.algo_param.ef_search\\\": ef_search}},\\n            \\\"mappings\\\": {\\n                \\\"properties\\\": {\\n                    vector_field: {\\n                        \\\"type\\\": \\\"knn_vector\\\",\\n                        \\\"dimension\\\": dim,\\n                        \\\"method\\\": {\\n                            \\\"name\\\": \\\"disk_ann\\\",\\n                            \\\"space_type\\\": space_type,\\n                            \\\"engine\\\": engine,\\n                            \\\"parameters\\\": {\\\"ef_construction\\\": ef_construction, \\\"m\\\": m},\\n                        },\\n                    },\\n                    \\\"embedding_model\\\": {\\\"type\\\": \\\"keyword\\\"},  # Track which model was used\\n                    \\\"embedding_dimensions\\\": {\\\"type\\\": \\\"integer\\\"},\\n                }\\n            },\\n        }\\n\\n    def _ensure_embedding_field_mapping(\\n        self,\\n        client: OpenSearch,\\n        index_name: str,\\n        field_name: str,\\n        dim: int,\\n        engine: str,\\n        space_type: str,\\n        ef_construction: int,\\n        m: int,\\n    ) -> None:\\n        \\\"\\\"\\\"Lazily add a dynamic embedding field to the index if it doesn't exist.\\n\\n        This allows adding new embedding models without recreating the entire index.\\n        Also ensures the embedding_model tracking field exists.\\n\\n        Note: Some OpenSearch versions/configurations have issues with dynamically adding\\n        knn_vector mappings (NullPointerException). This method checks if the field\\n        already exists before attempting to add it, and gracefully skips if the field\\n        is already properly configured.\\n\\n        Args:\\n            client: OpenSearch client instance\\n            index_name: Target index name\\n            field_name: Dynamic field name for this embedding model\\n            dim: Vector dimensionality\\n            engine: Vector search engine\\n            space_type: Distance metric\\n            ef_construction: Construction parameter\\n            m: HNSW parameter\\n        \\\"\\\"\\\"\\n        # First, check if the field already exists and is properly mapped\\n        properties = self._get_index_properties(client)\\n        if self._is_knn_vector_field(properties, field_name):\\n            # Field already exists as knn_vector - verify dimensions match\\n            existing_dim = self._get_field_dimension(properties, field_name)\\n            if existing_dim is not None and existing_dim != dim:\\n                logger.warning(\\n                    f\\\"Field '{field_name}' exists with dimension {existing_dim}, \\\"\\n                    f\\\"but current embedding has dimension {dim}. Using existing mapping.\\\"\\n                )\\n            else:\\n                logger.info(\\n                    f\\\"[OpenSearchMultimodel] Field '{field_name}' already exists\\\"\\n                    f\\\"as knn_vector with matching dimensions - skipping mapping update\\\"\\n                )\\n            return\\n\\n        # Field doesn't exist, try to add the mapping\\n        try:\\n            mapping = {\\n                \\\"properties\\\": {\\n                    field_name: {\\n                        \\\"type\\\": \\\"knn_vector\\\",\\n                        \\\"dimension\\\": dim,\\n                        \\\"method\\\": {\\n                            \\\"name\\\": \\\"disk_ann\\\",\\n                            \\\"space_type\\\": space_type,\\n                            \\\"engine\\\": engine,\\n                            \\\"parameters\\\": {\\\"ef_construction\\\": ef_construction, \\\"m\\\": m},\\n                        },\\n                    },\\n                    # Also ensure the embedding_model tracking field exists as keyword\\n                    \\\"embedding_model\\\": {\\\"type\\\": \\\"keyword\\\"},\\n                    \\\"embedding_dimensions\\\": {\\\"type\\\": \\\"integer\\\"},\\n                }\\n            }\\n            client.indices.put_mapping(index=index_name, body=mapping)\\n            logger.info(f\\\"Added/updated embedding field mapping: {field_name}\\\")\\n        except RequestError as e:\\n            error_str = str(e).lower()\\n            if \\\"invalid engine\\\" in error_str and \\\"jvector\\\" in error_str:\\n                msg = (\\n                    \\\"The 'jvector' engine is not available in your OpenSearch installation. \\\"\\n                    \\\"Use 'nmslib' or 'faiss' for standard OpenSearch, or upgrade to OpenSearch 2.9+.\\\"\\n                )\\n                raise ValueError(msg) from e\\n            if \\\"index.knn\\\" in error_str:\\n                msg = (\\n                    \\\"The index has index.knn: false. Delete the existing index and let the \\\"\\n                    \\\"component recreate it, or create a new index with a different name.\\\"\\n                )\\n                raise ValueError(msg) from e\\n            raise\\n        except Exception as e:\\n            # Check if this is the known OpenSearch k-NN NullPointerException issue\\n            error_str = str(e).lower()\\n            if \\\"null\\\" in error_str or \\\"nullpointerexception\\\" in error_str:\\n                logger.warning(\\n                    f\\\"[OpenSearchMultimodel] Could not add embedding field mapping for {field_name}\\\"\\n                    f\\\"due to OpenSearch k-NN plugin issue: {e}. \\\"\\n                    f\\\"This is a known issue with some OpenSearch versions. \\\"\\n                    f\\\"[OpenSearchMultimodel] Skipping mapping update. \\\"\\n                    f\\\"Please ensure the index has the correct mapping for KNN search to work.\\\"\\n                )\\n                # Skip and continue - ingestion will proceed, but KNN search may fail if mapping doesn't exist\\n                return\\n            logger.warning(f\\\"[OpenSearchMultimodel] Could not add embedding field mapping for {field_name}: {e}\\\")\\n            raise\\n\\n        # Verify the field was added correctly\\n        properties = self._get_index_properties(client)\\n        if not self._is_knn_vector_field(properties, field_name):\\n            msg = f\\\"Field '{field_name}' is not mapped as knn_vector. Current mapping: {properties.get(field_name)}\\\"\\n            logger.error(msg)\\n            raise ValueError(msg)\\n\\n    def _validate_aoss_with_engines(self, *, is_aoss: bool, engine: str) -> None:\\n        \\\"\\\"\\\"Validate engine compatibility with Amazon OpenSearch Serverless (AOSS).\\n\\n        Amazon OpenSearch Serverless has restrictions on which vector engines\\n        can be used. This method ensures the selected engine is compatible.\\n\\n        Args:\\n            is_aoss: Whether the connection is to Amazon OpenSearch Serverless\\n            engine: The selected vector search engine\\n\\n        Raises:\\n            ValueError: If AOSS is used with an incompatible engine\\n        \\\"\\\"\\\"\\n        if is_aoss and engine not in {\\\"nmslib\\\", \\\"faiss\\\"}:\\n            msg = \\\"Amazon OpenSearch Service Serverless only supports `nmslib` or `faiss` engines\\\"\\n            raise ValueError(msg)\\n\\n    def _is_aoss_enabled(self, http_auth: Any) -> bool:\\n        \\\"\\\"\\\"Determine if Amazon OpenSearch Serverless (AOSS) is being used.\\n\\n        Args:\\n            http_auth: The HTTP authentication object\\n\\n        Returns:\\n            True if AOSS is enabled, False otherwise\\n        \\\"\\\"\\\"\\n        return http_auth is not None and hasattr(http_auth, \\\"service\\\") and http_auth.service == \\\"aoss\\\"\\n\\n    def _bulk_ingest_embeddings(\\n        self,\\n        client: OpenSearch,\\n        index_name: str,\\n        embeddings: list[list[float]],\\n        texts: list[str],\\n        metadatas: list[dict] | None = None,\\n        ids: list[str] | None = None,\\n        vector_field: str = \\\"vector_field\\\",\\n        text_field: str = \\\"text\\\",\\n        embedding_model: str = \\\"unknown\\\",\\n        mapping: dict | None = None,\\n        max_chunk_bytes: int | None = 1 * 1024 * 1024,\\n        *,\\n        is_aoss: bool = False,\\n    ) -> list[str]:\\n        \\\"\\\"\\\"Efficiently ingest multiple documents with embeddings into OpenSearch.\\n\\n        This method uses bulk operations to insert documents with their vector\\n        embeddings and metadata into the specified OpenSearch index. Each document\\n        is tagged with the embedding_model name for tracking.\\n\\n        Args:\\n            client: OpenSearch client instance\\n            index_name: Target index for document storage\\n            embeddings: List of vector embeddings for each document\\n            texts: List of document texts\\n            metadatas: Optional metadata dictionaries for each document\\n            ids: Optional document IDs (UUIDs generated if not provided)\\n            vector_field: Field name for storing vector embeddings\\n            text_field: Field name for storing document text\\n            embedding_model: Name of the embedding model used\\n            mapping: Optional index mapping configuration\\n            max_chunk_bytes: Maximum size per bulk request chunk\\n            is_aoss: Whether using Amazon OpenSearch Serverless\\n\\n        Returns:\\n            List of document IDs that were successfully ingested\\n        \\\"\\\"\\\"\\n        logger.debug(f\\\"[OpenSearchMultimodel] Bulk ingesting embeddings for {index_name}\\\")\\n        if not mapping:\\n            mapping = {}\\n\\n        requests = []\\n        return_ids = []\\n        vector_dimensions = len(embeddings[0]) if embeddings else None\\n\\n        for i, text in enumerate(texts):\\n            metadata = metadatas[i] if metadatas else {}\\n            if vector_dimensions is not None and \\\"embedding_dimensions\\\" not in metadata:\\n                metadata = {**metadata, \\\"embedding_dimensions\\\": vector_dimensions}\\n\\n            # Normalize ACL fields that may arrive as JSON strings from flows\\n            for key in (\\\"allowed_users\\\", \\\"allowed_groups\\\"):\\n                value = metadata.get(key)\\n                if isinstance(value, str):\\n                    try:\\n                        parsed = json.loads(value)\\n                        if isinstance(parsed, list):\\n                            metadata[key] = parsed\\n                    except (json.JSONDecodeError, TypeError):\\n                        # Leave value as-is if it isn't valid JSON\\n                        pass\\n\\n            _id = ids[i] if ids else str(uuid.uuid4())\\n            request = {\\n                \\\"_op_type\\\": \\\"index\\\",\\n                \\\"_index\\\": index_name,\\n                vector_field: embeddings[i],\\n                text_field: text,\\n                \\\"embedding_model\\\": embedding_model,  # Track which model was used\\n                **metadata,\\n            }\\n            if is_aoss:\\n                request[\\\"id\\\"] = _id\\n            else:\\n                request[\\\"_id\\\"] = _id\\n            requests.append(request)\\n            return_ids.append(_id)\\n        if metadatas:\\n            self.log(f\\\"Sample metadata: {metadatas[0] if metadatas else {}}\\\")\\n        helpers.bulk(client, requests, max_chunk_bytes=max_chunk_bytes)\\n        return return_ids\\n\\n    # ---------- param helpers ----------\\n    def _parse_int_param(self, attr_name: str, default: int) -> int:\\n        \\\"\\\"\\\"Parse a string attribute to int, returning *default* on failure.\\\"\\\"\\\"\\n        raw = getattr(self, attr_name, None)\\n        if raw is None or str(raw).strip() == \\\"\\\":\\n            return default\\n        try:\\n            value = int(str(raw).strip())\\n        except ValueError:\\n            logger.warning(f\\\"Invalid integer value '{raw}' for {attr_name}, using default {default}\\\")\\n            return default\\n\\n        if value < 0:\\n            logger.warning(f\\\"Negative value '{raw}' for {attr_name}, using default {default}\\\")\\n            return default\\n\\n        return value\\n\\n    # ---------- auth / client ----------\\n    def _build_auth_kwargs(self) -> dict[str, Any]:\\n        \\\"\\\"\\\"Build authentication configuration for OpenSearch client.\\n\\n        Constructs the appropriate authentication parameters based on the\\n        selected auth mode (basic username/password or JWT token).\\n\\n        Returns:\\n            Dictionary containing authentication configuration\\n\\n        Raises:\\n            ValueError: If required authentication parameters are missing\\n        \\\"\\\"\\\"\\n        mode = (self.auth_mode or \\\"basic\\\").strip().lower()\\n        if mode == \\\"jwt\\\":\\n            token = (self.jwt_token or \\\"\\\").strip()\\n            if not token:\\n                msg = \\\"Auth Mode is 'jwt' but no jwt_token was provided.\\\"\\n                raise ValueError(msg)\\n            header_name = (self.jwt_header or \\\"Authorization\\\").strip()\\n            header_value = f\\\"Bearer {token}\\\" if self.bearer_prefix else token\\n            return {\\\"headers\\\": {header_name: header_value}}\\n        user = (self.username or \\\"\\\").strip()\\n        pwd = (self.password or \\\"\\\").strip()\\n        if not user or not pwd:\\n            msg = \\\"Auth Mode is 'basic' but username/password are missing.\\\"\\n            raise ValueError(msg)\\n        return {\\\"http_auth\\\": (user, pwd)}\\n\\n    def build_client(self) -> OpenSearch:\\n        \\\"\\\"\\\"Create and configure an OpenSearch client instance.\\n\\n        Returns:\\n            Configured OpenSearch client ready for operations\\n        \\\"\\\"\\\"\\n        logger.debug(\\\"[OpenSearchMultimodel] Building OpenSearch client\\\")\\n        auth_kwargs = self._build_auth_kwargs()\\n        return OpenSearch(\\n            hosts=[self.opensearch_url],\\n            use_ssl=self.use_ssl,\\n            verify_certs=self.verify_certs,\\n            ssl_assert_hostname=False,\\n            ssl_show_warn=False,\\n            timeout=self._parse_int_param(\\\"request_timeout\\\", REQUEST_TIMEOUT),\\n            max_retries=self._parse_int_param(\\\"max_retries\\\", MAX_RETRIES),\\n            retry_on_timeout=True,\\n            **auth_kwargs,\\n        )\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self) -> OpenSearch:\\n        # Return raw OpenSearch client as our \\\"vector store.\\\"\\n        client = self.build_client()\\n\\n        # Check if we're in ingestion-only mode (no search query)\\n        has_search_query = bool((self.search_query or \\\"\\\").strip())\\n        if not has_search_query:\\n            logger.debug(\\\"[OpenSearchMultimodel] Ingestion-only mode activated: search operations will be skipped\\\")\\n            logger.debug(\\\"[OpenSearchMultimodel] Starting ingestion mode...\\\")\\n\\n        logger.debug(f\\\"[OpenSearchMultimodel] Embedding: {self.embedding}\\\")\\n        self._add_documents_to_vector_store(client=client)\\n        return client\\n\\n    # ---------- ingest ----------\\n    def _add_documents_to_vector_store(self, client: OpenSearch) -> None:\\n        \\\"\\\"\\\"Process and ingest documents into the OpenSearch vector store.\\n\\n        This method handles the complete document ingestion pipeline:\\n        - Prepares document data and metadata\\n        - Generates vector embeddings using the selected model\\n        - Creates appropriate index mappings with dynamic field names\\n        - Bulk inserts documents with vectors and model tracking\\n\\n        Args:\\n            client: OpenSearch client for performing operations\\n        \\\"\\\"\\\"\\n        logger.debug(\\\"[OpenSearchMultimodel][INGESTION] _add_documents_to_vector_store called\\\")\\n        # Convert DataFrame to Data if needed using parent's method\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        logger.debug(\\n            f\\\"[OpenSearchMultimodel][INGESTION] ingest_data type: \\\"\\n            f\\\"{type(self.ingest_data)}, length: {len(self.ingest_data) if self.ingest_data else 0}\\\"\\n        )\\n        logger.debug(\\n            f\\\"[OpenSearchMultimodel][INGESTION] ingest_data content: \\\"\\n            f\\\"{self.ingest_data[:2] if self.ingest_data and len(self.ingest_data) > 0 else 'empty'}\\\"\\n        )\\n\\n        docs = self.ingest_data or []\\n        if not docs:\\n            logger.debug(\\\"Ingestion complete: No documents provided\\\")\\n            return\\n\\n        if not self.embedding:\\n            msg = \\\"Embedding handle is required to embed documents.\\\"\\n            raise ValueError(msg)\\n\\n        # Normalize embedding to list first\\n        embeddings_list = self.embedding if isinstance(self.embedding, list) else [self.embedding]\\n\\n        # Filter out None values (fail-safe mode) - do this BEFORE checking if empty\\n        embeddings_list = [e for e in embeddings_list if e is not None]\\n\\n        # NOW check if we have any valid embeddings left after filtering\\n        if not embeddings_list:\\n            logger.warning(\\\"All embeddings returned None (fail-safe mode enabled). Skipping document ingestion.\\\")\\n            self.log(\\\"Embedding returned None (fail-safe mode enabled). Skipping document ingestion.\\\")\\n            return\\n\\n        logger.debug(f\\\"[OpenSearchMultimodel][INGESTION] Valid embeddings after filtering: {len(embeddings_list)}\\\")\\n        self.log(f\\\"[OpenSearchMultimodel][INGESTION] Available embedding models: {len(embeddings_list)}\\\")\\n\\n        # Select the embedding to use for ingestion\\n        selected_embedding = None\\n        embedding_model = None\\n\\n        # If embedding_model_name is specified, find matching embedding\\n        if hasattr(self, \\\"embedding_model_name\\\") and self.embedding_model_name and self.embedding_model_name.strip():\\n            target_model_name = self.embedding_model_name.strip()\\n            self.log(f\\\"Looking for embedding model: {target_model_name}\\\")\\n\\n            for emb_obj in embeddings_list:\\n                # Check all possible model identifiers (deployment, model, model_id, model_name)\\n                # Also check available_models list from EmbeddingsWithModels\\n                possible_names = []\\n                deployment = getattr(emb_obj, \\\"deployment\\\", None)\\n                model = getattr(emb_obj, \\\"model\\\", None)\\n                model_id = getattr(emb_obj, \\\"model_id\\\", None)\\n                model_name = getattr(emb_obj, \\\"model_name\\\", None)\\n                available_models_attr = getattr(emb_obj, \\\"available_models\\\", None)\\n\\n                if deployment:\\n                    possible_names.append(str(deployment))\\n                if model:\\n                    possible_names.append(str(model))\\n                if model_id:\\n                    possible_names.append(str(model_id))\\n                if model_name:\\n                    possible_names.append(str(model_name))\\n\\n                # Also add combined identifier\\n                if deployment and model and deployment != model:\\n                    possible_names.append(f\\\"{deployment}:{model}\\\")\\n\\n                # Add all models from available_models dict\\n                if available_models_attr and isinstance(available_models_attr, dict):\\n                    possible_names.extend(\\n                        str(model_key).strip()\\n                        for model_key in available_models_attr\\n                        if model_key and str(model_key).strip()\\n                    )\\n\\n                # Match if target matches any of the possible names\\n                if target_model_name in possible_names:\\n                    # Check if target is in available_models dict - use dedicated instance\\n                    if (\\n                        available_models_attr\\n                        and isinstance(available_models_attr, dict)\\n                        and target_model_name in available_models_attr\\n                    ):\\n                        # Use the dedicated embedding instance from the dict\\n                        selected_embedding = available_models_attr[target_model_name]\\n                        embedding_model = target_model_name\\n                        self.log(f\\\"Found dedicated embedding instance for '{embedding_model}' in available_models dict\\\")\\n                    else:\\n                        # Traditional identifier match\\n                        selected_embedding = emb_obj\\n                        embedding_model = self._get_embedding_model_name(emb_obj)\\n                        self.log(f\\\"Found matching embedding model: {embedding_model} (matched on: {target_model_name})\\\")\\n                    break\\n\\n            if not selected_embedding:\\n                # Build detailed list of available embeddings with all their identifiers\\n                available_info = []\\n                for idx, emb in enumerate(embeddings_list):\\n                    emb_type = type(emb).__name__\\n                    identifiers = []\\n                    deployment = getattr(emb, \\\"deployment\\\", None)\\n                    model = getattr(emb, \\\"model\\\", None)\\n                    model_id = getattr(emb, \\\"model_id\\\", None)\\n                    model_name = getattr(emb, \\\"model_name\\\", None)\\n                    available_models_attr = getattr(emb, \\\"available_models\\\", None)\\n\\n                    if deployment:\\n                        identifiers.append(f\\\"deployment='{deployment}'\\\")\\n                    if model:\\n                        identifiers.append(f\\\"model='{model}'\\\")\\n                    if model_id:\\n                        identifiers.append(f\\\"model_id='{model_id}'\\\")\\n                    if model_name:\\n                        identifiers.append(f\\\"model_name='{model_name}'\\\")\\n\\n                    # Add combined identifier as an option\\n                    if deployment and model and deployment != model:\\n                        identifiers.append(f\\\"combined='{deployment}:{model}'\\\")\\n\\n                    # Add available_models dict if present\\n                    if available_models_attr and isinstance(available_models_attr, dict):\\n                        identifiers.append(f\\\"available_models={list(available_models_attr.keys())}\\\")\\n\\n                    available_info.append(\\n                        f\\\"  [{idx}] {emb_type}: {', '.join(identifiers) if identifiers else 'No identifiers'}\\\"\\n                    )\\n\\n                msg = (\\n                    f\\\"Embedding model '{target_model_name}' not found in available embeddings.\\\\n\\\\n\\\"\\n                    f\\\"Available embeddings:\\\\n\\\" + \\\"\\\\n\\\".join(available_info) + \\\"\\\\n\\\\n\\\"\\n                    \\\"Please set 'embedding_model_name' to one of the identifier values shown above \\\"\\n                    \\\"(use the value after the '=' sign, without quotes).\\\\n\\\"\\n                    \\\"For duplicate deployments, use the 'combined' format.\\\\n\\\"\\n                    \\\"Or leave it empty to use the first embedding.\\\"\\n                )\\n                raise ValueError(msg)\\n        else:\\n            # Use first embedding if no model name specified\\n            selected_embedding = embeddings_list[0]\\n            embedding_model = self._get_embedding_model_name(selected_embedding)\\n            self.log(f\\\"No embedding_model_name specified, using first embedding: {embedding_model}\\\")\\n\\n        dynamic_field_name = get_embedding_field_name(embedding_model)\\n\\n        logger.info(f\\\"Selected embedding model for ingestion: '{embedding_model}'\\\")\\n        self.log(f\\\"Using embedding model for ingestion: {embedding_model}\\\")\\n        self.log(f\\\"Dynamic vector field: {dynamic_field_name}\\\")\\n\\n        # Log embedding details for debugging\\n        if hasattr(selected_embedding, \\\"deployment\\\"):\\n            logger.info(f\\\"Embedding deployment: {selected_embedding.deployment}\\\")\\n        if hasattr(selected_embedding, \\\"model\\\"):\\n            logger.info(f\\\"Embedding model: {selected_embedding.model}\\\")\\n        if hasattr(selected_embedding, \\\"model_id\\\"):\\n            logger.info(f\\\"Embedding model_id: {selected_embedding.model_id}\\\")\\n        if hasattr(selected_embedding, \\\"dimensions\\\"):\\n            logger.info(f\\\"Embedding dimensions: {selected_embedding.dimensions}\\\")\\n        if hasattr(selected_embedding, \\\"available_models\\\"):\\n            logger.info(f\\\"Embedding available_models: {selected_embedding.available_models}\\\")\\n\\n        # No model switching needed - each model in available_models has its own dedicated instance\\n        # The selected_embedding is already configured correctly for the target model\\n        logger.info(f\\\"Using embedding instance for '{embedding_model}' - pre-configured and ready to use\\\")\\n\\n        # Extract texts and metadata from documents\\n        texts = []\\n        metadatas = []\\n        # Process docs_metadata table input into a dict\\n        additional_metadata = {}\\n        logger.debug(f\\\"[LF] Docs metadata {self.docs_metadata}\\\")\\n        if hasattr(self, \\\"docs_metadata\\\") and self.docs_metadata:\\n            logger.info(f\\\"[LF] Docs metadata {self.docs_metadata}\\\")\\n            if isinstance(self.docs_metadata[-1], Data):\\n                logger.info(f\\\"[LF] Docs metadata is a Data object {self.docs_metadata}\\\")\\n                self.docs_metadata = self.docs_metadata[-1].data\\n                logger.info(f\\\"[LF] Docs metadata is a Data object {self.docs_metadata}\\\")\\n                additional_metadata.update(self.docs_metadata)\\n            else:\\n                for item in self.docs_metadata:\\n                    if isinstance(item, dict) and \\\"key\\\" in item and \\\"value\\\" in item:\\n                        additional_metadata[item[\\\"key\\\"]] = item[\\\"value\\\"]\\n        # Replace string \\\"None\\\" values with actual None\\n        for key, value in additional_metadata.items():\\n            if value == \\\"None\\\":\\n                additional_metadata[key] = None\\n        logger.info(f\\\"[LF] Additional metadata {additional_metadata}\\\")\\n        for doc_obj in docs:\\n            data_copy = json.loads(doc_obj.model_dump_json())\\n            text = data_copy.pop(doc_obj.text_key, doc_obj.default_value)\\n            texts.append(text)\\n\\n            # Merge additional metadata from table input\\n            data_copy.update(additional_metadata)\\n\\n            metadatas.append(data_copy)\\n        self.log(metadatas)\\n\\n        # Generate embeddings with rate-limit-aware retry logic using tenacity\\n        from tenacity import (\\n            retry,\\n            retry_if_exception,\\n            stop_after_attempt,\\n            wait_exponential,\\n        )\\n\\n        def is_rate_limit_error(exception: Exception) -> bool:\\n            \\\"\\\"\\\"Check if exception is a rate limit error (429).\\\"\\\"\\\"\\n            error_str = str(exception).lower()\\n            return \\\"429\\\" in error_str or \\\"rate_limit\\\" in error_str or \\\"rate limit\\\" in error_str\\n\\n        def is_other_retryable_error(exception: Exception) -> bool:\\n            \\\"\\\"\\\"Check if exception is retryable but not a rate limit error.\\\"\\\"\\\"\\n            # Retry on most exceptions except for specific non-retryable ones\\n            # Add other non-retryable exceptions here if needed\\n            return not is_rate_limit_error(exception)\\n\\n        # Create retry decorator for rate limit errors (longer backoff)\\n        retry_on_rate_limit = retry(\\n            retry=retry_if_exception(is_rate_limit_error),\\n            stop=stop_after_attempt(5),\\n            wait=wait_exponential(multiplier=2, min=2, max=30),\\n            reraise=True,\\n            before_sleep=lambda retry_state: logger.warning(\\n                f\\\"Rate limit hit for chunk (attempt {retry_state.attempt_number}/5), \\\"\\n                f\\\"backing off for {retry_state.next_action.sleep:.1f}s\\\"\\n            ),\\n        )\\n\\n        # Create retry decorator for other errors (shorter backoff)\\n        retry_on_other_errors = retry(\\n            retry=retry_if_exception(is_other_retryable_error),\\n            stop=stop_after_attempt(3),\\n            wait=wait_exponential(multiplier=1, min=1, max=8),\\n            reraise=True,\\n            before_sleep=lambda retry_state: logger.warning(\\n                f\\\"Error embedding chunk (attempt {retry_state.attempt_number}/3), \\\"\\n                f\\\"retrying in {retry_state.next_action.sleep:.1f}s: {retry_state.outcome.exception()}\\\"\\n            ),\\n        )\\n\\n        def embed_chunk_with_retry(chunk_text: str, chunk_idx: int) -> list[float]:\\n            \\\"\\\"\\\"Embed a single chunk with rate-limit-aware retry logic.\\\"\\\"\\\"\\n\\n            @retry_on_rate_limit\\n            @retry_on_other_errors\\n            def _embed(text: str) -> list[float]:\\n                return selected_embedding.embed_documents([text])[0]\\n\\n            try:\\n                return _embed(chunk_text)\\n            except Exception as e:\\n                logger.error(\\n                    f\\\"Failed to embed chunk {chunk_idx} after all retries: {e}\\\",\\n                    error=str(e),\\n                )\\n                raise\\n\\n        # Restrict concurrency for IBM/Watsonx models to avoid rate limits\\n        is_ibm = (embedding_model and \\\"ibm\\\" in str(embedding_model).lower()) or (\\n            selected_embedding and \\\"watsonx\\\" in type(selected_embedding).__name__.lower()\\n        )\\n        logger.debug(f\\\"Is IBM: {is_ibm}\\\")\\n\\n        # For IBM models, use sequential processing with rate limiting\\n        # For other models, use parallel processing\\n        vectors: list[list[float]] = [None] * len(texts)\\n\\n        if is_ibm:\\n            # Sequential processing with inter-request delay for IBM models\\n            inter_request_delay = 0.6  # ~1.67 req/s, safely under 2 req/s limit\\n            logger.info(f\\\"Using sequential processing for IBM model with {inter_request_delay}s delay between requests\\\")\\n\\n            for idx, chunk in enumerate(texts):\\n                if idx > 0:\\n                    # Add delay between requests (but not before the first one)\\n                    time.sleep(inter_request_delay)\\n                vectors[idx] = embed_chunk_with_retry(chunk, idx)\\n        else:\\n            # Parallel processing for non-IBM models\\n            max_workers = min(max(len(texts), 1), 8)\\n            logger.debug(f\\\"Using parallel processing with {max_workers} workers\\\")\\n\\n            with ThreadPoolExecutor(max_workers=max_workers) as executor:\\n                futures = {executor.submit(embed_chunk_with_retry, chunk, idx): idx for idx, chunk in enumerate(texts)}\\n                for future in as_completed(futures):\\n                    idx = futures[future]\\n                    vectors[idx] = future.result()\\n\\n        if not vectors:\\n            self.log(f\\\"No vectors generated from documents for model {embedding_model}.\\\")\\n            return\\n\\n        # Get vector dimension for mapping\\n        dim = len(vectors[0]) if vectors else 768  # default fallback\\n\\n        # Check for AOSS\\n        auth_kwargs = self._build_auth_kwargs()\\n        is_aoss = self._is_aoss_enabled(auth_kwargs.get(\\\"http_auth\\\"))\\n\\n        # Validate engine with AOSS\\n        engine = getattr(self, \\\"engine\\\", \\\"jvector\\\")\\n        self._validate_aoss_with_engines(is_aoss=is_aoss, engine=engine)\\n\\n        # Create mapping with proper KNN settings\\n        space_type = getattr(self, \\\"space_type\\\", \\\"l2\\\")\\n        ef_construction = getattr(self, \\\"ef_construction\\\", 512)\\n        m = getattr(self, \\\"m\\\", 16)\\n\\n        mapping = self._default_text_mapping(\\n            dim=dim,\\n            engine=engine,\\n            space_type=space_type,\\n            ef_construction=ef_construction,\\n            m=m,\\n            vector_field=dynamic_field_name,  # Use dynamic field name\\n        )\\n\\n        # Ensure index exists with baseline mapping (index.knn: true is required for vector search)\\n        try:\\n            if not client.indices.exists(index=self.index_name):\\n                self.log(f\\\"Creating index '{self.index_name}' with base mapping\\\")\\n                client.indices.create(index=self.index_name, body=mapping)\\n        except RequestError as creation_error:\\n            if creation_error.error == \\\"resource_already_exists_exception\\\":\\n                pass  # Index was created concurrently\\n            else:\\n                error_msg = str(creation_error).lower()\\n                if \\\"invalid engine\\\" in error_msg or \\\"illegal_argument\\\" in error_msg:\\n                    if \\\"jvector\\\" in error_msg:\\n                        msg = (\\n                            \\\"The 'jvector' engine is not available in your OpenSearch installation. \\\"\\n                            \\\"Use 'nmslib' or 'faiss' for standard OpenSearch, or upgrade to 2.9+.\\\"\\n                        )\\n                        raise ValueError(msg) from creation_error\\n                    if \\\"index.knn\\\" in error_msg:\\n                        msg = (\\n                            \\\"The index has index.knn: false. Delete the existing index and let the \\\"\\n                            \\\"component recreate it, or create a new index with a different name.\\\"\\n                        )\\n                        raise ValueError(msg) from creation_error\\n                logger.warning(f\\\"Failed to create index '{self.index_name}': {creation_error}\\\")\\n                raise\\n\\n        # Ensure the dynamic field exists in the index\\n        self._ensure_embedding_field_mapping(\\n            client=client,\\n            index_name=self.index_name,\\n            field_name=dynamic_field_name,\\n            dim=dim,\\n            engine=engine,\\n            space_type=space_type,\\n            ef_construction=ef_construction,\\n            m=m,\\n        )\\n\\n        self.log(f\\\"Indexing {len(texts)} documents into '{self.index_name}' with model '{embedding_model}'...\\\")\\n        logger.info(f\\\"Will store embeddings in field: {dynamic_field_name}\\\")\\n        logger.info(f\\\"Will tag documents with embedding_model: {embedding_model}\\\")\\n\\n        # Use the bulk ingestion with model tracking\\n        return_ids = self._bulk_ingest_embeddings(\\n            client=client,\\n            index_name=self.index_name,\\n            embeddings=vectors,\\n            texts=texts,\\n            metadatas=metadatas,\\n            vector_field=dynamic_field_name,  # Use dynamic field name\\n            text_field=\\\"text\\\",\\n            embedding_model=embedding_model,  # Track the model\\n            mapping=mapping,\\n            is_aoss=is_aoss,\\n        )\\n        self.log(metadatas)\\n\\n        logger.info(\\n            f\\\"Ingestion complete: Successfully indexed {len(return_ids)} documents with model '{embedding_model}'\\\"\\n        )\\n        self.log(f\\\"Successfully indexed {len(return_ids)} documents with model {embedding_model}.\\\")\\n\\n    # ---------- helpers for filters ----------\\n    def _is_placeholder_term(self, term_obj: dict) -> bool:\\n        # term_obj like {\\\"filename\\\": \\\"__IMPOSSIBLE_VALUE__\\\"}\\n        return any(v == \\\"__IMPOSSIBLE_VALUE__\\\" for v in term_obj.values())\\n\\n    def _coerce_filter_clauses(self, filter_obj: dict | None) -> list[dict]:\\n        \\\"\\\"\\\"Convert filter expressions into OpenSearch-compatible filter clauses.\\n\\n        This method accepts two filter formats and converts them to standardized\\n        OpenSearch query clauses:\\n\\n        Format A - Explicit filters:\\n        {\\\"filter\\\": [{\\\"term\\\": {\\\"field\\\": \\\"value\\\"}}, {\\\"terms\\\": {\\\"field\\\": [\\\"val1\\\", \\\"val2\\\"]}}],\\n         \\\"limit\\\": 10, \\\"score_threshold\\\": 1.5}\\n\\n        Format B - Context-style mapping:\\n        {\\\"data_sources\\\": [\\\"file1.pdf\\\"], \\\"document_types\\\": [\\\"pdf\\\"], \\\"owners\\\": [\\\"user1\\\"]}\\n\\n        Args:\\n            filter_obj: Filter configuration dictionary or None\\n\\n        Returns:\\n            List of OpenSearch filter clauses (term/terms objects)\\n            Placeholder values with \\\"__IMPOSSIBLE_VALUE__\\\" are ignored\\n        \\\"\\\"\\\"\\n        if not filter_obj:\\n            return []\\n\\n        # If it is a string, try to parse it once\\n        if isinstance(filter_obj, str):\\n            try:\\n                filter_obj = json.loads(filter_obj)\\n            except json.JSONDecodeError:\\n                # Not valid JSON - treat as no filters\\n                return []\\n\\n        # Case A: already an explicit list/dict under \\\"filter\\\"\\n        if \\\"filter\\\" in filter_obj:\\n            raw = filter_obj[\\\"filter\\\"]\\n            if isinstance(raw, dict):\\n                raw = [raw]\\n            explicit_clauses: list[dict] = []\\n            for f in raw or []:\\n                if \\\"term\\\" in f and isinstance(f[\\\"term\\\"], dict) and not self._is_placeholder_term(f[\\\"term\\\"]):\\n                    explicit_clauses.append(f)\\n                elif \\\"terms\\\" in f and isinstance(f[\\\"terms\\\"], dict):\\n                    field, vals = next(iter(f[\\\"terms\\\"].items()))\\n                    if isinstance(vals, list) and len(vals) > 0:\\n                        explicit_clauses.append(f)\\n            return explicit_clauses\\n\\n        # Case B: convert context-style maps into clauses\\n        field_mapping = {\\n            \\\"data_sources\\\": \\\"filename\\\",\\n            \\\"document_types\\\": \\\"mimetype\\\",\\n            \\\"owners\\\": \\\"owner\\\",\\n        }\\n        context_clauses: list[dict] = []\\n        for k, values in filter_obj.items():\\n            if not isinstance(values, list):\\n                continue\\n            field = field_mapping.get(k, k)\\n            if len(values) == 0:\\n                # Match-nothing placeholder (kept to mirror your tool semantics)\\n                context_clauses.append({\\\"term\\\": {field: \\\"__IMPOSSIBLE_VALUE__\\\"}})\\n            elif len(values) == 1:\\n                if values[0] != \\\"__IMPOSSIBLE_VALUE__\\\":\\n                    context_clauses.append({\\\"term\\\": {field: values[0]}})\\n            else:\\n                context_clauses.append({\\\"terms\\\": {field: values}})\\n        return context_clauses\\n\\n    def _parse_filter_expression(self) -> dict | None:\\n        \\\"\\\"\\\"Parse and validate optional filter_expression JSON.\\n\\n        Returns:\\n            Parsed JSON object as a dict, or None when unset/blank.\\n\\n        Raises:\\n            ValueError: If JSON is invalid or does not decode to an object.\\n        \\\"\\\"\\\"\\n        filter_expression = getattr(self, \\\"filter_expression\\\", \\\"\\\")\\n        if not isinstance(filter_expression, str) or not filter_expression.strip():\\n            return None\\n        try:\\n            filter_obj = json.loads(filter_expression)\\n        except json.JSONDecodeError as e:\\n            msg = f\\\"Invalid filter_expression JSON: {e}\\\"\\n            raise ValueError(msg) from e\\n\\n        if not isinstance(filter_obj, dict):\\n            msg = \\\"Invalid filter_expression JSON type: expected a JSON object.\\\"\\n            raise TypeError(msg)\\n        return filter_obj\\n\\n    def _resolve_limit(self, filter_obj: dict | None, default_limit: int | None) -> int | None:\\n        \\\"\\\"\\\"Resolve an integer result limit from filter settings.\\\"\\\"\\\"\\n        if not filter_obj:\\n            return default_limit\\n        raw_limit = filter_obj.get(\\\"limit\\\", default_limit)\\n        if raw_limit is None:\\n            return None\\n        if isinstance(raw_limit, bool):\\n            msg = \\\"Invalid filter_expression.limit: expected a positive integer.\\\"\\n            raise TypeError(msg)\\n        try:\\n            limit = int(raw_limit)\\n        except (TypeError, ValueError) as e:\\n            msg = \\\"Invalid filter_expression.limit: expected a positive integer.\\\"\\n            raise ValueError(msg) from e\\n        if limit <= 0:\\n            msg = \\\"Invalid filter_expression.limit: expected a positive integer.\\\"\\n            raise ValueError(msg)\\n        return limit\\n\\n    def _resolve_score_threshold(self, filter_obj: dict | None) -> float | None:\\n        \\\"\\\"\\\"Resolve optional positive min score from filter settings.\\\"\\\"\\\"\\n        if not filter_obj:\\n            return None\\n        score_threshold = filter_obj.get(\\\"score_threshold\\\")\\n        if score_threshold is None:\\n            score_threshold = filter_obj.get(\\\"scoreThreshold\\\")\\n        if not isinstance(score_threshold, (int, float)) or score_threshold <= 0:\\n            return None\\n        return float(score_threshold)\\n\\n    def _detect_available_models(self, client: OpenSearch, filter_clauses: list[dict] | None = None) -> list[str]:\\n        \\\"\\\"\\\"Detect which embedding models have documents in the index.\\n\\n        Uses aggregation to find all unique embedding_model values, optionally\\n        filtered to only documents matching the user's filter criteria.\\n\\n        Args:\\n            client: OpenSearch client instance\\n            filter_clauses: Optional filter clauses to scope model detection\\n\\n        Returns:\\n            List of embedding model names found in the index\\n        \\\"\\\"\\\"\\n        try:\\n            agg_query = {\\\"size\\\": 0, \\\"aggs\\\": {\\\"embedding_models\\\": {\\\"terms\\\": {\\\"field\\\": \\\"embedding_model\\\", \\\"size\\\": 10}}}}\\n\\n            # Apply filters to model detection if any exist\\n            if filter_clauses:\\n                agg_query[\\\"query\\\"] = {\\\"bool\\\": {\\\"filter\\\": filter_clauses}}\\n\\n            logger.debug(f\\\"Model detection query: {agg_query}\\\")\\n            result = client.search(\\n                index=self.index_name,\\n                body=agg_query,\\n                params={\\\"terminate_after\\\": 0},\\n            )\\n            buckets = result.get(\\\"aggregations\\\", {}).get(\\\"embedding_models\\\", {}).get(\\\"buckets\\\", [])\\n            models = [b[\\\"key\\\"] for b in buckets if b[\\\"key\\\"]]\\n\\n            # Log detailed bucket info for debugging\\n            logger.info(\\n                f\\\"Detected embedding models in corpus: {models}\\\"\\n                + (f\\\" (with {len(filter_clauses)} filters)\\\" if filter_clauses else \\\"\\\")\\n            )\\n            if not models:\\n                total_hits = result.get(\\\"hits\\\", {}).get(\\\"total\\\", {})\\n                total_count = total_hits.get(\\\"value\\\", 0) if isinstance(total_hits, dict) else total_hits\\n                logger.warning(\\n                    f\\\"No embedding_model values found in index '{self.index_name}'. \\\"\\n                    f\\\"Total docs in index: {total_count}. \\\"\\n                    f\\\"This may indicate documents were indexed without the embedding_model field.\\\"\\n                )\\n        except (OpenSearchException, KeyError, ValueError) as e:\\n            logger.warning(f\\\"Failed to detect embedding models: {e}\\\")\\n            # Fallback to current model\\n            fallback_model = self._get_embedding_model_name()\\n            logger.info(f\\\"Using fallback model: {fallback_model}\\\")\\n            return [fallback_model]\\n        else:\\n            return models\\n\\n    def _get_index_properties(self, client: OpenSearch) -> dict[str, Any] | None:\\n        \\\"\\\"\\\"Retrieve flattened mapping properties for the current index.\\\"\\\"\\\"\\n        try:\\n            mapping = client.indices.get_mapping(index=self.index_name)\\n        except OpenSearchException as e:\\n            logger.warning(\\n                f\\\"Failed to fetch mapping for index '{self.index_name}': {e}. Proceeding without mapping metadata.\\\"\\n            )\\n            return None\\n\\n        properties: dict[str, Any] = {}\\n        for index_data in mapping.values():\\n            props = index_data.get(\\\"mappings\\\", {}).get(\\\"properties\\\", {})\\n            if isinstance(props, dict):\\n                properties.update(props)\\n        return properties\\n\\n    def _is_knn_vector_field(self, properties: dict[str, Any] | None, field_name: str) -> bool:\\n        \\\"\\\"\\\"Check whether the field is mapped as a knn_vector.\\\"\\\"\\\"\\n        if not field_name:\\n            return False\\n        if properties is None:\\n            logger.warning(f\\\"Mapping metadata unavailable; assuming field '{field_name}' is usable.\\\")\\n            return True\\n        field_def = properties.get(field_name)\\n        if not isinstance(field_def, dict):\\n            return False\\n        if field_def.get(\\\"type\\\") == \\\"knn_vector\\\":\\n            return True\\n\\n        nested_props = field_def.get(\\\"properties\\\")\\n        return bool(isinstance(nested_props, dict) and nested_props.get(\\\"type\\\") == \\\"knn_vector\\\")\\n\\n    def _get_field_dimension(self, properties: dict[str, Any] | None, field_name: str) -> int | None:\\n        \\\"\\\"\\\"Get the dimension of a knn_vector field from the index mapping.\\n\\n        Args:\\n            properties: Index properties from mapping\\n            field_name: Name of the vector field\\n\\n        Returns:\\n            Dimension of the field, or None if not found\\n        \\\"\\\"\\\"\\n        if not field_name or properties is None:\\n            return None\\n\\n        field_def = properties.get(field_name)\\n        if not isinstance(field_def, dict):\\n            return None\\n\\n        # Check direct knn_vector field\\n        if field_def.get(\\\"type\\\") == \\\"knn_vector\\\":\\n            return field_def.get(\\\"dimension\\\")\\n\\n        # Check nested properties\\n        nested_props = field_def.get(\\\"properties\\\")\\n        if isinstance(nested_props, dict) and nested_props.get(\\\"type\\\") == \\\"knn_vector\\\":\\n            return nested_props.get(\\\"dimension\\\")\\n\\n        return None\\n\\n    def _get_filename_agg_field(self, index_properties: dict[str, Any] | None) -> str:\\n        \\\"\\\"\\\"Choose the appropriate field for filename aggregations.\\\"\\\"\\\"\\n        if not index_properties:\\n            return \\\"filename.keyword\\\"\\n\\n        filename_def = index_properties.get(\\\"filename\\\")\\n        if not isinstance(filename_def, dict):\\n            return \\\"filename.keyword\\\"\\n\\n        field_type = filename_def.get(\\\"type\\\")\\n        fields_def = filename_def.get(\\\"fields\\\", {})\\n\\n        # Top-level keyword with no subfields\\n        if field_type == \\\"keyword\\\" and not isinstance(fields_def, dict):\\n            return \\\"filename\\\"\\n\\n        # Text field with keyword subfield\\n        if isinstance(fields_def, dict) and \\\"keyword\\\" in fields_def:\\n            return \\\"filename.keyword\\\"\\n\\n        # Fallback: aggregate on filename directly\\n        return \\\"filename\\\"\\n\\n    # ---------- search (multi-model hybrid) ----------\\n    def search(self, query: str | None = None) -> list[dict[str, Any]]:\\n        \\\"\\\"\\\"Perform multi-model hybrid search combining multiple vector similarities and keyword matching.\\n\\n        This method executes a sophisticated search that:\\n        1. Auto-detects all embedding models present in the index\\n        2. Generates query embeddings for ALL detected models in parallel\\n        3. Combines multiple KNN queries using dis_max (picks best match)\\n        4. Adds keyword search with fuzzy matching (30% weight)\\n        5. Applies optional filtering and score thresholds\\n        6. Returns aggregations for faceted search\\n\\n        Search weights:\\n        - Semantic search (dis_max across all models): 70%\\n        - Keyword search: 30%\\n\\n        Args:\\n            query: Search query string (used for both vector embedding and keyword search)\\n\\n        Returns:\\n            List of search results with page_content, metadata, and relevance scores\\n\\n        Raises:\\n            ValueError: If embedding component is not provided or filter JSON is invalid\\n        \\\"\\\"\\\"\\n        logger.info(self.ingest_data)\\n        client = self.build_client()\\n        q = (query or \\\"\\\").strip()\\n\\n        # Parse optional filter expression\\n        filter_obj = self._parse_filter_expression()\\n\\n        if not self.embedding:\\n            msg = \\\"Embedding is required to run hybrid search (KNN + keyword).\\\"\\n            raise ValueError(msg)\\n\\n        # Check if embedding is None (fail-safe mode)\\n        if self.embedding is None or (isinstance(self.embedding, list) and all(e is None for e in self.embedding)):\\n            logger.error(\\\"Embedding returned None (fail-safe mode enabled). Cannot perform search.\\\")\\n            return []\\n\\n        # Build filter clauses first so we can use them in model detection\\n        filter_clauses = self._coerce_filter_clauses(filter_obj)\\n\\n        # Detect available embedding models in the index (scoped by filters)\\n        available_models = self._detect_available_models(client, filter_clauses)\\n\\n        if not available_models:\\n            logger.warning(\\\"No embedding models found in index, using current model\\\")\\n            available_models = [self._get_embedding_model_name()]\\n\\n        # Generate embeddings for ALL detected models\\n        query_embeddings = {}\\n\\n        # Normalize embedding to list\\n        embeddings_list = self.embedding if isinstance(self.embedding, list) else [self.embedding]\\n        # Filter out None values (fail-safe mode)\\n        embeddings_list = [e for e in embeddings_list if e is not None]\\n\\n        if not embeddings_list:\\n            logger.error(\\n                \\\"No valid embeddings available after filtering None values (fail-safe mode). Cannot perform search.\\\"\\n            )\\n            return []\\n\\n        # Create a comprehensive map of model names to embedding objects\\n        # Check all possible identifiers (deployment, model, model_id, model_name)\\n        # Also leverage available_models list from EmbeddingsWithModels\\n        # Handle duplicate identifiers by creating combined keys\\n        embedding_by_model = {}\\n        identifier_conflicts = {}  # Track which identifiers have conflicts\\n\\n        for idx, emb_obj in enumerate(embeddings_list):\\n            # Get all possible identifiers for this embedding\\n            identifiers = []\\n            deployment = getattr(emb_obj, \\\"deployment\\\", None)\\n            model = getattr(emb_obj, \\\"model\\\", None)\\n            model_id = getattr(emb_obj, \\\"model_id\\\", None)\\n            model_name = getattr(emb_obj, \\\"model_name\\\", None)\\n            dimensions = getattr(emb_obj, \\\"dimensions\\\", None)\\n            available_models_attr = getattr(emb_obj, \\\"available_models\\\", None)\\n\\n            logger.info(\\n                f\\\"Embedding object {idx}: deployment={deployment}, model={model}, \\\"\\n                f\\\"model_id={model_id}, model_name={model_name}, dimensions={dimensions}, \\\"\\n                f\\\"available_models={available_models_attr}\\\"\\n            )\\n\\n            # If this embedding has available_models dict, map all models to their dedicated instances\\n            if available_models_attr and isinstance(available_models_attr, dict):\\n                logger.info(\\n                    f\\\"Embedding object {idx} provides {len(available_models_attr)} models via available_models dict\\\"\\n                )\\n                for model_name_key, dedicated_embedding in available_models_attr.items():\\n                    if model_name_key and str(model_name_key).strip():\\n                        model_str = str(model_name_key).strip()\\n                        if model_str not in embedding_by_model:\\n                            # Use the dedicated embedding instance from the dict\\n                            embedding_by_model[model_str] = dedicated_embedding\\n                            logger.info(f\\\"Mapped available model '{model_str}' to dedicated embedding instance\\\")\\n                        else:\\n                            # Conflict detected - track it\\n                            if model_str not in identifier_conflicts:\\n                                identifier_conflicts[model_str] = [embedding_by_model[model_str]]\\n                            identifier_conflicts[model_str].append(dedicated_embedding)\\n                            logger.warning(f\\\"Available model '{model_str}' has conflict - used by multiple embeddings\\\")\\n\\n            # Also map traditional identifiers (for backward compatibility)\\n            if deployment:\\n                identifiers.append(str(deployment))\\n            if model:\\n                identifiers.append(str(model))\\n            if model_id:\\n                identifiers.append(str(model_id))\\n            if model_name:\\n                identifiers.append(str(model_name))\\n\\n            # Map all identifiers to this embedding object\\n            for identifier in identifiers:\\n                if identifier not in embedding_by_model:\\n                    embedding_by_model[identifier] = emb_obj\\n                    logger.info(f\\\"Mapped identifier '{identifier}' to embedding object {idx}\\\")\\n                else:\\n                    # Conflict detected - track it\\n                    if identifier not in identifier_conflicts:\\n                        identifier_conflicts[identifier] = [embedding_by_model[identifier]]\\n                    identifier_conflicts[identifier].append(emb_obj)\\n                    logger.warning(f\\\"Identifier '{identifier}' has conflict - used by multiple embeddings\\\")\\n\\n            # For embeddings with model+deployment, create combined identifier\\n            # This helps when deployment is the same but model differs\\n            if deployment and model and deployment != model:\\n                combined_id = f\\\"{deployment}:{model}\\\"\\n                if combined_id not in embedding_by_model:\\n                    embedding_by_model[combined_id] = emb_obj\\n                    logger.info(f\\\"Created combined identifier '{combined_id}' for embedding object {idx}\\\")\\n\\n        # Log conflicts\\n        if identifier_conflicts:\\n            logger.warning(\\n                f\\\"Found {len(identifier_conflicts)} conflicting identifiers. \\\"\\n                f\\\"Consider using combined format 'deployment:model' or specifying unique model names.\\\"\\n            )\\n            for conflict_id, emb_list in identifier_conflicts.items():\\n                logger.warning(f\\\"  Conflict on '{conflict_id}': {len(emb_list)} embeddings use this identifier\\\")\\n\\n        logger.info(f\\\"Generating embeddings for {len(available_models)} models in index\\\")\\n        logger.info(f\\\"Available embedding identifiers: {list(embedding_by_model.keys())}\\\")\\n        self.log(f\\\"[SEARCH] Models detected in index: {available_models}\\\")\\n        self.log(f\\\"[SEARCH] Available embedding identifiers: {list(embedding_by_model.keys())}\\\")\\n\\n        # Track matching status for debugging\\n        matched_models = []\\n        unmatched_models = []\\n\\n        for model_name in available_models:\\n            try:\\n                # Check if we have an embedding object for this model\\n                if model_name in embedding_by_model:\\n                    # Use the matching embedding object directly\\n                    emb_obj = embedding_by_model[model_name]\\n                    emb_deployment = getattr(emb_obj, \\\"deployment\\\", None)\\n                    emb_model = getattr(emb_obj, \\\"model\\\", None)\\n                    emb_model_id = getattr(emb_obj, \\\"model_id\\\", None)\\n                    emb_dimensions = getattr(emb_obj, \\\"dimensions\\\", None)\\n                    emb_available_models = getattr(emb_obj, \\\"available_models\\\", None)\\n\\n                    logger.info(\\n                        f\\\"Using embedding object for model '{model_name}': \\\"\\n                        f\\\"deployment={emb_deployment}, model={emb_model}, model_id={emb_model_id}, \\\"\\n                        f\\\"dimensions={emb_dimensions}\\\"\\n                    )\\n\\n                    # Check if this is a dedicated instance from available_models dict\\n                    if emb_available_models and isinstance(emb_available_models, dict):\\n                        logger.info(\\n                            f\\\"Model '{model_name}' using dedicated instance from available_models dict \\\"\\n                            f\\\"(pre-configured with correct model and dimensions)\\\"\\n                        )\\n\\n                    # Use the embedding instance directly - no model switching needed!\\n                    vec = emb_obj.embed_query(q)\\n                    query_embeddings[model_name] = vec\\n                    matched_models.append(model_name)\\n                    logger.info(f\\\"Generated embedding for model: {model_name} (actual dimensions: {len(vec)})\\\")\\n                    self.log(f\\\"[MATCH] Model '{model_name}' - generated {len(vec)}-dim embedding\\\")\\n                else:\\n                    # No matching embedding found for this model\\n                    unmatched_models.append(model_name)\\n                    logger.warning(\\n                        f\\\"No matching embedding found for model '{model_name}'. \\\"\\n                        f\\\"This model will be skipped. Available identifiers: {list(embedding_by_model.keys())}\\\"\\n                    )\\n                    self.log(f\\\"[NO MATCH] Model '{model_name}' - available: {list(embedding_by_model.keys())}\\\")\\n            except (RuntimeError, ValueError, ConnectionError, TimeoutError, AttributeError, KeyError) as e:\\n                logger.warning(f\\\"Failed to generate embedding for {model_name}: {e}\\\")\\n                self.log(f\\\"[ERROR] Embedding generation failed for '{model_name}': {e}\\\")\\n\\n        # Log summary of model matching\\n        logger.info(f\\\"Model matching summary: {len(matched_models)} matched, {len(unmatched_models)} unmatched\\\")\\n        self.log(f\\\"[SUMMARY] Model matching: {len(matched_models)} matched, {len(unmatched_models)} unmatched\\\")\\n        if unmatched_models:\\n            self.log(f\\\"[WARN] Unmatched models in index: {unmatched_models}\\\")\\n\\n        if not query_embeddings:\\n            msg = (\\n                f\\\"Failed to generate embeddings for any model. \\\"\\n                f\\\"Index has models: {available_models}, but no matching embedding objects found. \\\"\\n                f\\\"Available embedding identifiers: {list(embedding_by_model.keys())}\\\"\\n            )\\n            self.log(f\\\"[FAIL] Search failed: {msg}\\\")\\n            raise ValueError(msg)\\n\\n        index_properties = self._get_index_properties(client)\\n        legacy_vector_field = getattr(self, \\\"vector_field\\\", \\\"chunk_embedding\\\")\\n\\n        # Build KNN queries for each model\\n        embedding_fields: list[str] = []\\n        knn_queries_with_candidates = []\\n        knn_queries_without_candidates = []\\n\\n        raw_num_candidates = getattr(self, \\\"num_candidates\\\", 1000)\\n        try:\\n            num_candidates = int(raw_num_candidates) if raw_num_candidates is not None else 0\\n        except (TypeError, ValueError):\\n            num_candidates = 0\\n        use_num_candidates = num_candidates > 0\\n\\n        for model_name, embedding_vector in query_embeddings.items():\\n            field_name = get_embedding_field_name(model_name)\\n            selected_field = field_name\\n            vector_dim = len(embedding_vector)\\n\\n            # Only use the expected dynamic field - no legacy fallback\\n            # This prevents dimension mismatches between models\\n            if not self._is_knn_vector_field(index_properties, selected_field):\\n                logger.warning(\\n                    f\\\"Skipping model {model_name}: field '{field_name}' is not mapped as knn_vector. \\\"\\n                    f\\\"Documents must be indexed with this embedding model before querying.\\\"\\n                )\\n                self.log(f\\\"[SKIP] Field '{selected_field}' not a knn_vector - skipping model '{model_name}'\\\")\\n                continue\\n\\n            # Validate vector dimensions match the field dimensions\\n            field_dim = self._get_field_dimension(index_properties, selected_field)\\n            if field_dim is not None and field_dim != vector_dim:\\n                logger.error(\\n                    f\\\"Dimension mismatch for model '{model_name}': \\\"\\n                    f\\\"Query vector has {vector_dim} dimensions but field '{selected_field}' expects {field_dim}. \\\"\\n                    f\\\"Skipping this model to prevent search errors.\\\"\\n                )\\n                self.log(f\\\"[DIM MISMATCH] Model '{model_name}': query={vector_dim} vs field={field_dim} - skipping\\\")\\n                continue\\n\\n            logger.info(\\n                f\\\"Adding KNN query for model '{model_name}': field='{selected_field}', \\\"\\n                f\\\"query_dims={vector_dim}, field_dims={field_dim or 'unknown'}\\\"\\n            )\\n            embedding_fields.append(selected_field)\\n\\n            base_query = {\\n                \\\"knn\\\": {\\n                    selected_field: {\\n                        \\\"vector\\\": embedding_vector,\\n                        \\\"k\\\": 50,\\n                    }\\n                }\\n            }\\n\\n            if use_num_candidates:\\n                query_with_candidates = copy.deepcopy(base_query)\\n                query_with_candidates[\\\"knn\\\"][selected_field][\\\"num_candidates\\\"] = num_candidates\\n            else:\\n                query_with_candidates = base_query\\n\\n            knn_queries_with_candidates.append(query_with_candidates)\\n            knn_queries_without_candidates.append(base_query)\\n\\n        if not knn_queries_with_candidates:\\n            # No valid fields found - this can happen when:\\n            # 1. Index is empty (no documents yet)\\n            # 2. Embedding model has changed and field doesn't exist yet\\n            # Return empty results instead of failing\\n            logger.warning(\\n                \\\"No valid knn_vector fields found for embedding models. \\\"\\n                \\\"This may indicate an empty index or missing field mappings. \\\"\\n                \\\"Returning empty search results.\\\"\\n            )\\n            self.log(\\n                f\\\"[WARN] No valid KNN queries could be built. \\\"\\n                f\\\"Query embeddings generated: {list(query_embeddings.keys())}, \\\"\\n                f\\\"but no matching knn_vector fields found in index.\\\"\\n            )\\n            return []\\n\\n        # Build exists filter - document must have at least one embedding field\\n        exists_any_embedding = {\\n            \\\"bool\\\": {\\\"should\\\": [{\\\"exists\\\": {\\\"field\\\": f}} for f in set(embedding_fields)], \\\"minimum_should_match\\\": 1}\\n        }\\n\\n        # Combine user filters with exists filter\\n        all_filters = [*filter_clauses, exists_any_embedding]\\n\\n        # Get limit and score threshold\\n        limit = self._resolve_limit(filter_obj, default_limit=self.number_of_results)\\n        score_threshold = self._resolve_score_threshold(filter_obj)\\n\\n        # Determine the best aggregation field for filename based on index mapping\\n        filename_agg_field = self._get_filename_agg_field(index_properties)\\n\\n        # Build multi-model hybrid query\\n        body = {\\n            \\\"query\\\": {\\n                \\\"bool\\\": {\\n                    \\\"should\\\": [\\n                        {\\n                            \\\"dis_max\\\": {\\n                                \\\"tie_breaker\\\": 0.0,  # Take only the best match, no blending\\n                                \\\"boost\\\": 0.7,  # 70% weight for semantic search\\n                                \\\"queries\\\": knn_queries_with_candidates,\\n                            }\\n                        },\\n                        {\\n                            \\\"multi_match\\\": {\\n                                \\\"query\\\": q,\\n                                \\\"fields\\\": [\\\"text^2\\\", \\\"filename^1.5\\\"],\\n                                \\\"type\\\": \\\"best_fields\\\",\\n                                \\\"fuzziness\\\": \\\"AUTO\\\",\\n                                \\\"boost\\\": 0.3,  # 30% weight for keyword search\\n                            }\\n                        },\\n                    ],\\n                    \\\"minimum_should_match\\\": 1,\\n                    \\\"filter\\\": all_filters,\\n                }\\n            },\\n            \\\"aggs\\\": {\\n                \\\"data_sources\\\": {\\\"terms\\\": {\\\"field\\\": filename_agg_field, \\\"size\\\": 20}},\\n                \\\"document_types\\\": {\\\"terms\\\": {\\\"field\\\": \\\"mimetype\\\", \\\"size\\\": 10}},\\n                \\\"owners\\\": {\\\"terms\\\": {\\\"field\\\": \\\"owner\\\", \\\"size\\\": 10}},\\n                \\\"embedding_models\\\": {\\\"terms\\\": {\\\"field\\\": \\\"embedding_model\\\", \\\"size\\\": 10}},\\n            },\\n            \\\"_source\\\": [\\n                \\\"filename\\\",\\n                \\\"mimetype\\\",\\n                \\\"page\\\",\\n                \\\"text\\\",\\n                \\\"source_url\\\",\\n                \\\"owner\\\",\\n                \\\"embedding_model\\\",\\n                \\\"allowed_users\\\",\\n                \\\"allowed_groups\\\",\\n            ],\\n            \\\"size\\\": limit,\\n        }\\n\\n        if score_threshold is not None:\\n            body[\\\"min_score\\\"] = score_threshold\\n\\n        logger.info(\\n            f\\\"Executing multi-model hybrid search with {len(knn_queries_with_candidates)} embedding models: \\\"\\n            f\\\"{list(query_embeddings.keys())}\\\"\\n        )\\n        self.log(f\\\"[EXEC] Executing search with {len(knn_queries_with_candidates)} KNN queries, limit={limit}\\\")\\n        self.log(f\\\"[EXEC] Embedding models used: {list(query_embeddings.keys())}\\\")\\n        self.log(f\\\"[EXEC] KNN fields being queried: {embedding_fields}\\\")\\n\\n        try:\\n            resp = client.search(index=self.index_name, body=body, params={\\\"terminate_after\\\": 0})\\n        except RequestError as e:\\n            error_message = str(e)\\n            lowered = error_message.lower()\\n            if use_num_candidates and \\\"num_candidates\\\" in lowered:\\n                logger.warning(\\n                    \\\"Retrying search without num_candidates parameter due to cluster capabilities\\\",\\n                    error=error_message,\\n                )\\n                fallback_body = copy.deepcopy(body)\\n                try:\\n                    fallback_body[\\\"query\\\"][\\\"bool\\\"][\\\"should\\\"][0][\\\"dis_max\\\"][\\\"queries\\\"] = knn_queries_without_candidates\\n                except (KeyError, IndexError, TypeError) as inner_err:\\n                    raise e from inner_err\\n                resp = client.search(\\n                    index=self.index_name,\\n                    body=fallback_body,\\n                    params={\\\"terminate_after\\\": 0},\\n                )\\n            elif \\\"knn_vector\\\" in lowered or (\\\"field\\\" in lowered and \\\"knn\\\" in lowered):\\n                fallback_vector = next(iter(query_embeddings.values()), None)\\n                if fallback_vector is None:\\n                    raise\\n                fallback_field = legacy_vector_field or \\\"chunk_embedding\\\"\\n                logger.warning(\\n                    \\\"KNN search failed for dynamic fields; falling back to legacy field '%s'.\\\",\\n                    fallback_field,\\n                )\\n                fallback_body = copy.deepcopy(body)\\n                fallback_body[\\\"query\\\"][\\\"bool\\\"][\\\"filter\\\"] = filter_clauses\\n                knn_fallback = {\\n                    \\\"knn\\\": {\\n                        fallback_field: {\\n                            \\\"vector\\\": fallback_vector,\\n                            \\\"k\\\": 50,\\n                        }\\n                    }\\n                }\\n                if use_num_candidates:\\n                    knn_fallback[\\\"knn\\\"][fallback_field][\\\"num_candidates\\\"] = num_candidates\\n                fallback_body[\\\"query\\\"][\\\"bool\\\"][\\\"should\\\"][0][\\\"dis_max\\\"][\\\"queries\\\"] = [knn_fallback]\\n                resp = client.search(\\n                    index=self.index_name,\\n                    body=fallback_body,\\n                    params={\\\"terminate_after\\\": 0},\\n                )\\n            else:\\n                raise\\n        hits = resp.get(\\\"hits\\\", {}).get(\\\"hits\\\", [])\\n\\n        logger.info(f\\\"Found {len(hits)} results\\\")\\n        self.log(f\\\"[RESULT] Search complete: {len(hits)} results found\\\")\\n\\n        if len(hits) == 0:\\n            self.log(\\n                f\\\"[EMPTY] Debug info: \\\"\\n                f\\\"models_in_index={available_models}, \\\"\\n                f\\\"matched_models={matched_models}, \\\"\\n                f\\\"knn_fields={embedding_fields}, \\\"\\n                f\\\"filters={len(filter_clauses)} clauses\\\"\\n            )\\n\\n        return [\\n            {\\n                \\\"page_content\\\": hit[\\\"_source\\\"].get(\\\"text\\\", \\\"\\\"),\\n                \\\"metadata\\\": {k: v for k, v in hit[\\\"_source\\\"].items() if k != \\\"text\\\"},\\n                \\\"score\\\": hit.get(\\\"_score\\\"),\\n            }\\n            for hit in hits\\n        ]\\n\\n    def search_documents(self) -> Table:\\n        \\\"\\\"\\\"Search documents and return results as Data objects.\\n\\n        This is the main interface method that performs the multi-model search using the\\n        configured search_query and returns results in Langflow's Table format.\\n\\n        Always builds the vector store (triggering ingestion if needed), then performs\\n        search only if a query is provided.\\n\\n        Returns:\\n            Table: A table containing search results with text and metadata\\n\\n        Raises:\\n            Exception: If search operation fails\\n        \\\"\\\"\\\"\\n        try:\\n            # Always build/cache the vector store to ensure ingestion happens\\n            logger.info(f\\\"Search query: {self.search_query}\\\")\\n            if self._cached_vector_store is None:\\n                self.build_vector_store()\\n\\n            # Only perform search if query is provided\\n            search_query = (self.search_query or \\\"\\\").strip()\\n            if not search_query:\\n                self.log(\\\"No search query provided - ingestion completed, returning empty results\\\")\\n                return []\\n\\n            # Perform search with the provided query\\n            raw = self.search(search_query)\\n            raw_list = [Data(text=hit[\\\"page_content\\\"], **hit[\\\"metadata\\\"]) for hit in raw]\\n\\n            return Table(data=raw_list)\\n        except Exception as e:\\n            self.log(f\\\"search_documents error: {e}\\\")\\n            raise\\n\\n    # -------- dynamic UI handling (auth switch) --------\\n    async def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None) -> dict:\\n        \\\"\\\"\\\"Dynamically update component configuration based on field changes.\\n\\n        This method handles real-time UI updates, particularly for authentication\\n        mode changes that show/hide relevant input fields.\\n\\n        Args:\\n            build_config: Current component configuration\\n            field_value: New value for the changed field\\n            field_name: Name of the field that changed\\n\\n        Returns:\\n            Updated build configuration with appropriate field visibility\\n        \\\"\\\"\\\"\\n        try:\\n            if field_name == \\\"auth_mode\\\":\\n                mode = (field_value or \\\"basic\\\").strip().lower()\\n                is_basic = mode == \\\"basic\\\"\\n                is_jwt = mode == \\\"jwt\\\"\\n\\n                build_config[\\\"username\\\"][\\\"show\\\"] = is_basic\\n                build_config[\\\"password\\\"][\\\"show\\\"] = is_basic\\n\\n                build_config[\\\"jwt_token\\\"][\\\"show\\\"] = is_jwt\\n                build_config[\\\"jwt_header\\\"][\\\"show\\\"] = is_jwt\\n                build_config[\\\"bearer_prefix\\\"][\\\"show\\\"] = is_jwt\\n\\n                build_config[\\\"username\\\"][\\\"required\\\"] = is_basic\\n                build_config[\\\"password\\\"][\\\"required\\\"] = is_basic\\n\\n                build_config[\\\"jwt_token\\\"][\\\"required\\\"] = is_jwt\\n                build_config[\\\"jwt_header\\\"][\\\"required\\\"] = is_jwt\\n                build_config[\\\"bearer_prefix\\\"][\\\"required\\\"] = False\\n\\n                if is_basic:\\n                    build_config[\\\"jwt_token\\\"][\\\"value\\\"] = \\\"\\\"\\n\\n                return build_config\\n\\n        except (KeyError, ValueError) as e:\\n            self.log(f\\\"update_build_config error: {e}\\\")\\n\\n        return build_config\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/faiss/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"81b7728a753b301b6fe0f4547d470fb91d3cfc8c71d16f792dd2171c4826adf8\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from .faiss import FaissVectorStoreComponent\\n\\n_dynamic_imports = {\\n    \\\"FaissVectorStoreComponent\\\": \\\"faiss\\\",\\n}\\n\\n__all__ = [\\n    \\\"FaissVectorStoreComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import FAISS components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/faiss/faiss.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"44c2f668694456f3587eb4d3ef92c08277076e61223e9b332947dd506dcbec56\",\"content\":\"import re\\nfrom hashlib import sha256\\nfrom pathlib import Path\\n\\nfrom langchain_community.vectorstores import FAISS\\nfrom lfx.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.io import BoolInput, HandleInput, IntInput, StrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.file_path_security import enforce_local_file_access\\n\\n\\nclass FaissVectorStoreComponent(LCVectorStoreComponent):\\n    \\\"\\\"\\\"FAISS Vector Store with search capabilities.\\\"\\\"\\\"\\n\\n    display_name: str = \\\"FAISS\\\"\\n    description: str = \\\"FAISS Vector Store with search capabilities\\\"\\n    name = \\\"FAISS\\\"\\n    icon = \\\"FAISS\\\"\\n\\n    # Strict portable allow-list for the index file prefix: letters, digits, dot,\\n    # underscore and hyphen only, and the name must contain at least one\\n    # non-dot character. This rejects empty, \\\".\\\", \\\"..\\\", path separators\\n    # (\\\"/\\\", \\\"\\\\\\\\\\\") and drive-relative prefixes (e.g. \\\"D:shared\\\") that could escape\\n    # the per-user persist directory.\\n    _INDEX_NAME_PATTERN = re.compile(r\\\"^[A-Za-z0-9._-]*[A-Za-z0-9_-][A-Za-z0-9._-]*$\\\")\\n\\n    inputs = [\\n        StrInput(\\n            name=\\\"index_name\\\",\\n            display_name=\\\"Index Name\\\",\\n            value=\\\"langflow_index\\\",\\n        ),\\n        StrInput(\\n            name=\\\"persist_directory\\\",\\n            display_name=\\\"Persist Directory\\\",\\n            info=\\\"Path to save the FAISS index. It will be relative to where Langflow is running.\\\",\\n        ),\\n        *LCVectorStoreComponent.inputs,\\n        BoolInput(\\n            name=\\\"allow_dangerous_deserialization\\\",\\n            display_name=\\\"Allow Dangerous Deserialization\\\",\\n            info=\\\"Set to True to allow loading pickle files. WARNING: Only enable this if you trust the source \\\"\\n            \\\"of the data. Malicious pickle files can execute arbitrary code on your system.\\\",\\n            advanced=True,\\n            value=False,\\n        ),\\n        HandleInput(name=\\\"embedding\\\", display_name=\\\"Embedding\\\", input_types=[\\\"Embeddings\\\"]),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            advanced=True,\\n            value=4,\\n        ),\\n    ]\\n\\n    @staticmethod\\n    def _user_scope(user_id: object) -> str | None:\\n        if user_id is None:\\n            return None\\n\\n        user_id_str = str(user_id).strip()\\n        if not user_id_str or user_id_str.lower() == \\\"none\\\":\\n            return None\\n\\n        return sha256(user_id_str.encode(\\\"utf-8\\\")).hexdigest()[:32]\\n\\n    @staticmethod\\n    def resolve_path(path: str) -> str:\\n        \\\"\\\"\\\"Resolve the path relative to the Langflow root.\\n\\n        Args:\\n            path: The path to resolve\\n        Returns:\\n            str: The resolved path as a string\\n        \\\"\\\"\\\"\\n        return str(Path(path).resolve())\\n\\n    def get_index_name(self) -> str:\\n        \\\"\\\"\\\"Returns the validated FAISS index file prefix.\\\"\\\"\\\"\\n        index_name = str(self.index_name or \\\"\\\").strip()\\n        if not self._INDEX_NAME_PATTERN.match(index_name):\\n            msg = \\\"FAISS index name must be a file name, not a path.\\\"\\n            raise ValueError(msg)\\n        return index_name\\n\\n    def get_persist_directory(self) -> Path:\\n        \\\"\\\"\\\"Returns the resolved, user-scoped persist directory path.\\n\\n        When ``LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS`` is on, the user-supplied base\\n        directory is confined to the storage dir before the per-user FAISS scope is appended.\\n        \\\"\\\"\\\"\\n        path = (\\n            enforce_local_file_access(self.resolve_path(self.persist_directory)) if self.persist_directory else Path()\\n        )\\n        if user_scope := self._user_scope(self.user_id):\\n            return path / \\\".langflow_faiss\\\" / \\\"users\\\" / user_scope\\n        return path\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self) -> FAISS:\\n        \\\"\\\"\\\"Builds the FAISS object.\\\"\\\"\\\"\\n        path = self.get_persist_directory()\\n        index_name = self.get_index_name()\\n        path.mkdir(parents=True, exist_ok=True)\\n\\n        # Convert DataFrame to Data if needed using parent's method\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                documents.append(_input)\\n\\n        faiss = FAISS.from_documents(documents=documents, embedding=self.embedding)\\n        faiss.save_local(str(path), index_name)\\n        return faiss\\n\\n    def search_documents(self) -> list[Data]:\\n        \\\"\\\"\\\"Search for documents in the FAISS vector store.\\\"\\\"\\\"\\n        path = self.get_persist_directory()\\n        index_name = self.get_index_name()\\n        index_path = path / f\\\"{index_name}.faiss\\\"\\n\\n        if not index_path.exists():\\n            vector_store = self.build_vector_store()\\n        else:\\n            vector_store = FAISS.load_local(\\n                folder_path=str(path),\\n                embeddings=self.embedding,\\n                index_name=index_name,\\n                allow_dangerous_deserialization=self.allow_dangerous_deserialization,\\n            )\\n\\n        if not vector_store:\\n            msg = \\\"Failed to load the FAISS index.\\\"\\n            raise ValueError(msg)\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            docs = vector_store.similarity_search(\\n                query=self.search_query,\\n                k=self.number_of_results,\\n            )\\n            return docs_to_data(docs)\\n        return []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/git/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cda9712a93792227dbb30cbcfc78d29efab3592164183eb58d2db1020aafea96\",\"content\":\"from .git import GitLoaderComponent\\nfrom .gitextractor import GitExtractorComponent\\n\\n__all__ = [\\\"GitExtractorComponent\\\", \\\"GitLoaderComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/git/git.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"b164d564f6120fb2437b20c91707b08f3458facb59cc126e936b59189fb6ab5f\",\"content\":\"import re\\nimport tempfile\\nfrom contextlib import asynccontextmanager\\nfrom fnmatch import fnmatch\\nfrom pathlib import Path\\n\\nimport anyio\\nfrom langchain_community.document_loaders.git import GitLoader\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import DropdownInput, MessageTextInput, Output\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.file_path_security import enforce_local_file_access\\nfrom lfx.utils.ssrf_protection import validate_git_repository_url\\n\\n\\nclass GitLoaderComponent(Component):\\n    display_name = \\\"Git\\\"\\n    description = (\\n        \\\"Load and filter documents from a local or remote Git repository. \\\"\\n        \\\"Use a local repo path or clone from a remote URL.\\\"\\n    )\\n    trace_type = \\\"tool\\\"\\n    icon = \\\"GitLoader\\\"\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"repo_source\\\",\\n            display_name=\\\"Repository Source\\\",\\n            options=[\\\"Local\\\", \\\"Remote\\\"],\\n            required=True,\\n            info=\\\"Select whether to use a local repo path or clone from a remote URL.\\\",\\n            real_time_refresh=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"repo_path\\\",\\n            display_name=\\\"Local Repository Path\\\",\\n            required=False,\\n            info=\\\"The local path to the existing Git repository (used if 'Local' is selected).\\\",\\n            dynamic=True,\\n            show=False,\\n        ),\\n        MessageTextInput(\\n            name=\\\"clone_url\\\",\\n            display_name=\\\"Clone URL\\\",\\n            required=False,\\n            info=\\\"The URL of the Git repository to clone (used if 'Clone' is selected).\\\",\\n            dynamic=True,\\n            show=False,\\n        ),\\n        MessageTextInput(\\n            name=\\\"branch\\\",\\n            display_name=\\\"Branch\\\",\\n            required=False,\\n            value=\\\"main\\\",\\n            info=\\\"The branch to load files from. Defaults to 'main'.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"file_filter\\\",\\n            display_name=\\\"File Filter\\\",\\n            required=False,\\n            advanced=True,\\n            info=(\\n                \\\"Patterns to filter files. For example:\\\\n\\\"\\n                \\\"Include only .py files: '*.py'\\\\n\\\"\\n                \\\"Exclude .py files: '!*.py'\\\\n\\\"\\n                \\\"Multiple patterns can be separated by commas.\\\"\\n            ),\\n        ),\\n        MessageTextInput(\\n            name=\\\"content_filter\\\",\\n            display_name=\\\"Content Filter\\\",\\n            required=False,\\n            advanced=True,\\n            info=\\\"A regex pattern to filter files based on their content.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"data\\\", display_name=\\\"JSON\\\", method=\\\"load_documents\\\"),\\n    ]\\n\\n    @staticmethod\\n    def is_binary(file_path: str | Path) -> bool:\\n        \\\"\\\"\\\"Check if a file is binary by looking for null bytes.\\\"\\\"\\\"\\n        try:\\n            with Path(file_path).open(\\\"rb\\\") as file:\\n                content = file.read(1024)\\n                return b\\\"\\\\x00\\\" in content\\n        except Exception:  # noqa: BLE001\\n            return True\\n\\n    @staticmethod\\n    def check_file_patterns(file_path: str | Path, patterns: str) -> bool:\\n        \\\"\\\"\\\"Check if a file matches the given patterns.\\n\\n        Args:\\n            file_path: Path to the file to check\\n            patterns: Comma-separated list of glob patterns\\n\\n        Returns:\\n            bool: True if file should be included, False if excluded\\n        \\\"\\\"\\\"\\n        # Handle empty or whitespace-only patterns\\n        if not patterns or patterns.isspace():\\n            return True\\n\\n        path_str = str(file_path)\\n        file_name = Path(path_str).name\\n        pattern_list: list[str] = [pattern.strip() for pattern in patterns.split(\\\",\\\") if pattern.strip()]\\n\\n        # If no valid patterns after stripping, treat as include all\\n        if not pattern_list:\\n            return True\\n\\n        # Process exclusion patterns first\\n        for pattern in pattern_list:\\n            if pattern.startswith(\\\"!\\\"):\\n                # For exclusions, match against both full path and filename\\n                exclude_pattern = pattern[1:]\\n                if fnmatch(path_str, exclude_pattern) or fnmatch(file_name, exclude_pattern):\\n                    return False\\n\\n        # Then check inclusion patterns\\n        include_patterns = [p for p in pattern_list if not p.startswith(\\\"!\\\")]\\n        # If no include patterns, treat as include all\\n        if not include_patterns:\\n            return True\\n\\n        # For inclusions, match against both full path and filename\\n        return any(fnmatch(path_str, pattern) or fnmatch(file_name, pattern) for pattern in include_patterns)\\n\\n    @staticmethod\\n    def check_content_pattern(file_path: str | Path, pattern: str) -> bool:\\n        \\\"\\\"\\\"Check if file content matches the given regex pattern.\\n\\n        Args:\\n            file_path: Path to the file to check\\n            pattern: Regex pattern to match against content\\n\\n        Returns:\\n            bool: True if content matches, False otherwise\\n        \\\"\\\"\\\"\\n        try:\\n            # Check if file is binary\\n            with Path(file_path).open(\\\"rb\\\") as file:\\n                content = file.read(1024)\\n                if b\\\"\\\\x00\\\" in content:\\n                    return False\\n\\n            # Try to compile the regex pattern first\\n            try:\\n                # Use the MULTILINE flag to better handle text content\\n                content_regex = re.compile(pattern, re.MULTILINE)\\n                # Test the pattern with a simple string to catch syntax errors\\n                test_str = \\\"test\\\\nstring\\\"\\n                if not content_regex.search(test_str):\\n                    # Pattern is valid but doesn't match test string\\n                    pass\\n            except (re.error, TypeError, ValueError):\\n                return False\\n\\n            # If not binary and regex is valid, check content\\n            with Path(file_path).open(encoding=\\\"utf-8\\\") as file:\\n                file_content = file.read()\\n            return bool(content_regex.search(file_content))\\n        except (OSError, UnicodeDecodeError):\\n            return False\\n\\n    def build_combined_filter(self, file_filter_patterns: str | None = None, content_filter_pattern: str | None = None):\\n        \\\"\\\"\\\"Build a combined filter function from file and content patterns.\\n\\n        Args:\\n            file_filter_patterns: Comma-separated glob patterns\\n            content_filter_pattern: Regex pattern for content\\n\\n        Returns:\\n            callable: Filter function that takes a file path and returns bool\\n        \\\"\\\"\\\"\\n\\n        def combined_filter(file_path: str) -> bool:\\n            try:\\n                path = Path(file_path)\\n\\n                # Check if file exists and is readable\\n                if not path.exists():\\n                    return False\\n\\n                # Check if file is binary\\n                if self.is_binary(path):\\n                    return False\\n\\n                # Apply file pattern filters\\n                if file_filter_patterns and not self.check_file_patterns(path, file_filter_patterns):\\n                    return False\\n\\n                # Apply content filter\\n                return not (content_filter_pattern and not self.check_content_pattern(path, content_filter_pattern))\\n            except Exception:  # noqa: BLE001\\n                return False\\n\\n        return combined_filter\\n\\n    @asynccontextmanager\\n    async def temp_clone_dir(self):\\n        \\\"\\\"\\\"Context manager for handling temporary clone directory.\\\"\\\"\\\"\\n        temp_dir = None\\n        try:\\n            temp_dir = tempfile.mkdtemp(prefix=\\\"langflow_clone_\\\")\\n            yield temp_dir\\n        finally:\\n            if temp_dir:\\n                await anyio.Path(temp_dir).rmdir()\\n\\n    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None) -> dict:\\n        # Hide fields by default\\n        build_config[\\\"repo_path\\\"][\\\"show\\\"] = False\\n        build_config[\\\"clone_url\\\"][\\\"show\\\"] = False\\n\\n        if field_name == \\\"repo_source\\\":\\n            if field_value == \\\"Local\\\":\\n                build_config[\\\"repo_path\\\"][\\\"show\\\"] = True\\n                build_config[\\\"repo_path\\\"][\\\"required\\\"] = True\\n                build_config[\\\"clone_url\\\"][\\\"required\\\"] = False\\n            elif field_value == \\\"Remote\\\":\\n                build_config[\\\"clone_url\\\"][\\\"show\\\"] = True\\n                build_config[\\\"clone_url\\\"][\\\"required\\\"] = True\\n                build_config[\\\"repo_path\\\"][\\\"required\\\"] = False\\n\\n        return build_config\\n\\n    async def build_gitloader(self) -> GitLoader:\\n        file_filter_patterns = getattr(self, \\\"file_filter\\\", None)\\n        content_filter_pattern = getattr(self, \\\"content_filter\\\", None)\\n\\n        combined_filter = self.build_combined_filter(file_filter_patterns, content_filter_pattern)\\n\\n        repo_source = getattr(self, \\\"repo_source\\\", None)\\n        if repo_source == \\\"Local\\\":\\n            # repo_path is tenant-controlled and its file contents are read back: confine to the\\n            # storage dir when LANGFLOW_RESTRICT_LOCAL_FILE_ACCESS is enabled (multi-tenant).\\n            repo_path = str(enforce_local_file_access(self.repo_path))\\n            clone_url = None\\n        else:\\n            # Clone source. The URL is tenant-controlled: block ext::/fd:: remote helpers\\n            # (RCE), file:// / local paths (arbitrary file read), and SSRF-blocked hosts.\\n            clone_url = self.clone_url\\n            validate_git_repository_url(clone_url)\\n            async with self.temp_clone_dir() as temp_dir:\\n                repo_path = temp_dir\\n\\n        # Only pass branch if it's explicitly set\\n        branch = getattr(self, \\\"branch\\\", None)\\n        if not branch:\\n            branch = None\\n\\n        return GitLoader(\\n            repo_path=repo_path,\\n            clone_url=clone_url if repo_source == \\\"Remote\\\" else None,\\n            branch=branch,\\n            file_filter=combined_filter,\\n        )\\n\\n    async def load_documents(self) -> list[Data]:\\n        gitloader = await self.build_gitloader()\\n        data = [Data.from_document(doc) async for doc in gitloader.alazy_load()]\\n        self.status = data\\n        return data\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/git/gitextractor.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"23a0f4f3678a7ea6341a99709f146c3b49fd553ae741258453299c5d93784918\",\"content\":\"import os\\nimport shutil\\nimport tempfile\\nfrom contextlib import asynccontextmanager\\nfrom pathlib import Path\\n\\nimport aiofiles\\nimport git\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\nfrom lfx.utils.ssrf_protection import validate_git_repository_url\\n\\n\\nclass GitExtractorComponent(Component):\\n    display_name = \\\"GitExtractor\\\"\\n    description = \\\"Analyzes a Git repository and returns file contents and complete repository information\\\"\\n    icon = \\\"GitLoader\\\"\\n\\n    inputs = [\\n        MessageTextInput(\\n            name=\\\"repository_url\\\",\\n            display_name=\\\"Repository URL\\\",\\n            info=\\\"URL of the Git repository (e.g., https://github.com/username/repo)\\\",\\n            value=\\\"\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Text-Based File Contents\\\",\\n            name=\\\"text_based_file_contents\\\",\\n            method=\\\"get_text_based_file_contents\\\",\\n        ),\\n        Output(display_name=\\\"Directory Structure\\\", name=\\\"directory_structure\\\", method=\\\"get_directory_structure\\\"),\\n        Output(display_name=\\\"Repository Info\\\", name=\\\"repository_info\\\", method=\\\"get_repository_info\\\"),\\n        Output(display_name=\\\"Statistics\\\", name=\\\"statistics\\\", method=\\\"get_statistics\\\"),\\n        Output(display_name=\\\"Files Content\\\", name=\\\"files_content\\\", method=\\\"get_files_content\\\"),\\n    ]\\n\\n    @asynccontextmanager\\n    async def temp_git_repo(self):\\n        \\\"\\\"\\\"Async context manager for temporary git repository cloning.\\\"\\\"\\\"\\n        # Confine the tenant-controlled URL to safe network transports: block ext::/fd::\\n        # remote helpers (RCE), file:// and local paths (arbitrary file read), and hosts\\n        # in SSRF-blocked ranges (internal/cloud-metadata access).\\n        validate_git_repository_url(self.repository_url)\\n        temp_dir = tempfile.mkdtemp()\\n        try:\\n            # Clone is still sync but wrapped in try/finally\\n            git.Repo.clone_from(self.repository_url, temp_dir)\\n            yield temp_dir\\n        finally:\\n            shutil.rmtree(temp_dir, ignore_errors=True)\\n\\n    async def get_repository_info(self) -> list[Data]:\\n        try:\\n            async with self.temp_git_repo() as temp_dir:\\n                repo = git.Repo(temp_dir)\\n                repo_info = {\\n                    \\\"name\\\": self.repository_url.split(\\\"/\\\")[-1],\\n                    \\\"url\\\": self.repository_url,\\n                    \\\"default_branch\\\": repo.active_branch.name,\\n                    \\\"remote_urls\\\": [remote.url for remote in repo.remotes],\\n                    \\\"last_commit\\\": {\\n                        \\\"hash\\\": repo.head.commit.hexsha,\\n                        \\\"author\\\": str(repo.head.commit.author),\\n                        \\\"message\\\": repo.head.commit.message.strip(),\\n                        \\\"date\\\": str(repo.head.commit.committed_datetime),\\n                    },\\n                    \\\"branches\\\": [str(branch) for branch in repo.branches],\\n                }\\n                result = [Data(data=repo_info)]\\n                self.status = result\\n                return result\\n        except git.GitError as e:\\n            error_result = [Data(data={\\\"error\\\": f\\\"Error getting repository info: {e!s}\\\"})]\\n            self.status = error_result\\n            return error_result\\n\\n    async def get_statistics(self) -> list[Data]:\\n        try:\\n            async with self.temp_git_repo() as temp_dir:\\n                total_files = 0\\n                total_size = 0\\n                total_lines = 0\\n                binary_files = 0\\n                directories = 0\\n\\n                for root, dirs, files in os.walk(temp_dir):\\n                    dirs[:] = [directory for directory in dirs if not (Path(root) / directory).is_symlink()]\\n                    directories += len(dirs)\\n                    for file in files:\\n                        file_path = Path(root) / file\\n                        if file_path.is_symlink():\\n                            continue\\n                        total_files += 1\\n                        total_size += file_path.stat().st_size\\n                        try:\\n                            async with aiofiles.open(file_path, encoding=\\\"utf-8\\\") as f:\\n                                total_lines += sum(1 for _ in await f.readlines())\\n                        except UnicodeDecodeError:\\n                            binary_files += 1\\n\\n                statistics = {\\n                    \\\"total_files\\\": total_files,\\n                    \\\"total_size_bytes\\\": total_size,\\n                    \\\"total_size_kb\\\": round(total_size / 1024, 2),\\n                    \\\"total_size_mb\\\": round(total_size / (1024 * 1024), 2),\\n                    \\\"total_lines\\\": total_lines,\\n                    \\\"binary_files\\\": binary_files,\\n                    \\\"directories\\\": directories,\\n                }\\n                result = [Data(data=statistics)]\\n                self.status = result\\n                return result\\n        except git.GitError as e:\\n            error_result = [Data(data={\\\"error\\\": f\\\"Error calculating statistics: {e!s}\\\"})]\\n            self.status = error_result\\n            return error_result\\n\\n    async def get_directory_structure(self) -> Message:\\n        try:\\n            async with self.temp_git_repo() as temp_dir:\\n                tree = [\\\"Directory structure:\\\"]\\n                for root, _dirs, files in os.walk(temp_dir):\\n                    level = root.replace(temp_dir, \\\"\\\").count(os.sep)\\n                    indent = \\\"    \\\" * level\\n                    if level == 0:\\n                        tree.append(f\\\"\u2514\u2500\u2500 {Path(root).name}\\\")\\n                    else:\\n                        tree.append(f\\\"{indent}\u251c\u2500\u2500 {Path(root).name}\\\")\\n                    subindent = \\\"    \\\" * (level + 1)\\n                    tree.extend(f\\\"{subindent}\u251c\u2500\u2500 {f}\\\" for f in files)\\n                directory_structure = \\\"\\\\n\\\".join(tree)\\n                self.status = directory_structure\\n                return Message(text=directory_structure)\\n        except git.GitError as e:\\n            error_message = f\\\"Error getting directory structure: {e!s}\\\"\\n            self.status = error_message\\n            return Message(text=error_message)\\n\\n    async def get_files_content(self) -> list[Data]:\\n        try:\\n            async with self.temp_git_repo() as temp_dir:\\n                content_list = []\\n                for root, _, files in os.walk(temp_dir):\\n                    for file in files:\\n                        file_path = Path(root) / file\\n                        if file_path.is_symlink():\\n                            continue\\n                        relative_path = file_path.relative_to(temp_dir)\\n                        file_size = file_path.stat().st_size\\n                        try:\\n                            async with aiofiles.open(file_path, encoding=\\\"utf-8\\\") as f:\\n                                file_content = await f.read()\\n                        except UnicodeDecodeError:\\n                            file_content = \\\"[BINARY FILE]\\\"\\n                        content_list.append(\\n                            Data(data={\\\"path\\\": str(relative_path), \\\"size\\\": file_size, \\\"content\\\": file_content})\\n                        )\\n                self.status = content_list\\n                return content_list\\n        except git.GitError as e:\\n            error_result = [Data(data={\\\"error\\\": f\\\"Error getting files content: {e!s}\\\"})]\\n            self.status = error_result\\n            return error_result\\n\\n    async def get_text_based_file_contents(self) -> Message:\\n        try:\\n            async with self.temp_git_repo() as temp_dir:\\n                content_list = [\\\"(Files content cropped to 300k characters, download full ingest to see more)\\\"]\\n                total_chars = 0\\n                char_limit = 300000\\n\\n                for root, _, files in os.walk(temp_dir):\\n                    for file in files:\\n                        file_path = Path(root) / file\\n                        if file_path.is_symlink():\\n                            continue\\n                        relative_path = file_path.relative_to(temp_dir)\\n                        content_list.extend([\\\"=\\\" * 50, f\\\"File: /{relative_path}\\\", \\\"=\\\" * 50])\\n\\n                        try:\\n                            async with aiofiles.open(file_path, encoding=\\\"utf-8\\\") as f:\\n                                file_content = await f.read()\\n                                if total_chars + len(file_content) > char_limit:\\n                                    remaining_chars = char_limit - total_chars\\n                                    file_content = file_content[:remaining_chars] + \\\"\\\\n... (content truncated)\\\"\\n                                content_list.append(file_content)\\n                                total_chars += len(file_content)\\n                        except UnicodeDecodeError:\\n                            content_list.append(\\\"[BINARY FILE]\\\")\\n\\n                        content_list.append(\\\"\\\")\\n\\n                        if total_chars >= char_limit:\\n                            break\\n\\n                text_content = \\\"\\\\n\\\".join(content_list)\\n                self.status = text_content\\n                return Message(text=text_content)\\n        except git.GitError as e:\\n            error_message = f\\\"Error getting text-based file contents: {e!s}\\\"\\n            self.status = error_message\\n            return Message(text=error_message)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/glean/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"d5574c05394d2ff85527b10918eb6b1c4df4cca72fe057cab98f98ba8e8babf1\",\"content\":\"from .glean_search_api import GleanSearchAPISchema\\n\\n__all__ = [\\\"GleanSearchAPISchema\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/glean/glean_search_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5cb31fd6db29759a39d5b59c8465b82dc4cac9c939dc3bfdc20b21d1ec7a3d6a\",\"content\":\"import json\\nfrom typing import Any\\nfrom urllib.parse import urljoin\\n\\nfrom langchain_core.tools import StructuredTool, ToolException\\nfrom lfx.base.langchain_utilities.model import LCToolComponent\\nfrom lfx.field_typing import Tool\\nfrom lfx.inputs.inputs import IntInput, MultilineInput, NestedDictInput, SecretStrInput, StrInput\\nfrom lfx.io import Output\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dataframe import DataFrame\\nfrom lfx.utils.ssrf_httpx import ssrf_safe_httpx_post\\nfrom pydantic import BaseModel\\nfrom pydantic.v1 import Field\\n\\n\\nclass GleanSearchAPISchema(BaseModel):\\n    query: str = Field(..., description=\\\"The search query\\\")\\n    page_size: int = Field(10, description=\\\"Maximum number of results to return\\\")\\n    request_options: dict[str, Any] | None = Field(default_factory=dict, description=\\\"Request Options\\\")\\n\\n\\nclass GleanAPIWrapper(BaseModel):\\n    \\\"\\\"\\\"Wrapper around Glean API.\\\"\\\"\\\"\\n\\n    glean_api_url: str\\n    glean_access_token: str\\n    act_as: str = \\\"langflow-component@datastax.com\\\"  # TODO: Detect this\\n\\n    def _prepare_request(\\n        self,\\n        query: str,\\n        page_size: int = 10,\\n        request_options: dict[str, Any] | None = None,\\n    ) -> dict:\\n        # Ensure there's a trailing slash\\n        url = self.glean_api_url\\n        if not url.endswith(\\\"/\\\"):\\n            url += \\\"/\\\"\\n\\n        return {\\n            \\\"url\\\": urljoin(url, \\\"search\\\"),\\n            \\\"headers\\\": {\\n                \\\"Authorization\\\": f\\\"Bearer {self.glean_access_token}\\\",\\n                \\\"X-Scio-ActAs\\\": self.act_as,\\n            },\\n            \\\"payload\\\": {\\n                \\\"query\\\": query,\\n                \\\"pageSize\\\": page_size,\\n                \\\"requestOptions\\\": request_options,\\n            },\\n        }\\n\\n    def results(self, query: str, **kwargs: Any) -> list[dict[str, Any]]:\\n        results = self._search_api_results(query, **kwargs)\\n\\n        if len(results) == 0:\\n            msg = \\\"No good Glean Search Result was found\\\"\\n            raise AssertionError(msg)\\n\\n        return results\\n\\n    def run(self, query: str, **kwargs: Any) -> list[dict[str, Any]]:\\n        try:\\n            results = self.results(query, **kwargs)\\n\\n            processed_results = []\\n            for result in results:\\n                if \\\"title\\\" in result:\\n                    result[\\\"snippets\\\"] = result.get(\\\"snippets\\\", [{\\\"snippet\\\": {\\\"text\\\": result[\\\"title\\\"]}}])\\n                    if \\\"text\\\" not in result[\\\"snippets\\\"][0]:\\n                        result[\\\"snippets\\\"][0][\\\"text\\\"] = result[\\\"title\\\"]\\n\\n                processed_results.append(result)\\n        except Exception as e:\\n            error_message = f\\\"Error in Glean Search API: {e!s}\\\"\\n            raise ToolException(error_message) from e\\n\\n        return processed_results\\n\\n    def _search_api_results(self, query: str, **kwargs: Any) -> list[dict[str, Any]]:\\n        request_details = self._prepare_request(query, **kwargs)\\n\\n        response = ssrf_safe_httpx_post(\\n            request_details[\\\"url\\\"],\\n            json=request_details[\\\"payload\\\"],\\n            headers=request_details[\\\"headers\\\"],\\n        )\\n\\n        response.raise_for_status()\\n        response_json = response.json()\\n\\n        return response_json.get(\\\"results\\\", [])\\n\\n    @staticmethod\\n    def _result_as_string(result: dict) -> str:\\n        return json.dumps(result, indent=4)\\n\\n\\nclass GleanSearchAPIComponent(LCToolComponent):\\n    display_name: str = \\\"Glean Search API\\\"\\n    description: str = \\\"Search using Glean's API.\\\"\\n    documentation: str = \\\"https://docs.langflow.org/bundles-glean\\\"\\n    icon: str = \\\"Glean\\\"\\n\\n    outputs = [\\n        Output(display_name=\\\"Table\\\", name=\\\"dataframe\\\", method=\\\"fetch_content_dataframe\\\"),\\n    ]\\n\\n    inputs = [\\n        StrInput(name=\\\"glean_api_url\\\", display_name=\\\"Glean API URL\\\", required=True),\\n        SecretStrInput(name=\\\"glean_access_token\\\", display_name=\\\"Glean Access Token\\\", required=True),\\n        MultilineInput(name=\\\"query\\\", display_name=\\\"Query\\\", required=True, tool_mode=True),\\n        IntInput(name=\\\"page_size\\\", display_name=\\\"Page Size\\\", value=10),\\n        NestedDictInput(name=\\\"request_options\\\", display_name=\\\"Request Options\\\", required=False),\\n    ]\\n\\n    def build_tool(self) -> Tool:\\n        wrapper = self._build_wrapper(\\n            glean_api_url=self.glean_api_url,\\n            glean_access_token=self.glean_access_token,\\n        )\\n\\n        tool = StructuredTool.from_function(\\n            name=\\\"glean_search_api\\\",\\n            description=\\\"Search Glean for relevant results.\\\",\\n            func=wrapper.run,\\n            args_schema=GleanSearchAPISchema,\\n        )\\n\\n        self.status = \\\"Glean Search API Tool for Langchain\\\"\\n\\n        return tool\\n\\n    def run_model(self) -> DataFrame:\\n        return self.fetch_content_dataframe()\\n\\n    def fetch_content(self) -> list[Data]:\\n        tool = self.build_tool()\\n\\n        results = tool.run(\\n            {\\n                \\\"query\\\": self.query,\\n                \\\"page_size\\\": self.page_size,\\n                \\\"request_options\\\": self.request_options,\\n            }\\n        )\\n\\n        # Build the data\\n        data = [Data(data=result, text=result[\\\"snippets\\\"][0][\\\"text\\\"]) for result in results]\\n        self.status = data  # type: ignore[assignment]\\n\\n        return data\\n\\n    def _build_wrapper(\\n        self,\\n        glean_api_url: str,\\n        glean_access_token: str,\\n    ):\\n        return GleanAPIWrapper(\\n            glean_api_url=glean_api_url,\\n            glean_access_token=glean_access_token,\\n        )\\n\\n    def fetch_content_dataframe(self) -> DataFrame:\\n        \\\"\\\"\\\"Convert the Glean search results to a DataFrame.\\n\\n        Returns:\\n            DataFrame: A DataFrame containing the search results.\\n        \\\"\\\"\\\"\\n        data = self.fetch_content()\\n        return DataFrame(data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/groq/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"25e9798dc98538d932707c5d5d3c7ffa444bc5df044ca3d0b30edbddecb94b37\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .groq import GroqModel\\n\\n_dynamic_imports = {\\n    \\\"GroqModel\\\": \\\"groq\\\",\\n}\\n\\n__all__ = [\\n    \\\"GroqModel\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import groq components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/groq/groq.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"59c69a65e077786ccfa25a7a95f5f16ece8a39ec85bffddb85a7550e91ddef16\",\"content\":\"from lfx.base.models.groq_constants import GROQ_MODELS\\nfrom lfx.base.models.groq_model_discovery import get_groq_models\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.io import BoolInput, DropdownInput, IntInput, MessageTextInput, SecretStrInput, SliderInput\\nfrom lfx.log.logger import logger\\nfrom pydantic.v1 import SecretStr\\n\\n\\nclass GroqModel(LCModelComponent):\\n    display_name: str = \\\"Groq\\\"\\n    description: str = \\\"Generate text using Groq.\\\"\\n    icon = \\\"Groq\\\"\\n    name = \\\"GroqModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        SecretStrInput(\\n            name=\\\"api_key\\\", display_name=\\\"Groq API Key\\\", info=\\\"API key for the Groq API.\\\", real_time_refresh=True\\n        ),\\n        MessageTextInput(\\n            name=\\\"base_url\\\",\\n            display_name=\\\"Groq API Base\\\",\\n            info=\\\"Base URL path for API requests, leave blank if not using a proxy or service emulator.\\\",\\n            advanced=True,\\n            value=\\\"https://api.groq.com\\\",\\n            real_time_refresh=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Output Tokens\\\",\\n            info=\\\"The maximum number of tokens to generate.\\\",\\n            advanced=True,\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.1,\\n            info=\\\"Run inference with this temperature. Must by in the closed interval [0.0, 1.0].\\\",\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"n\\\",\\n            display_name=\\\"N\\\",\\n            info=\\\"Number of chat completions to generate for each prompt. \\\"\\n            \\\"Note that the API may not return the full n completions if duplicates are generated.\\\",\\n            advanced=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model\\\",\\n            info=\\\"The name of the model to use. Add your Groq API key to access additional available models.\\\",\\n            options=GROQ_MODELS,\\n            value=GROQ_MODELS[0],\\n            refresh_button=True,\\n            combobox=True,\\n        ),\\n        BoolInput(\\n            name=\\\"tool_model_enabled\\\",\\n            display_name=\\\"Enable Tool Models\\\",\\n            info=(\\n                \\\"Select if you want to use models that can work with tools. If yes, only those models will be shown.\\\"\\n            ),\\n            advanced=False,\\n            value=False,\\n            real_time_refresh=True,\\n        ),\\n    ]\\n\\n    def get_models(self, *, tool_model_enabled: bool | None = None) -> list[str]:\\n        \\\"\\\"\\\"Get available Groq models using the dynamic discovery system.\\n\\n        This method uses the groq_model_discovery module which:\\n        - Fetches models directly from Groq API\\n        - Automatically tests tool calling support\\n        - Caches results for 24 hours\\n        - Falls back to hardcoded list if API fails\\n\\n        Args:\\n            tool_model_enabled: If True, only return models that support tool calling\\n\\n        Returns:\\n            List of available model IDs\\n        \\\"\\\"\\\"\\n        try:\\n            # Get models with metadata from dynamic discovery system\\n            api_key = self.api_key if hasattr(self, \\\"api_key\\\") and self.api_key else None\\n            models_metadata = get_groq_models(api_key=api_key)\\n\\n            # Filter out non-LLM models (audio, TTS, guards)\\n            model_ids = [\\n                model_id for model_id, metadata in models_metadata.items() if not metadata.get(\\\"not_supported\\\", False)\\n            ]\\n\\n            # Filter by tool calling support if requested\\n            if tool_model_enabled:\\n                model_ids = [model_id for model_id in model_ids if models_metadata[model_id].get(\\\"tool_calling\\\", False)]\\n                logger.info(f\\\"Loaded {len(model_ids)} Groq models with tool calling support\\\")\\n            else:\\n                logger.info(f\\\"Loaded {len(model_ids)} Groq models\\\")\\n        except (ValueError, KeyError, TypeError, ImportError):\\n            logger.exception(\\\"Error getting model names\\\")\\n            # Fallback to hardcoded list from groq_constants.py\\n            return GROQ_MODELS\\n        else:\\n            return model_ids\\n\\n    def update_build_config(self, build_config: dict, field_value: str, field_name: str | None = None):\\n        if field_name in {\\\"base_url\\\", \\\"model_name\\\", \\\"tool_model_enabled\\\", \\\"api_key\\\"} and field_value:\\n            try:\\n                if len(self.api_key) != 0:\\n                    try:\\n                        ids = self.get_models(tool_model_enabled=self.tool_model_enabled)\\n                    except (ValueError, KeyError, TypeError, ImportError):\\n                        logger.exception(\\\"Error getting model names\\\")\\n                        ids = GROQ_MODELS\\n                    ids = ids or GROQ_MODELS\\n                    build_config.setdefault(\\\"model_name\\\", {})\\n                    build_config[\\\"model_name\\\"][\\\"options\\\"] = ids\\n                    build_config[\\\"model_name\\\"].setdefault(\\\"value\\\", ids[0])\\n            except (ValueError, KeyError, TypeError, AttributeError) as e:\\n                msg = f\\\"Error getting model names: {e}\\\"\\n                raise ValueError(msg) from e\\n        return build_config\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        try:\\n            from langchain_groq import ChatGroq\\n        except ImportError as e:\\n            msg = \\\"langchain-groq is not installed. Please install it with `pip install langchain-groq`.\\\"\\n            raise ImportError(msg) from e\\n\\n        return ChatGroq(\\n            model=self.model_name,\\n            max_tokens=self.max_tokens or None,\\n            temperature=self.temperature,\\n            base_url=self.base_url,\\n            n=self.n or 1,\\n            api_key=SecretStr(self.api_key).get_secret_value(),\\n            streaming=self.stream,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/homeassistant/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a9302f66bb70f0c7f817ff598c7053735a4007e3eee6c2da501e3a891db813f7\",\"content\":\"from .home_assistant_control import HomeAssistantControl\\nfrom .list_home_assistant_states import ListHomeAssistantStates\\n\\n__all__ = [\\n    \\\"HomeAssistantControl\\\",\\n    \\\"ListHomeAssistantStates\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/homeassistant/home_assistant_control.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"117bc6dae122ef056589ca47dd9addaa89c8bb191a73f1431586669f36a2527e\",\"content\":\"import json\\nfrom typing import Any\\n\\nimport httpx\\nfrom langchain_core.tools import StructuredTool\\nfrom lfx.base.langchain_utilities.model import LCToolComponent\\nfrom lfx.field_typing import Tool\\nfrom lfx.inputs.inputs import SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.ssrf_httpx import ssrf_safe_httpx_post\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom pydantic import BaseModel, Field\\n\\n\\nclass HomeAssistantControl(LCToolComponent):\\n    \\\"\\\"\\\"This tool is used to control Home Assistant devices.\\n\\n    A very simple tool to control Home Assistant devices.\\n    - The agent only needs to provide action (turn_on, turn_off, toggle) + entity_id (e.g., switch.xxx, light.xxx).\\n    - The domain (e.g., 'switch', 'light') is automatically extracted from entity_id.\\n    \\\"\\\"\\\"\\n\\n    display_name: str = \\\"Home Assistant Control\\\"\\n    description: str = (\\n        \\\"A very simple tool to control Home Assistant devices. \\\"\\n        \\\"Only action (turn_on, turn_off, toggle) and entity_id need to be provided.\\\"\\n    )\\n    documentation: str = \\\"https://developers.home-assistant.io/docs/api/rest/\\\"\\n    icon: str = \\\"HomeAssistant\\\"\\n\\n    # --- Input fields for LangFlow UI (token, URL) ---\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"ha_token\\\",\\n            display_name=\\\"Home Assistant Token\\\",\\n            info=\\\"Home Assistant Long-Lived Access Token\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"base_url\\\",\\n            display_name=\\\"Home Assistant URL\\\",\\n            info=\\\"e.g., http://192.168.0.10:8123\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"default_action\\\",\\n            display_name=\\\"Default Action (Optional)\\\",\\n            info=\\\"One of turn_on, turn_off, toggle\\\",\\n            required=False,\\n        ),\\n        StrInput(\\n            name=\\\"default_entity_id\\\",\\n            display_name=\\\"Default Entity ID (Optional)\\\",\\n            info=\\\"Default entity ID to control (e.g., switch.unknown_switch_3)\\\",\\n            required=False,\\n        ),\\n    ]\\n\\n    # --- Parameters exposed to the agent (Pydantic schema) ---\\n    class ToolSchema(BaseModel):\\n        \\\"\\\"\\\"Parameters to be passed by the agent: action, entity_id only.\\\"\\\"\\\"\\n\\n        action: str = Field(..., description=\\\"Home Assistant service name. (One of turn_on, turn_off, toggle)\\\")\\n        entity_id: str = Field(\\n            ...,\\n            description=\\\"Entity ID to control (e.g., switch.xxx, light.xxx, cover.xxx, etc.).\\\"\\n            \\\"Do not infer; use the list_homeassistant_states tool to retrieve it.\\\",\\n        )\\n\\n    def run_model(self) -> Data:\\n        \\\"\\\"\\\"Used when the 'Run' button is clicked in LangFlow.\\n\\n        - Uses default_action and default_entity_id entered in the UI.\\n        \\\"\\\"\\\"\\n        action = self.default_action or \\\"turn_off\\\"\\n        entity_id = self.default_entity_id or \\\"switch.unknown_switch_3\\\"\\n\\n        result = self._control_device(\\n            ha_token=self.ha_token,\\n            base_url=self.base_url,\\n            action=action,\\n            entity_id=entity_id,\\n        )\\n        return self._make_data_response(result)\\n\\n    def build_tool(self) -> Tool:\\n        \\\"\\\"\\\"Returns a tool to be used by the agent (LLM).\\n\\n        - The agent can only pass action and entity_id as arguments.\\n        \\\"\\\"\\\"\\n        return StructuredTool.from_function(\\n            name=\\\"home_assistant_control\\\",\\n            description=(\\n                \\\"A tool to control Home Assistant devices easily. \\\"\\n                \\\"Parameters: action ('turn_on'/'turn_off'/'toggle'), entity_id ('switch.xxx', etc.).\\\"\\n                \\\"Entity ID must be obtained using the list_homeassistant_states tool and not guessed.\\\"\\n            ),\\n            func=self._control_device_for_tool,  # Wrapper function below\\n            args_schema=self.ToolSchema,\\n        )\\n\\n    def _control_device_for_tool(self, action: str, entity_id: str) -> dict[str, Any] | str:\\n        \\\"\\\"\\\"Function called by the agent.\\n\\n        -> Internally calls _control_device.\\n        \\\"\\\"\\\"\\n        return self._control_device(\\n            ha_token=self.ha_token,\\n            base_url=self.base_url,\\n            action=action,\\n            entity_id=entity_id,\\n        )\\n\\n    def _control_device(\\n        self,\\n        ha_token: str,\\n        base_url: str,\\n        action: str,\\n        entity_id: str,\\n    ) -> dict[str, Any] | str:\\n        \\\"\\\"\\\"Actual logic to call the Home Assistant service.\\n\\n        The domain is extracted from the beginning of the entity_id.\\n        Example: entity_id=\\\"switch.unknown_switch_3\\\" -> domain=\\\"switch\\\".\\n        \\\"\\\"\\\"\\n        try:\\n            domain = entity_id.split(\\\".\\\")[0]  # switch, light, cover, etc.\\n            url = f\\\"{base_url}/api/services/{domain}/{action}\\\"\\n\\n            headers = {\\n                \\\"Authorization\\\": f\\\"Bearer {ha_token}\\\",\\n                \\\"Content-Type\\\": \\\"application/json\\\",\\n            }\\n            payload = {\\\"entity_id\\\": entity_id}\\n\\n            response = ssrf_safe_httpx_post(url, headers=headers, json=payload, timeout=10)\\n            response.raise_for_status()\\n\\n            return response.json()  # HA response JSON on success\\n        except SSRFProtectionError as e:\\n            return f\\\"Error: SSRF Protection: {e}\\\"\\n        except httpx.HTTPError as e:\\n            return f\\\"Error: Failed to call service. {e}\\\"\\n        except Exception as e:  # noqa: BLE001\\n            return f\\\"An unexpected error occurred: {e}\\\"\\n\\n    def _make_data_response(self, result: dict[str, Any] | str) -> Data:\\n        \\\"\\\"\\\"Returns a response in the LangFlow Data format.\\\"\\\"\\\"\\n        if isinstance(result, str):\\n            # Handle error messages\\n            return Data(text=result)\\n\\n        # Convert dict to JSON string\\n        formatted_json = json.dumps(result, indent=2, ensure_ascii=False)\\n        return Data(data=result, text=formatted_json)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/homeassistant/list_home_assistant_states.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fa1aa171f6184d9331986a7907780b618f090ef94bd0636cfbadc7de42458fc6\",\"content\":\"import json\\nfrom typing import Any\\n\\nimport httpx\\nfrom langchain_core.tools import StructuredTool\\nfrom lfx.base.langchain_utilities.model import LCToolComponent\\nfrom lfx.field_typing import Tool\\nfrom lfx.inputs.inputs import SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.ssrf_httpx import ssrf_safe_httpx_get\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\nfrom pydantic import BaseModel, Field\\n\\n\\nclass ListHomeAssistantStates(LCToolComponent):\\n    display_name: str = \\\"List Home Assistant States\\\"\\n    description: str = (\\n        \\\"Retrieve states from Home Assistant. \\\"\\n        \\\"The agent only needs to specify 'filter_domain' (optional). \\\"\\n        \\\"Token and base_url are not exposed to the agent.\\\"\\n    )\\n    documentation: str = \\\"https://developers.home-assistant.io/docs/api/rest/\\\"\\n    icon = \\\"HomeAssistant\\\"\\n\\n    # 1) Define fields to be received in LangFlow UI\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"ha_token\\\",\\n            display_name=\\\"Home Assistant Token\\\",\\n            info=\\\"Home Assistant Long-Lived Access Token\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"base_url\\\",\\n            display_name=\\\"Home Assistant URL\\\",\\n            info=\\\"e.g., http://192.168.0.10:8123\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"filter_domain\\\",\\n            display_name=\\\"Default Filter Domain (Optional)\\\",\\n            info=\\\"light, switch, sensor, etc. (Leave empty to fetch all)\\\",\\n            required=False,\\n        ),\\n    ]\\n\\n    # 2) Pydantic schema containing only parameters exposed to the agent\\n    class ToolSchema(BaseModel):\\n        \\\"\\\"\\\"Parameters to be passed by the agent: filter_domain only.\\\"\\\"\\\"\\n\\n        filter_domain: str = Field(\\\"\\\", description=\\\"Filter domain (e.g., 'light'). If empty, returns all.\\\")\\n\\n    def run_model(self) -> Data:\\n        \\\"\\\"\\\"Execute the LangFlow component.\\n\\n        Uses self.ha_token, self.base_url, self.filter_domain as entered in the UI.\\n        Triggered when 'Run' is clicked directly without an agent.\\n        \\\"\\\"\\\"\\n        filter_domain = self.filter_domain or \\\"\\\"  # Use \\\"\\\" for fetching all states\\n        result = self._list_states(\\n            ha_token=self.ha_token,\\n            base_url=self.base_url,\\n            filter_domain=filter_domain,\\n        )\\n        return self._make_data_response(result)\\n\\n    def build_tool(self) -> Tool:\\n        \\\"\\\"\\\"Build a tool object to be used by the agent.\\n\\n        The agent can only pass 'filter_domain' as a parameter.\\n        'ha_token' and 'base_url' are not exposed (stored as self attributes).\\n        \\\"\\\"\\\"\\n        return StructuredTool.from_function(\\n            name=\\\"list_homeassistant_states\\\",\\n            description=(\\n                \\\"Retrieve states from Home Assistant. \\\"\\n                \\\"You can provide filter_domain='light', 'switch', etc. to narrow results.\\\"\\n            ),\\n            func=self._list_states_for_tool,  # Wrapper function below\\n            args_schema=self.ToolSchema,  # Requires only filter_domain\\n        )\\n\\n    def _list_states_for_tool(self, filter_domain: str = \\\"\\\") -> list[Any] | str:\\n        \\\"\\\"\\\"Execute the tool when called by the agent.\\n\\n        'ha_token' and 'base_url' are stored in self (not exposed).\\n        \\\"\\\"\\\"\\n        return self._list_states(\\n            ha_token=self.ha_token,\\n            base_url=self.base_url,\\n            filter_domain=filter_domain,\\n        )\\n\\n    def _list_states(\\n        self,\\n        ha_token: str,\\n        base_url: str,\\n        filter_domain: str = \\\"\\\",\\n    ) -> list[Any] | str:\\n        \\\"\\\"\\\"Call the Home Assistant /api/states endpoint.\\\"\\\"\\\"\\n        try:\\n            headers = {\\n                \\\"Authorization\\\": f\\\"Bearer {ha_token}\\\",\\n                \\\"Content-Type\\\": \\\"application/json\\\",\\n            }\\n            url = f\\\"{base_url}/api/states\\\"\\n            response = ssrf_safe_httpx_get(url, headers=headers, timeout=10)\\n            response.raise_for_status()\\n\\n            all_states = response.json()\\n            if filter_domain:\\n                return [st for st in all_states if st.get(\\\"entity_id\\\", \\\"\\\").startswith(f\\\"{filter_domain}.\\\")]\\n\\n        except SSRFProtectionError as e:\\n            return f\\\"Error: SSRF Protection: {e}\\\"\\n        except httpx.HTTPError as e:\\n            return f\\\"Error: Failed to fetch states. {e}\\\"\\n        except (ValueError, TypeError) as e:\\n            return f\\\"Error processing response: {e}\\\"\\n        return all_states\\n\\n    def _make_data_response(self, result: list[Any] | str | dict) -> Data:\\n        \\\"\\\"\\\"Format the response into a Data object.\\\"\\\"\\\"\\n        try:\\n            if isinstance(result, list):\\n                # Wrap list data into a dictionary and convert to text\\n                wrapped_result = {\\\"result\\\": result}\\n                return Data(data=wrapped_result, text=json.dumps(wrapped_result, indent=2, ensure_ascii=False))\\n            if isinstance(result, dict):\\n                # Return dictionary as-is\\n                return Data(data=result, text=json.dumps(result, indent=2, ensure_ascii=False))\\n            if isinstance(result, str):\\n                # Return error messages or strings\\n                return Data(data={}, text=result)\\n\\n            # Handle unexpected data types\\n            return Data(data={}, text=\\\"Error: Unexpected response format.\\\")\\n        except (TypeError, ValueError) as e:\\n            # Handle specific exceptions during formatting\\n            return Data(data={}, text=f\\\"Error: Failed to process response. Details: {e!s}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/huggingface/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"6fc345a39fbdcdb058e1ff5454ccf343d19d9d21aa1d844a496e5877a4e605ac\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from .huggingface import HuggingFaceEndpointsComponent\\n    from .huggingface_inference_api import HuggingFaceInferenceAPIEmbeddingsComponent\\n\\n_dynamic_imports = {\\n    \\\"HuggingFaceEndpointsComponent\\\": \\\"huggingface\\\",\\n    \\\"HuggingFaceInferenceAPIEmbeddingsComponent\\\": \\\"huggingface_inference_api\\\",\\n}\\n\\n__all__ = [\\n    \\\"HuggingFaceEndpointsComponent\\\",\\n    \\\"HuggingFaceInferenceAPIEmbeddingsComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import huggingface components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/huggingface/huggingface.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"829ce3d842400f5a781ca6c6f302946c2a0e0303ba68821148744b7a392bc093\",\"content\":\"from typing import Any\\n\\nfrom langchain_community.llms.huggingface_endpoint import HuggingFaceEndpoint\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.io import DictInput, DropdownInput, FloatInput, IntInput, SecretStrInput, SliderInput, StrInput\\nfrom tenacity import retry, stop_after_attempt, wait_fixed\\n\\n# TODO: langchain_community.llms.huggingface_endpoint is depreciated.\\n#  Need to update to langchain_huggingface, but have dependency with langchain_core 0.3.0\\n\\n# Constants\\nDEFAULT_MODEL = \\\"meta-llama/Llama-3.3-70B-Instruct\\\"\\n\\n\\nclass HuggingFaceEndpointsComponent(LCModelComponent):\\n    display_name: str = \\\"Hugging Face\\\"\\n    description: str = \\\"Generate text using Hugging Face Inference APIs.\\\"\\n    icon = \\\"HuggingFace\\\"\\n    name = \\\"HuggingFaceModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        DropdownInput(\\n            name=\\\"model_id\\\",\\n            display_name=\\\"Model ID\\\",\\n            info=\\\"Select a model from Hugging Face Hub\\\",\\n            options=[\\n                DEFAULT_MODEL,\\n                \\\"mistralai/Mixtral-8x7B-Instruct-v0.1\\\",\\n                \\\"mistralai/Mistral-7B-Instruct-v0.3\\\",\\n                \\\"meta-llama/Llama-3.1-8B-Instruct\\\",\\n                \\\"Qwen/Qwen2.5-Coder-32B-Instruct\\\",\\n                \\\"Qwen/QwQ-32B-Preview\\\",\\n                \\\"openai-community/gpt2\\\",\\n                \\\"custom\\\",\\n            ],\\n            value=DEFAULT_MODEL,\\n            required=True,\\n            real_time_refresh=True,\\n        ),\\n        StrInput(\\n            name=\\\"custom_model\\\",\\n            display_name=\\\"Custom Model ID\\\",\\n            info=\\\"Enter a custom model ID from Hugging Face Hub\\\",\\n            value=\\\"\\\",\\n            show=False,\\n            required=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_new_tokens\\\", display_name=\\\"Max New Tokens\\\", value=512, info=\\\"Maximum number of generated tokens\\\"\\n        ),\\n        IntInput(\\n            name=\\\"top_k\\\",\\n            display_name=\\\"Top K\\\",\\n            advanced=True,\\n            info=\\\"The number of highest probability vocabulary tokens to keep for top-k-filtering\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"top_p\\\",\\n            display_name=\\\"Top P\\\",\\n            value=0.95,\\n            advanced=True,\\n            info=(\\n                \\\"If set to < 1, only the smallest set of most probable tokens with \\\"\\n                \\\"probabilities that add up to `top_p` or higher are kept for generation\\\"\\n            ),\\n        ),\\n        FloatInput(\\n            name=\\\"typical_p\\\",\\n            display_name=\\\"Typical P\\\",\\n            value=0.95,\\n            advanced=True,\\n            info=\\\"Typical Decoding mass.\\\",\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.8,\\n            range_spec=RangeSpec(min=0, max=2, step=0.01),\\n            info=\\\"The value used to module the logits distribution\\\",\\n            advanced=True,\\n        ),\\n        FloatInput(\\n            name=\\\"repetition_penalty\\\",\\n            display_name=\\\"Repetition Penalty\\\",\\n            info=\\\"The parameter for repetition penalty. 1.0 means no penalty.\\\",\\n            advanced=True,\\n        ),\\n        StrInput(\\n            name=\\\"inference_endpoint\\\",\\n            display_name=\\\"Inference Endpoint\\\",\\n            value=\\\"https://api-inference.huggingface.co/models/\\\",\\n            info=\\\"Custom inference endpoint URL.\\\",\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"task\\\",\\n            display_name=\\\"Task\\\",\\n            options=[\\\"text2text-generation\\\", \\\"text-generation\\\", \\\"summarization\\\", \\\"translation\\\"],\\n            value=\\\"text-generation\\\",\\n            advanced=True,\\n            info=\\\"The task to call the model with. Should be a task that returns `generated_text` or `summary_text`.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"huggingfacehub_api_token\\\", display_name=\\\"HuggingFace HubAPI Token\\\", password=True, required=True\\n        ),\\n        DictInput(name=\\\"model_kwargs\\\", display_name=\\\"Model Keyword Arguments\\\", advanced=True),\\n        IntInput(name=\\\"retry_attempts\\\", display_name=\\\"Retry Attempts\\\", value=1, advanced=True),\\n    ]\\n\\n    def get_api_url(self) -> str:\\n        if \\\"huggingface\\\" in self.inference_endpoint.lower():\\n            if self.model_id == \\\"custom\\\":\\n                if not self.custom_model:\\n                    error_msg = \\\"Custom model ID is required when 'custom' is selected\\\"\\n                    raise ValueError(error_msg)\\n                return f\\\"{self.inference_endpoint}{self.custom_model}\\\"\\n            return f\\\"{self.inference_endpoint}{self.model_id}\\\"\\n        return self.inference_endpoint\\n\\n    async def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None) -> dict:\\n        \\\"\\\"\\\"Update build configuration based on field updates.\\\"\\\"\\\"\\n        try:\\n            if field_name is None or field_name == \\\"model_id\\\":\\n                # If model_id is custom, show custom model field\\n                if field_value == \\\"custom\\\":\\n                    build_config[\\\"custom_model\\\"][\\\"show\\\"] = True\\n                    build_config[\\\"custom_model\\\"][\\\"required\\\"] = True\\n                else:\\n                    build_config[\\\"custom_model\\\"][\\\"show\\\"] = False\\n                    build_config[\\\"custom_model\\\"][\\\"value\\\"] = \\\"\\\"\\n\\n        except (KeyError, AttributeError) as e:\\n            self.log(f\\\"Error updating build config: {e!s}\\\")\\n        return build_config\\n\\n    def create_huggingface_endpoint(\\n        self,\\n        task: str | None,\\n        huggingfacehub_api_token: str | None,\\n        model_kwargs: dict[str, Any],\\n        max_new_tokens: int,\\n        top_k: int | None,\\n        top_p: float,\\n        typical_p: float | None,\\n        temperature: float | None,\\n        repetition_penalty: float | None,\\n    ) -> HuggingFaceEndpoint:\\n        retry_attempts = self.retry_attempts\\n        endpoint_url = self.get_api_url()\\n\\n        @retry(stop=stop_after_attempt(retry_attempts), wait=wait_fixed(2))\\n        def _attempt_create():\\n            return HuggingFaceEndpoint(\\n                endpoint_url=endpoint_url,\\n                task=task,\\n                huggingfacehub_api_token=huggingfacehub_api_token,\\n                model_kwargs=model_kwargs,\\n                max_new_tokens=max_new_tokens,\\n                top_k=top_k,\\n                top_p=top_p,\\n                typical_p=typical_p,\\n                temperature=temperature,\\n                repetition_penalty=repetition_penalty,\\n            )\\n\\n        return _attempt_create()\\n\\n    def build_model(self) -> LanguageModel:\\n        task = self.task or None\\n        huggingfacehub_api_token = self.huggingfacehub_api_token\\n        model_kwargs = self.model_kwargs or {}\\n        max_new_tokens = self.max_new_tokens\\n        top_k = self.top_k or None\\n        top_p = self.top_p\\n        typical_p = self.typical_p or None\\n        temperature = self.temperature or 0.8\\n        repetition_penalty = self.repetition_penalty or None\\n\\n        try:\\n            llm = self.create_huggingface_endpoint(\\n                task=task,\\n                huggingfacehub_api_token=huggingfacehub_api_token,\\n                model_kwargs=model_kwargs,\\n                max_new_tokens=max_new_tokens,\\n                top_k=top_k,\\n                top_p=top_p,\\n                typical_p=typical_p,\\n                temperature=temperature,\\n                repetition_penalty=repetition_penalty,\\n            )\\n        except Exception as e:\\n            msg = \\\"Could not connect to Hugging Face Endpoints API.\\\"\\n            raise ValueError(msg) from e\\n\\n        return llm\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/huggingface/huggingface_inference_api.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"721a96036a36440656ec28dbc24cb25848e997e39c368aa48d07574ebe5046d2\",\"content\":\"from urllib.parse import urlparse\\n\\nimport httpx\\nfrom langchain_community.embeddings.huggingface import HuggingFaceInferenceAPIEmbeddings\\nfrom lfx.base.embeddings.model import LCEmbeddingsModel\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.io import MessageTextInput, Output, SecretStrInput\\nfrom lfx.utils.ssrf_httpx import ssrf_safe_httpx_get, validate_url_for_ssrf_or_raise\\n\\n# Next update: use langchain_huggingface\\nfrom pydantic import SecretStr\\nfrom tenacity import retry, stop_after_attempt, wait_fixed\\n\\n\\nclass HuggingFaceInferenceAPIEmbeddingsComponent(LCEmbeddingsModel):\\n    display_name = \\\"Hugging Face Embeddings Inference\\\"\\n    description = \\\"Generate embeddings using Hugging Face Text Embeddings Inference (TEI)\\\"\\n    documentation = \\\"https://huggingface.co/docs/text-embeddings-inference/index\\\"\\n    icon = \\\"HuggingFace\\\"\\n    name = \\\"HuggingFaceInferenceAPIEmbeddings\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"HuggingFace API Key\\\",\\n            advanced=False,\\n            info=\\\"Required for non-local inference endpoints. Local inference does not require an API Key.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"inference_endpoint\\\",\\n            display_name=\\\"Inference Endpoint\\\",\\n            required=True,\\n            value=\\\"https://api-inference.huggingface.co/models/\\\",\\n            info=\\\"Custom inference endpoint URL.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            value=\\\"BAAI/bge-large-en-v1.5\\\",\\n            info=\\\"The name of the model to use for text embeddings.\\\",\\n            required=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Embeddings\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    def validate_inference_endpoint(self, inference_endpoint: str) -> bool:\\n        parsed_url = urlparse(inference_endpoint)\\n        if not all([parsed_url.scheme, parsed_url.netloc]):\\n            msg = (\\n                f\\\"Invalid inference endpoint format: '{self.inference_endpoint}'. \\\"\\n                \\\"Please ensure the URL includes both a scheme (e.g., 'http://' or 'https://') and a domain name. \\\"\\n                \\\"Example: 'http://localhost:8080' or 'https://api.example.com'\\\"\\n            )\\n            raise ValueError(msg)\\n\\n        try:\\n            response = ssrf_safe_httpx_get(f\\\"{inference_endpoint}/health\\\", timeout=5)\\n        except httpx.HTTPError as e:\\n            msg = (\\n                f\\\"Inference endpoint '{inference_endpoint}' is not responding. \\\"\\n                \\\"Please ensure the URL is correct and the service is running.\\\"\\n            )\\n            raise ValueError(msg) from e\\n\\n        if response.status_code != httpx.codes.OK:\\n            msg = f\\\"Hugging Face health check failed: {response.status_code}\\\"\\n            raise ValueError(msg)\\n        # returning True to solve linting error\\n        return True\\n\\n    def get_api_url(self) -> str:\\n        if \\\"huggingface\\\" in self.inference_endpoint.lower():\\n            return f\\\"{self.inference_endpoint}\\\"\\n        return self.inference_endpoint\\n\\n    @retry(stop=stop_after_attempt(3), wait=wait_fixed(2))\\n    def create_huggingface_embeddings(\\n        self, api_key: SecretStr, api_url: str, model_name: str\\n    ) -> HuggingFaceInferenceAPIEmbeddings:\\n        return HuggingFaceInferenceAPIEmbeddings(api_key=api_key, api_url=api_url, model_name=model_name)\\n\\n    def build_embeddings(self) -> Embeddings:\\n        api_url = self.get_api_url()\\n        validate_url_for_ssrf_or_raise(api_url)\\n\\n        is_local_url = (\\n            api_url.startswith((\\\"http://localhost\\\", \\\"http://127.0.0.1\\\", \\\"http://0.0.0.0\\\", \\\"http://docker\\\"))\\n            or \\\"huggingface.co\\\" not in api_url.lower()\\n        )\\n\\n        if not self.api_key and is_local_url:\\n            self.validate_inference_endpoint(api_url)\\n            api_key = SecretStr(\\\"APIKeyForLocalDeployment\\\")\\n        elif not self.api_key:\\n            msg = \\\"API Key is required for non-local inference endpoints\\\"\\n            raise ValueError(msg)\\n        else:\\n            api_key = SecretStr(self.api_key).get_secret_value()\\n\\n        try:\\n            return self.create_huggingface_embeddings(api_key, api_url, self.model_name)\\n        except Exception as e:\\n            msg = \\\"Could not connect to Hugging Face Inference API.\\\"\\n            raise ValueError(msg) from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/icosacomputing/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"341c9633e20c3dfecdd6539e6437adf02bc86bc036e641b7c8a8ab718c12e76c\",\"content\":\"from .combinatorial_reasoner import CombinatorialReasonerComponent\\n\\n__all__ = [\\n    \\\"CombinatorialReasonerComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/icosacomputing/combinatorial_reasoner.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"669a9ee8d0527fac427f9acff336d3604a8afaaa670045a04bbb8c51211f3f1c\",\"content\":\"import requests\\nfrom lfx.base.models.openai_constants import OPENAI_CHAT_MODEL_NAMES\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import DropdownInput, SecretStrInput, StrInput\\nfrom lfx.io import MessageTextInput, Output\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\nfrom requests.auth import HTTPBasicAuth\\n\\n\\nclass CombinatorialReasonerComponent(Component):\\n    display_name = \\\"Combinatorial Reasoner\\\"\\n    description = \\\"Uses Combinatorial Optimization to construct an optimal prompt with embedded reasons. Sign up here:\\\\nhttps://forms.gle/oWNv2NKjBNaqqvCx6\\\"\\n    icon = \\\"Icosa\\\"\\n    name = \\\"Combinatorial Reasoner\\\"\\n\\n    inputs = [\\n        MessageTextInput(name=\\\"prompt\\\", display_name=\\\"Prompt\\\", required=True),\\n        SecretStrInput(\\n            name=\\\"openai_api_key\\\",\\n            display_name=\\\"OpenAI API Key\\\",\\n            info=\\\"The OpenAI API Key to use for the OpenAI model.\\\",\\n            advanced=False,\\n            value=\\\"OPENAI_API_KEY\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"username\\\",\\n            display_name=\\\"Username\\\",\\n            info=\\\"Username to authenticate access to Icosa CR API\\\",\\n            advanced=False,\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"password\\\",\\n            display_name=\\\"Combinatorial Reasoner Password\\\",\\n            info=\\\"Password to authenticate access to Icosa CR API.\\\",\\n            advanced=False,\\n            required=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            advanced=False,\\n            options=OPENAI_CHAT_MODEL_NAMES,\\n            value=OPENAI_CHAT_MODEL_NAMES[0],\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(\\n            display_name=\\\"Optimized Prompt\\\",\\n            name=\\\"optimized_prompt\\\",\\n            method=\\\"build_prompt\\\",\\n        ),\\n        Output(display_name=\\\"Selected Reasons\\\", name=\\\"reasons\\\", method=\\\"build_reasons\\\"),\\n    ]\\n\\n    def build_prompt(self) -> Message:\\n        params = {\\n            \\\"prompt\\\": self.prompt,\\n            \\\"apiKey\\\": self.openai_api_key,\\n            \\\"model\\\": self.model_name,\\n        }\\n\\n        creds = HTTPBasicAuth(self.username, password=self.password)\\n        response = requests.post(\\n            \\\"https://cr-api.icosacomputing.com/cr/langflow\\\",\\n            json=params,\\n            auth=creds,\\n            timeout=100,\\n        )\\n        response.raise_for_status()\\n\\n        prompt = response.json()[\\\"prompt\\\"]\\n\\n        self.reasons = response.json()[\\\"finalReasons\\\"]\\n        return prompt\\n\\n    def build_reasons(self) -> Data:\\n        # list of selected reasons\\n        final_reasons = [reason[0] for reason in self.reasons]\\n        return Data(value=final_reasons)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"bea4e6cb9b318ff08076491d4ad6aabaf2ebcdeec53301854e371aa5dd2be5e5\",\"content\":\"from .ai_scrape import JigsawStackAIScraperComponent\\nfrom .ai_web_search import JigsawStackAIWebSearchComponent\\nfrom .file_read import JigsawStackFileReadComponent\\nfrom .file_upload import JigsawStackFileUploadComponent\\nfrom .image_generation import JigsawStackImageGenerationComponent\\nfrom .nsfw import JigsawStackNSFWComponent\\nfrom .object_detection import JigsawStackObjectDetectionComponent\\nfrom .sentiment import JigsawStackSentimentComponent\\nfrom .text_to_sql import JigsawStackTextToSQLComponent\\nfrom .vocr import JigsawStackVOCRComponent\\n\\n__all__ = [\\n    \\\"JigsawStackAIScraperComponent\\\",\\n    \\\"JigsawStackAIWebSearchComponent\\\",\\n    \\\"JigsawStackFileReadComponent\\\",\\n    \\\"JigsawStackFileUploadComponent\\\",\\n    \\\"JigsawStackImageGenerationComponent\\\",\\n    \\\"JigsawStackNSFWComponent\\\",\\n    \\\"JigsawStackObjectDetectionComponent\\\",\\n    \\\"JigsawStackSentimentComponent\\\",\\n    \\\"JigsawStackTextToSQLComponent\\\",\\n    \\\"JigsawStackVOCRComponent\\\",\\n]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/ai_scrape.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"08a0063e256492c6c4de3e08f6403fae7d2b3f0eed6ce55a7a36fa2ba5e14410\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageTextInput, Output, SecretStrInput\\nfrom lfx.schema.data import Data\\n\\nMAX_ELEMENT_PROMPTS = 5\\n\\n\\nclass JigsawStackAIScraperComponent(Component):\\n    display_name = \\\"AI Scraper\\\"\\n    description = \\\"Scrape any website instantly and get consistent structured data \\\\\\n        in seconds without writing any css selector code\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/scrape\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackAIScraper\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            info=\\\"URL of the page to scrape. Either url or html is required, but not both.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"html\\\",\\n            display_name=\\\"HTML\\\",\\n            info=\\\"HTML content to scrape. Either url or html is required, but not both.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"element_prompts\\\",\\n            display_name=\\\"Element Prompts\\\",\\n            info=\\\"Items on the page to be scraped (maximum 5). E.g. 'Plan price', 'Plan title'\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"root_element_selector\\\",\\n            display_name=\\\"Root Element Selector\\\",\\n            info=\\\"CSS selector to limit the scope of scraping to a specific element and its children\\\",\\n            required=False,\\n            value=\\\"main\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"AI Scraper Results\\\", name=\\\"scrape_results\\\", method=\\\"scrape\\\"),\\n    ]\\n\\n    def scrape(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            # Build request object\\n            scrape_params: dict = {}\\n            if self.url:\\n                scrape_params[\\\"url\\\"] = self.url\\n            if self.html:\\n                scrape_params[\\\"html\\\"] = self.html\\n\\n            url_value = scrape_params.get(\\\"url\\\", \\\"\\\")\\n            html_value = scrape_params.get(\\\"html\\\", \\\"\\\")\\n            if (not url_value or not url_value.strip()) and (not html_value or not html_value.strip()):\\n                url_or_html_error = \\\"Either 'url' or 'html' must be provided for scraping\\\"\\n                raise ValueError(url_or_html_error)\\n\\n            # Process element_prompts with proper type handling\\n            element_prompts_list: list[str] = []\\n            if self.element_prompts:\\n                element_prompts_value: str | list[str] = self.element_prompts\\n\\n                if isinstance(element_prompts_value, str):\\n                    if \\\",\\\" not in element_prompts_value:\\n                        element_prompts_list = [element_prompts_value]\\n                    else:\\n                        element_prompts_list = element_prompts_value.split(\\\",\\\")\\n                elif isinstance(element_prompts_value, list):\\n                    element_prompts_list = element_prompts_value\\n                else:\\n                    # Fallback for other types\\n                    element_prompts_list = str(element_prompts_value).split(\\\",\\\")\\n\\n                if len(element_prompts_list) > MAX_ELEMENT_PROMPTS:\\n                    max_elements_error = \\\"Maximum of 5 element prompts allowed\\\"\\n                    raise ValueError(max_elements_error)\\n                if len(element_prompts_list) == 0:\\n                    invalid_elements_error = \\\"Element prompts cannot be empty\\\"\\n                    raise ValueError(invalid_elements_error)\\n\\n                scrape_params[\\\"element_prompts\\\"] = element_prompts_list\\n\\n            if self.root_element_selector:\\n                scrape_params[\\\"root_element_selector\\\"] = self.root_element_selector\\n\\n            # Call web scraping\\n            response = client.web.ai_scrape(scrape_params)\\n\\n            if not response.get(\\\"success\\\", False):\\n                fail_error = \\\"JigsawStack API request failed.\\\"\\n                raise ValueError(fail_error)\\n\\n            result_data = response\\n\\n            self.status = \\\"AI scrape process is now complete.\\\"\\n\\n            return Data(data=result_data)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/ai_web_search.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"5e821ee44040524662bfafe348783c856f8932d949561bb9775b2af88e5429fe\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import BoolInput, DropdownInput, Output, QueryInput, SecretStrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\n\\n\\nclass JigsawStackAIWebSearchComponent(Component):\\n    display_name = \\\"AI Web Search\\\"\\n    description = \\\"Effortlessly search the Web and get access to high-quality results powered with AI.\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/web/ai-search\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackAISearch\\\"\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        QueryInput(\\n            name=\\\"query\\\",\\n            display_name=\\\"Query\\\",\\n            info=\\\"The search value. The maximum query character length is 400\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"ai_overview\\\",\\n            display_name=\\\"AI Overview\\\",\\n            info=\\\"Include AI powered overview in the search results\\\",\\n            required=False,\\n            value=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"safe_search\\\",\\n            display_name=\\\"Safe Search\\\",\\n            info=\\\"Enable safe search to filter out adult content\\\",\\n            required=False,\\n            options=[\\\"moderate\\\", \\\"strict\\\", \\\"off\\\"],\\n            value=\\\"off\\\",\\n        ),\\n        BoolInput(\\n            name=\\\"spell_check\\\",\\n            display_name=\\\"Spell Check\\\",\\n            info=\\\"Spell check the search query\\\",\\n            required=False,\\n            value=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"AI Search Results\\\", name=\\\"search_results\\\", method=\\\"search\\\"),\\n        Output(display_name=\\\"Content Text\\\", name=\\\"content_text\\\", method=\\\"get_content_text\\\"),\\n    ]\\n\\n    def search(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            # build request object\\n            search_params = {}\\n            if self.query:\\n                search_params[\\\"query\\\"] = self.query\\n            if self.ai_overview is not None:\\n                search_params[\\\"ai_overview\\\"] = self.ai_overview\\n            if self.safe_search:\\n                search_params[\\\"safe_search\\\"] = self.safe_search\\n            if self.spell_check is not None:\\n                search_params[\\\"spell_check\\\"] = self.spell_check\\n\\n            # Call web scraping\\n            response = client.web.search(search_params)\\n\\n            api_error_msg = \\\"JigsawStack API returned unsuccessful response\\\"\\n            if not response.get(\\\"success\\\", False):\\n                raise ValueError(api_error_msg)\\n\\n            # Create comprehensive data object\\n            result_data = {\\n                \\\"query\\\": self.query,\\n                \\\"ai_overview\\\": response.get(\\\"ai_overview\\\", \\\"\\\"),\\n                \\\"spell_fixed\\\": response.get(\\\"spell_fixed\\\", False),\\n                \\\"is_safe\\\": response.get(\\\"is_safe\\\", True),\\n                \\\"results\\\": response.get(\\\"results\\\", []),\\n                \\\"success\\\": True,\\n            }\\n\\n            self.status = f\\\"Search complete for: {response.get('query', '')}\\\"\\n\\n            return Data(data=result_data)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\\n    def get_content_text(self) -> Message:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError:\\n            return Message(text=\\\"Error: JigsawStack package not found.\\\")\\n\\n        try:\\n            # Initialize JigsawStack client\\n            client = JigsawStack(api_key=self.api_key)\\n            search_params = {}\\n            if self.query:\\n                search_params[\\\"query\\\"] = self.query\\n            if self.ai_overview is not None:\\n                search_params[\\\"ai_overview\\\"] = self.ai_overview\\n            if self.safe_search:\\n                search_params[\\\"safe_search\\\"] = self.safe_search\\n            if self.spell_check is not None:\\n                search_params[\\\"spell_check\\\"] = self.spell_check\\n\\n            # Call web scraping\\n            response = client.web.search(search_params)\\n\\n            request_failed_msg = \\\"Request Failed\\\"\\n            if not response.get(\\\"success\\\", False):\\n                raise JigsawStackError(request_failed_msg)\\n\\n            # Return the content as text\\n            content = response.get(\\\"ai_overview\\\", \\\"\\\")\\n            return Message(text=content)\\n\\n        except JigsawStackError as e:\\n            return Message(text=f\\\"Error while using AI Search: {e!s}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/file_read.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"84d122f46fb1c5b9c1f993cd3a7d4e56ce65d4ddb32122ab78873000f36a925f\",\"content\":\"import tempfile\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackFileReadComponent(Component):\\n    display_name = \\\"File Read\\\"\\n    description = \\\"Read any previously uploaded file seamlessly from \\\\\\n        JigsawStack File Storage and use it in your AI applications.\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/store/file/get\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackFileRead\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"key\\\",\\n            display_name=\\\"Key\\\",\\n            info=\\\"The key used to retrieve the file from JigsawStack File Storage.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"File Path\\\", name=\\\"file_path\\\", method=\\\"read_and_save_file\\\"),\\n    ]\\n\\n    def read_and_save_file(self) -> Data:\\n        \\\"\\\"\\\"Read file from JigsawStack and save to temp file, return file path.\\\"\\\"\\\"\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n            if not self.key or self.key.strip() == \\\"\\\":\\n                invalid_key_error = \\\"Key is required to read a file from JigsawStack File Storage.\\\"\\n                raise ValueError(invalid_key_error)\\n\\n            # Download file content\\n            response = client.store.get(self.key)\\n\\n            # Determine file extension\\n            file_extension = self._detect_file_extension(response)\\n\\n            # Create temporary file\\n            with tempfile.NamedTemporaryFile(\\n                delete=False, suffix=file_extension, prefix=f\\\"jigsawstack_{self.key}_\\\"\\n            ) as temp_file:\\n                if isinstance(response, bytes):\\n                    temp_file.write(response)\\n                else:\\n                    # Handle string content\\n                    temp_file.write(response.encode(\\\"utf-8\\\"))\\n\\n                temp_path = temp_file.name\\n\\n            return Data(\\n                data={\\n                    \\\"file_path\\\": temp_path,\\n                    \\\"key\\\": self.key,\\n                    \\\"file_extension\\\": file_extension,\\n                    \\\"size\\\": len(response) if isinstance(response, bytes) else len(str(response)),\\n                    \\\"success\\\": True,\\n                }\\n            )\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\\n    def _detect_file_extension(self, content) -> str:\\n        \\\"\\\"\\\"Detect file extension based on content headers.\\\"\\\"\\\"\\n        if isinstance(content, bytes):\\n            # Check magic numbers for common file types\\n            if content.startswith(b\\\"\\\\xff\\\\xd8\\\\xff\\\"):\\n                return \\\".jpg\\\"\\n            if content.startswith(b\\\"\\\\x89PNG\\\\r\\\\n\\\\x1a\\\\n\\\"):\\n                return \\\".png\\\"\\n            if content.startswith((b\\\"GIF87a\\\", b\\\"GIF89a\\\")):\\n                return \\\".gif\\\"\\n            if content.startswith(b\\\"%PDF\\\"):\\n                return \\\".pdf\\\"\\n            if content.startswith(b\\\"PK\\\\x03\\\\x04\\\"):  # ZIP/DOCX/XLSX\\n                return \\\".zip\\\"\\n            if content.startswith(b\\\"\\\\x00\\\\x00\\\\x01\\\\x00\\\"):  # ICO\\n                return \\\".ico\\\"\\n            if content.startswith(b\\\"RIFF\\\") and b\\\"WEBP\\\" in content[:12]:\\n                return \\\".webp\\\"\\n            if content.startswith((b\\\"\\\\xff\\\\xfb\\\", b\\\"\\\\xff\\\\xf3\\\", b\\\"\\\\xff\\\\xf2\\\")):\\n                return \\\".mp3\\\"\\n            if content.startswith((b\\\"ftypmp4\\\", b\\\"\\\\x00\\\\x00\\\\x00\\\\x20ftypmp4\\\")):\\n                return \\\".mp4\\\"\\n            # Try to decode as text\\n            try:\\n                content.decode(\\\"utf-8\\\")\\n                return \\\".txt\\\"  # noqa: TRY300\\n            except UnicodeDecodeError:\\n                return \\\".bin\\\"  # Binary file\\n        else:\\n            # String content\\n            return \\\".txt\\\"\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/file_upload.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8261dc72a65563faf049c9d15361f4604e510873f38063855d9c8c73482d76bd\",\"content\":\"from pathlib import Path\\n\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.io import BoolInput, FileInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackFileUploadComponent(Component):\\n    display_name = \\\"File Upload\\\"\\n    description = \\\"Store any file seamlessly on JigsawStack File Storage and use it in your AI applications. \\\\\\n        Supports various file types including images, documents, and more.\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/store/file/add\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackFileUpload\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        FileInput(\\n            name=\\\"file\\\",\\n            display_name=\\\"File\\\",\\n            info=\\\"Upload file to be stored on JigsawStack File Storage.\\\",\\n            required=True,\\n            file_types=[\\\"pdf\\\", \\\"png\\\", \\\"jpg\\\", \\\"jpeg\\\", \\\"mp4\\\", \\\"mp3\\\", \\\"txt\\\", \\\"docx\\\", \\\"xlsx\\\"],\\n        ),\\n        StrInput(\\n            name=\\\"key\\\",\\n            display_name=\\\"Key\\\",\\n            info=\\\"The key used to store the file on JigsawStack File Storage. \\\\\\n                If not provided, a unique key will be generated.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"overwrite\\\",\\n            display_name=\\\"Overwrite Existing File\\\",\\n            info=\\\"If true, will overwrite the existing file with the same key. \\\\\\n                If false, will return an error if the file already exists.\\\",\\n            required=False,\\n            value=True,\\n        ),\\n        BoolInput(\\n            name=\\\"temp_public_url\\\",\\n            display_name=\\\"Return Temporary Public URL\\\",\\n            info=\\\"If true, will return a temporary public URL which lasts for a limited time. \\\\\\n                If false, will return the file store key which can only be accessed by the owner.\\\",\\n            required=False,\\n            value=False,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"File Store Result\\\", name=\\\"file_upload_result\\\", method=\\\"upload_file\\\"),\\n    ]\\n\\n    def upload_file(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            file_path = Path(self.file)\\n            with Path.open(file_path, \\\"rb\\\") as f:\\n                file_content = f.read()\\n            params = {}\\n\\n            if self.key:\\n                # if key is provided, use it as the file store key\\n                params[\\\"key\\\"] = self.key\\n            if self.overwrite is not None:\\n                # if overwrite is provided, use it to determine if the file should be overwritten\\n                params[\\\"overwrite\\\"] = self.overwrite\\n            if self.temp_public_url is not None:\\n                # if temp_public_url is provided, use it to determine if a temporary public URL should\\n                params[\\\"temp_public_url\\\"] = self.temp_public_url\\n\\n            response = client.store.upload(file_content, params)\\n            return Data(data=response)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/image_generation.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"463f8efbaa18f314717818535f3d349b428a2060352fb06a9d38b311e9cdfb11\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import DropdownInput, IntInput, MessageTextInput, Output, SecretStrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackImageGenerationComponent(Component):\\n    display_name = \\\"Image Generation\\\"\\n    description = \\\"Generate an image based on the given text by employing AI models like Flux, \\\\\\n        Stable Diffusion, and other top models.\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/image-generation\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackImageGeneration\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"prompt\\\",\\n            display_name=\\\"Prompt\\\",\\n            info=\\\"The text prompt to generate the image from. Must be between 1-5000 characters.\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"aspect_ratio\\\",\\n            display_name=\\\"Aspect Ratio\\\",\\n            info=\\\"The aspect ratio of the generated image. Must be one of the following:\\\\\\n                '1:1', '16:9', '21:9', '3:2', '2:3', '4:5', '5:4', '3:4', '4:3', '9:16', '9:21' \\\\\\n                Default is 1:1.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            info=\\\"A valid URL where the generated image will be sent.\\\",\\n            required=False,\\n        ),\\n        MessageTextInput(\\n            name=\\\"file_store_key\\\",\\n            display_name=\\\"File Store Key\\\",\\n            info=\\\"The key used to store the image on Jigsawstack File Storage. Not required if url is specified.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"width\\\",\\n            display_name=\\\"Width\\\",\\n            info=\\\"The width of the image. Must be between 256-1920 pixels.\\\",\\n            required=False,\\n        ),\\n        IntInput(\\n            name=\\\"height\\\",\\n            display_name=\\\"Height\\\",\\n            info=\\\"The height of the image. Must be between 256-1920 pixels.\\\",\\n            required=False,\\n        ),\\n        IntInput(\\n            name=\\\"steps\\\",\\n            display_name=\\\"Steps\\\",\\n            info=\\\"The number of denoising steps. Must be between 1-90. \\\\\\n                Higher values produce better quality images but take more time to generate.\\\",\\n            required=False,\\n        ),\\n        DropdownInput(\\n            name=\\\"output_format\\\",\\n            display_name=\\\"Output Format\\\",\\n            info=\\\"The output format of the generated image. Must be one of the following values:\\\\\\n                png or svg\\\",\\n            required=False,\\n            options=[\\\"png\\\", \\\"svg\\\"],\\n            value=\\\"png\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"negative_prompt\\\",\\n            display_name=\\\"Negative Prompt\\\",\\n            info=\\\"The text prompt to avoid in the generated image. \\\\\\n                Must be between 1-5000 characters.\\\",\\n            required=False,\\n            tool_mode=True,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"seed\\\",\\n            display_name=\\\"Seed\\\",\\n            info=\\\"Makes generation deterministic.\\\\\\n                Using the same seed and set of parameters will produce identical image each time.\\\",\\n            required=False,\\n            tool_mode=True,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"guidance\\\",\\n            display_name=\\\"Guidance Scale\\\",\\n            info=\\\"Higher guidance forces the model to better follow the prompt, \\\\\\n                but may result in lower quality output. Must be between 1-28.\\\",\\n            required=False,\\n            tool_mode=True,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Image Generation Results\\\", name=\\\"image_generation_results\\\", method=\\\"generate_image\\\"),\\n    ]\\n\\n    def generate_image(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            min_character_length = 1\\n            max_character_length = 5000\\n            min_width = 256\\n            max_width = 1920\\n            min_height = 256\\n            max_height = 1920\\n            min_steps = 1\\n            max_steps = 90\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            if not self.prompt or len(self.prompt) < min_character_length or len(self.prompt) > max_character_length:\\n                invalid_prompt_error = f\\\"Prompts must be between \\\\\\n                    {min_character_length}-{max_character_length} characters.\\\"\\n                raise ValueError(invalid_prompt_error)\\n\\n            if self.aspect_ratio and self.aspect_ratio not in [\\n                \\\"1:1\\\",\\n                \\\"16:9\\\",\\n                \\\"21:9\\\",\\n                \\\"3:2\\\",\\n                \\\"2:3\\\",\\n                \\\"4:5\\\",\\n                \\\"5:4\\\",\\n                \\\"3:4\\\",\\n                \\\"4:3\\\",\\n                \\\"9:16\\\",\\n                \\\"9:21\\\",\\n            ]:\\n                invalid_aspect_ratio_error = (\\n                    \\\"Aspect ratio must be one of the following: '1:1', '16:9', '21:9', '3:2', '2:3', \\\"\\n                    \\\"'4:5', '5:4', '3:4', '4:3', '9:16', '9:21'.\\\"\\n                )\\n                raise ValueError(invalid_aspect_ratio_error)\\n            if self.width and (self.width < min_width or self.width > max_width):\\n                invalid_width_error = f\\\"Width must be between {min_width}-{max_width} pixels.\\\"\\n                raise ValueError(invalid_width_error)\\n            if self.height and (self.height < min_height or self.height > max_height):\\n                invalid_height_error = f\\\"Height must be between {min_height}-{max_height} pixels.\\\"\\n                raise ValueError(invalid_height_error)\\n            if self.steps and (self.steps < min_steps or self.steps > max_steps):\\n                invalid_steps_error = f\\\"Steps must be between {min_steps}-{max_steps}.\\\"\\n                raise ValueError(invalid_steps_error)\\n\\n            params = {}\\n            if self.prompt:\\n                params[\\\"prompt\\\"] = self.prompt.strip()\\n            if self.aspect_ratio:\\n                params[\\\"aspect_ratio\\\"] = self.aspect_ratio.strip()\\n            if self.url:\\n                params[\\\"url\\\"] = self.url.strip()\\n            if self.file_store_key:\\n                params[\\\"file_store_key\\\"] = self.file_store_key.strip()\\n            if self.width:\\n                params[\\\"width\\\"] = self.width\\n            if self.height:\\n                params[\\\"height\\\"] = self.height\\n            params[\\\"return_type\\\"] = \\\"url\\\"\\n            if self.output_format:\\n                params[\\\"output_format\\\"] = self.output_format.strip()\\n            if self.steps:\\n                params[\\\"steps\\\"] = self.steps\\n\\n            # Initialize advance_config if any advanced parameters are provided\\n            if self.negative_prompt or self.seed or self.guidance:\\n                params[\\\"advance_config\\\"] = {}\\n            if self.negative_prompt:\\n                params[\\\"advance_config\\\"][\\\"negative_prompt\\\"] = self.negative_prompt\\n            if self.seed:\\n                params[\\\"advance_config\\\"][\\\"seed\\\"] = self.seed\\n            if self.guidance:\\n                params[\\\"advance_config\\\"][\\\"guidance\\\"] = self.guidance\\n\\n            # Call image generation\\n            response = client.image_generation(params)\\n\\n            if response.get(\\\"url\\\", None) is None or response.get(\\\"url\\\", None).strip() == \\\"\\\":\\n                failed_response_error = \\\"JigsawStack API returned unsuccessful response\\\"\\n                raise ValueError(failed_response_error)\\n\\n            return Data(data=response)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/nsfw.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"88b5eee389067ee2447186f7fe4e3d2e2f70a79863b6cc57e372277377d5f844\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackNSFWComponent(Component):\\n    display_name = \\\"NSFW Detection\\\"\\n    description = \\\"Detect if image/video contains NSFW content\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/nsfw\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackNSFW\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            info=\\\"URL of the image or video to analyze\\\",\\n            required=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"NSFW Analysis\\\", name=\\\"nsfw_result\\\", method=\\\"detect_nsfw\\\"),\\n    ]\\n\\n    def detect_nsfw(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            # Build request parameters\\n            params = {\\\"url\\\": self.url}\\n\\n            response = client.validate.nsfw(params)\\n\\n            api_error_msg = \\\"JigsawStack API returned unsuccessful response\\\"\\n            if not response.get(\\\"success\\\", False):\\n                raise ValueError(api_error_msg)\\n\\n            return Data(data=response)\\n\\n        except ValueError:\\n            raise\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/object_detection.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"fceaf0286f209c28ea5b8528d5510d62764a020518b7a4c5bf0367544a804e95\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import BoolInput, DropdownInput, MessageTextInput, Output, SecretStrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackObjectDetectionComponent(Component):\\n    display_name = \\\"Object Detection\\\"\\n    description = \\\"Perform object detection on images using JigsawStack's Object Detection Model, \\\\\\n        capable of image grounding, segmentation and computer use.\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/object-detection\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackObjectDetection\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"prompts\\\",\\n            display_name=\\\"Prompts\\\",\\n            info=\\\"The prompts to ground the object detection model. \\\\\\n                You can pass a list of comma-separated prompts to extract different information from the image.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            info=\\\"The image URL. Not required if file_store_key is specified.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"file_store_key\\\",\\n            display_name=\\\"File Store Key\\\",\\n            info=\\\"The key used to store the image on Jigsawstack File Storage. Not required if url is specified.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        BoolInput(\\n            name=\\\"annotated_image\\\",\\n            display_name=\\\"Return Annotated Image\\\",\\n            info=\\\"If true, will return an url for annotated image with detected objects.\\\",\\n            required=False,\\n            value=True,\\n        ),\\n        DropdownInput(\\n            name=\\\"features\\\",\\n            display_name=\\\"Features\\\",\\n            info=\\\"Select the features to enable for object detection\\\",\\n            required=False,\\n            options=[\\\"object_detection\\\", \\\"gui\\\"],\\n            value=[\\\"object_detection\\\", \\\"gui\\\"],\\n        ),\\n        DropdownInput(\\n            name=\\\"return_type\\\",\\n            display_name=\\\"Return Type\\\",\\n            info=\\\"Select the return type for the object detection results such as masks or annotations.\\\",\\n            required=False,\\n            options=[\\\"url\\\", \\\"base64\\\"],\\n            value=\\\"url\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Object Detection results\\\", name=\\\"object_detection_results\\\", method=\\\"detect_objects\\\"),\\n    ]\\n\\n    def detect_objects(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            # build request object\\n            params = {}\\n            if self.prompts:\\n                if isinstance(self.prompts, list):\\n                    params[\\\"prompt\\\"] = self.prompts\\n                elif isinstance(self.prompts, str):\\n                    if \\\",\\\" in self.prompts:\\n                        # Split by comma and strip whitespace\\n                        params[\\\"prompt\\\"] = [p.strip() for p in self.prompts.split(\\\",\\\")]\\n                    else:\\n                        params[\\\"prompt\\\"] = [self.prompts.strip()]\\n                else:\\n                    invalid_prompt_error = \\\"Prompt must be a list of strings or a single string\\\"\\n                    raise ValueError(invalid_prompt_error)\\n            if self.url:\\n                params[\\\"url\\\"] = self.url\\n            if self.file_store_key:\\n                params[\\\"file_store_key\\\"] = self.file_store_key\\n\\n            # if both url and file_store_key are not provided, raise an error\\n            if not self.url and not self.file_store_key:\\n                missing_url_error = \\\"Either URL or File Store Key must be provided to perform object detection\\\"\\n                raise ValueError(missing_url_error)\\n\\n            params[\\\"annotated_image\\\"] = self.annotated_image\\n            if self.features:\\n                params[\\\"features\\\"] = self.features\\n\\n            # Call web scraping\\n            response = client.vision.object_detection(params)\\n\\n            if not response.get(\\\"success\\\", False):\\n                failed_response_error = \\\"JigsawStack API returned unsuccessful response\\\"\\n                raise ValueError(failed_response_error)\\n\\n            return Data(data=response)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/sentiment.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"00d0377e5c2e5d80eab06814a6a9c8511eaacaef82aeea8870532385b1e77f99\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageTextInput, Output, SecretStrInput\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.message import Message\\n\\n\\nclass JigsawStackSentimentComponent(Component):\\n    display_name = \\\"Sentiment Analysis\\\"\\n    description = \\\"Analyze sentiment of text using JigsawStack AI\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/sentiment\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackSentiment\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"text\\\",\\n            display_name=\\\"Text\\\",\\n            info=\\\"Text to analyze for sentiment\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Sentiment Data\\\", name=\\\"sentiment_data\\\", method=\\\"analyze_sentiment\\\"),\\n        Output(display_name=\\\"Sentiment Text\\\", name=\\\"sentiment_text\\\", method=\\\"get_sentiment_text\\\"),\\n    ]\\n\\n    def analyze_sentiment(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n            response = client.sentiment({\\\"text\\\": self.text})\\n\\n            api_error_msg = \\\"JigsawStack API returned unsuccessful response\\\"\\n            if not response.get(\\\"success\\\", False):\\n                raise ValueError(api_error_msg)\\n\\n            sentiment_data = response.get(\\\"sentiment\\\", {})\\n\\n            result_data = {\\n                \\\"text_analyzed\\\": self.text,\\n                \\\"sentiment\\\": sentiment_data.get(\\\"sentiment\\\", \\\"Unknown\\\"),\\n                \\\"emotion\\\": sentiment_data.get(\\\"emotion\\\", \\\"Unknown\\\"),\\n                \\\"score\\\": sentiment_data.get(\\\"score\\\", 0.0),\\n                \\\"sentences\\\": response.get(\\\"sentences\\\", []),\\n                \\\"success\\\": True,\\n            }\\n\\n            self.status = (\\n                f\\\"Sentiment: {sentiment_data.get('sentiment', 'Unknown')} | \\\"\\n                f\\\"Emotion: {sentiment_data.get('emotion', 'Unknown')} | \\\"\\n                f\\\"Score: {sentiment_data.get('score', 0.0):.3f}\\\"\\n            )\\n\\n            return Data(data=result_data)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"text_analyzed\\\": self.text, \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\\n    def get_sentiment_text(self) -> Message:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError:\\n            return Message(text=\\\"Error: JigsawStack package not found. Please install it with: pip install jigsawstack\\\")\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n            response = client.sentiment({\\\"text\\\": self.text})\\n\\n            sentiment_data = response.get(\\\"sentiment\\\", {})\\n            sentences = response.get(\\\"sentences\\\", [])\\n\\n            # Format the output\\n            formatted_output = f\\\"\\\"\\\"Sentiment Analysis Results:\\n\\nText: {self.text}\\n\\nOverall Sentiment: {sentiment_data.get(\\\"sentiment\\\", \\\"Unknown\\\")}\\nEmotion: {sentiment_data.get(\\\"emotion\\\", \\\"Unknown\\\")}\\nScore: {sentiment_data.get(\\\"score\\\", 0.0):.3f}\\n\\nSentence-by-sentence Analysis:\\n\\\"\\\"\\\"\\n\\n            for i, sentence in enumerate(sentences, 1):\\n                formatted_output += (\\n                    f\\\"{i}. {sentence.get('text', '')}\\\\n\\\"\\n                    f\\\"   Sentiment: {sentence.get('sentiment', 'Unknown')} | \\\"\\n                    f\\\"Emotion: {sentence.get('emotion', 'Unknown')} | \\\"\\n                    f\\\"Score: {sentence.get('score', 0.0):.3f}\\\\n\\\"\\n                )\\n\\n            return Message(text=formatted_output)\\n\\n        except JigsawStackError as e:\\n            return Message(text=f\\\"Error analyzing sentiment: {e!s}\\\")\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/text_to_sql.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"30aa0cc15fb84230cb7c4b34a3f1f06432586e484663fd69a76e66cfe13e5393\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageTextInput, Output, QueryInput, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackTextToSQLComponent(Component):\\n    display_name = \\\"Text to SQL\\\"\\n    description = \\\"Convert natural language to SQL queries using JigsawStack AI\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/text-to-sql\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackTextToSQL\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        QueryInput(\\n            name=\\\"prompt\\\",\\n            display_name=\\\"Prompt\\\",\\n            info=\\\"Natural language description of the SQL query you want to generate\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"sql_schema\\\",\\n            display_name=\\\"SQL Schema\\\",\\n            info=(\\n                \\\"The database schema information. Can be a CREATE TABLE statement or schema description. \\\"\\n                \\\"Specifying this parameter improves SQL generation accuracy by applying \\\"\\n                \\\"database-specific syntax and optimizations.\\\"\\n            ),\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        StrInput(\\n            name=\\\"file_store_key\\\",\\n            display_name=\\\"File Store Key\\\",\\n            info=(\\n                \\\"The key used to store the database schema on Jigsawstack file Storage. \\\"\\n                \\\"Not required if sql_schema is specified.\\\"\\n            ),\\n            required=False,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"SQL Query\\\", name=\\\"sql_query\\\", method=\\\"generate_sql\\\"),\\n    ]\\n\\n    def generate_sql(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            schema_error = \\\"Either 'sql_schema' or 'file_store_key' must be provided\\\"\\n            if not self.sql_schema and not self.file_store_key:\\n                raise ValueError(schema_error)\\n\\n            # build request object\\n            params = {\\\"prompt\\\": self.prompt}\\n\\n            if self.sql_schema:\\n                params[\\\"sql_schema\\\"] = self.sql_schema\\n            if self.file_store_key:\\n                params[\\\"file_store_key\\\"] = self.file_store_key\\n\\n            client = JigsawStack(api_key=self.api_key)\\n            response = client.text_to_sql(params)\\n\\n            api_error_msg = \\\"JigsawStack API returned unsuccessful response\\\"\\n            if not response.get(\\\"success\\\", False):\\n                raise ValueError(api_error_msg)\\n\\n            return Data(data=response)\\n\\n        except ValueError:\\n            raise\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/text_translate.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"46233e19961fde844129aabb164cecb0bdac0d4f72ee37f742430390447e87c6\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import MessageTextInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackTextTranslateComponent(Component):\\n    display_name = \\\"Text Translate\\\"\\n    description = \\\"Translate text from one language to another with support for multiple text formats.\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/translate\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackTextTranslate\\\"\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        StrInput(\\n            name=\\\"target_language\\\",\\n            display_name=\\\"Target Language\\\",\\n            info=\\\"The language code of the target language to translate to. \\\\\\n                Language code is identified by a unique ISO 639-1 two-letter code\\\",\\n            required=True,\\n            tool_mode=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"text\\\",\\n            display_name=\\\"Text\\\",\\n            info=\\\"The text to translate. This can be a single string or a list of strings. \\\\\\n                If a list is provided, each string will be translated separately.\\\",\\n            required=True,\\n            is_list=True,\\n            tool_mode=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Translation Results\\\", name=\\\"translation_results\\\", method=\\\"translation\\\"),\\n    ]\\n\\n    def translation(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            # build request object\\n            params = {}\\n            if self.target_language:\\n                params[\\\"target_language\\\"] = self.target_language\\n\\n            if self.text:\\n                if isinstance(self.text, list):\\n                    params[\\\"text\\\"] = self.text\\n                else:\\n                    params[\\\"text\\\"] = [self.text]\\n\\n            # Call web scraping\\n            response = client.translate.text(params)\\n\\n            if not response.get(\\\"success\\\", False):\\n                failed_response_error = \\\"JigsawStack API returned unsuccessful response\\\"\\n                raise ValueError(failed_response_error)\\n\\n            return Data(data=response)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/jigsawstack/vocr.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"a44491947ba727cbb5425986dfaef666899fe807b2785d4d679bed983c74e804\",\"content\":\"from lfx.custom.custom_component.component import Component\\nfrom lfx.io import IntInput, MessageTextInput, Output, SecretStrInput, StrInput\\nfrom lfx.schema.data import Data\\n\\n\\nclass JigsawStackVOCRComponent(Component):\\n    display_name = \\\"VOCR\\\"\\n    description = \\\"Extract data from any document type in a consistent structure with fine-tuned \\\\\\n        vLLMs for the highest accuracy\\\"\\n    documentation = \\\"https://jigsawstack.com/docs/api-reference/ai/vocr\\\"\\n    icon = \\\"JigsawStack\\\"\\n    name = \\\"JigsawStackVOCR\\\"\\n\\n    inputs = [\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"JigsawStack API Key\\\",\\n            info=\\\"Your JigsawStack API key for authentication\\\",\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"prompts\\\",\\n            display_name=\\\"Prompts\\\",\\n            info=\\\"The prompts used to describe the image. Default prompt is Describe the image in detail. \\\\\\n                You can pass a list of comma-separated prompts to extract different information from the image.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        StrInput(\\n            name=\\\"url\\\",\\n            display_name=\\\"URL\\\",\\n            info=\\\"The image or document url. Not required if file_store_key is specified.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        StrInput(\\n            name=\\\"file_store_key\\\",\\n            display_name=\\\"File Store Key\\\",\\n            info=\\\"The key used to store the image on Jigsawstack File Storage. Not required if url is specified.\\\",\\n            required=False,\\n            tool_mode=True,\\n        ),\\n        IntInput(\\n            name=\\\"page_range_start\\\",\\n            display_name=\\\"Page Range\\\",\\n            info=\\\"Page range start limit for the document. If not specified, all pages will be processed.\\\",\\n            required=False,\\n        ),\\n        IntInput(\\n            name=\\\"page_range_end\\\",\\n            display_name=\\\"Page Range End\\\",\\n            info=\\\"Page range end limit for the document. If not specified, all pages will be processed.\\\",\\n            required=False,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"VOCR results\\\", name=\\\"vocr_results\\\", method=\\\"vocr\\\"),\\n    ]\\n\\n    def vocr(self) -> Data:\\n        try:\\n            from jigsawstack import JigsawStack, JigsawStackError\\n        except ImportError as e:\\n            jigsawstack_import_error = (\\n                \\\"JigsawStack package not found. Please install it using: pip install jigsawstack>=0.2.7\\\"\\n            )\\n            raise ImportError(jigsawstack_import_error) from e\\n\\n        try:\\n            client = JigsawStack(api_key=self.api_key)\\n\\n            # build request object\\n            params = {}\\n            if self.prompts:\\n                if isinstance(self.prompts, list):\\n                    params[\\\"prompt\\\"] = self.prompts\\n                elif isinstance(self.prompts, str):\\n                    if \\\",\\\" in self.prompts:\\n                        # Split by comma and strip whitespace\\n                        params[\\\"prompt\\\"] = [p.strip() for p in self.prompts.split(\\\",\\\")]\\n                    else:\\n                        params[\\\"prompt\\\"] = [self.prompts.strip()]\\n                else:\\n                    invalid_prompt_error = \\\"Prompt must be a list of strings or a single string\\\"\\n                    raise ValueError(invalid_prompt_error)\\n            if self.url:\\n                params[\\\"url\\\"] = self.url\\n            if self.file_store_key:\\n                params[\\\"file_store_key\\\"] = self.file_store_key\\n\\n            if self.page_range_start and self.page_range_end:\\n                params[\\\"page_range\\\"] = [self.page_range_start, self.page_range_end]\\n\\n            # Call VOCR\\n            response = client.vision.vocr(params)\\n\\n            if not response.get(\\\"success\\\", False):\\n                failed_response_error = \\\"JigsawStack API returned unsuccessful response\\\"\\n                raise ValueError(failed_response_error)\\n\\n            return Data(data=response)\\n\\n        except JigsawStackError as e:\\n            error_data = {\\\"error\\\": str(e), \\\"success\\\": False}\\n            self.status = f\\\"Error: {e!s}\\\"\\n            return Data(data=error_data)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/langwatch/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"64e55401b311b86916eaef2772a29946cd084a53eb011f1f0f7a994d573b6f3b\",\"content\":\"from .langwatch import LangWatchComponent\\n\\n__all__ = [\\\"LangWatchComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/langwatch/langwatch.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"418a94b314f31b5ff035f66e4cbce318d75ab4793d9d44de51e81bd89c114d90\",\"content\":\"import json\\nimport os\\nfrom typing import Any\\n\\nimport httpx\\nfrom lfx.base.langwatch.utils import get_cached_evaluators\\nfrom lfx.custom.custom_component.component import Component\\nfrom lfx.inputs.inputs import MultilineInput\\nfrom lfx.io import (\\n    BoolInput,\\n    DropdownInput,\\n    FloatInput,\\n    IntInput,\\n    MessageTextInput,\\n    NestedDictInput,\\n    Output,\\n    SecretStrInput,\\n)\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.schema.dotdict import dotdict\\n\\n\\nclass LangWatchComponent(Component):\\n    display_name: str = \\\"LangWatch Evaluator\\\"\\n    description: str = \\\"Evaluates various aspects of language models using LangWatch's evaluation endpoints.\\\"\\n    documentation: str = \\\"https://docs.langwatch.ai/langevals/documentation/introduction\\\"\\n    icon: str = \\\"Langwatch\\\"\\n    name: str = \\\"LangWatchEvaluator\\\"\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"evaluator_name\\\",\\n            display_name=\\\"Evaluator Name\\\",\\n            options=[],\\n            required=True,\\n            info=\\\"Select an evaluator.\\\",\\n            refresh_button=True,\\n            real_time_refresh=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"LangWatch API Key\\\",\\n            required=True,\\n            info=\\\"Enter your LangWatch API key.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"input\\\",\\n            display_name=\\\"Input\\\",\\n            required=False,\\n            info=\\\"The input text for evaluation.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"output\\\",\\n            display_name=\\\"Output\\\",\\n            required=False,\\n            info=\\\"The output text for evaluation.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"expected_output\\\",\\n            display_name=\\\"Expected Output\\\",\\n            required=False,\\n            info=\\\"The expected output for evaluation.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"contexts\\\",\\n            display_name=\\\"Contexts\\\",\\n            required=False,\\n            info=\\\"The contexts for evaluation (comma-separated).\\\",\\n        ),\\n        IntInput(\\n            name=\\\"timeout\\\",\\n            display_name=\\\"Timeout\\\",\\n            info=\\\"The maximum time (in seconds) allowed for the server to respond before timing out.\\\",\\n            value=30,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"evaluation_result\\\", display_name=\\\"Evaluation Result\\\", method=\\\"evaluate\\\"),\\n    ]\\n\\n    def set_evaluators(self, endpoint: str):\\n        url = f\\\"{endpoint}/api/evaluations/list\\\"\\n        self.evaluators = get_cached_evaluators(url)\\n        if not self.evaluators or len(self.evaluators) == 0:\\n            self.status = f\\\"No evaluators found from {endpoint}\\\"\\n            msg = f\\\"No evaluators found from {endpoint}\\\"\\n            raise ValueError(msg)\\n\\n    def update_build_config(self, build_config: dotdict, field_value: Any, field_name: str | None = None) -> dotdict:\\n        try:\\n            logger.info(f\\\"Updating build config. Field name: {field_name}, Field value: {field_value}\\\")\\n\\n            if field_name is None or field_name == \\\"evaluator_name\\\":\\n                self.evaluators = self.get_evaluators(os.getenv(\\\"LANGWATCH_ENDPOINT\\\", \\\"https://app.langwatch.ai\\\"))\\n                build_config[\\\"evaluator_name\\\"][\\\"options\\\"] = list(self.evaluators.keys())\\n\\n                # Set a default evaluator if none is selected\\n                if not getattr(self, \\\"current_evaluator\\\", None) and self.evaluators:\\n                    self.current_evaluator = next(iter(self.evaluators))\\n                    build_config[\\\"evaluator_name\\\"][\\\"value\\\"] = self.current_evaluator\\n\\n                # Define default keys that should always be present\\n                default_keys = [\\\"code\\\", \\\"_type\\\", \\\"evaluator_name\\\", \\\"api_key\\\", \\\"input\\\", \\\"output\\\", \\\"timeout\\\"]\\n\\n                if field_value and field_value in self.evaluators and self.current_evaluator != field_value:\\n                    self.current_evaluator = field_value\\n                    evaluator = self.evaluators[field_value]\\n\\n                    # Clear previous dynamic inputs\\n                    keys_to_remove = [key for key in build_config if key not in default_keys]\\n                    for key in keys_to_remove:\\n                        del build_config[key]\\n\\n                    # Clear component's dynamic attributes\\n                    for attr in list(self.__dict__.keys()):\\n                        if attr not in default_keys and attr not in {\\n                            \\\"evaluators\\\",\\n                            \\\"dynamic_inputs\\\",\\n                            \\\"_code\\\",\\n                            \\\"current_evaluator\\\",\\n                        }:\\n                            delattr(self, attr)\\n\\n                    # Add new dynamic inputs\\n                    self.dynamic_inputs = self.get_dynamic_inputs(evaluator)\\n                    for name, input_config in self.dynamic_inputs.items():\\n                        build_config[name] = input_config.to_dict()\\n\\n                    # Update required fields\\n                    required_fields = {\\\"api_key\\\", \\\"evaluator_name\\\"}.union(evaluator.get(\\\"requiredFields\\\", []))\\n                    for key in build_config:\\n                        if isinstance(build_config[key], dict):\\n                            build_config[key][\\\"required\\\"] = key in required_fields\\n\\n                # Validate presence of default keys\\n                missing_keys = [key for key in default_keys if key not in build_config]\\n                if missing_keys:\\n                    logger.warning(f\\\"Missing required keys in build_config: {missing_keys}\\\")\\n                    # Add missing keys with default values\\n                    for key in missing_keys:\\n                        build_config[key] = {\\\"value\\\": None, \\\"type\\\": \\\"str\\\"}\\n\\n            # Ensure the current_evaluator is always set in the build_config\\n            build_config[\\\"evaluator_name\\\"][\\\"value\\\"] = self.current_evaluator\\n\\n            logger.info(f\\\"Current evaluator set to: {self.current_evaluator}\\\")\\n\\n        except (KeyError, AttributeError, ValueError) as e:\\n            self.status = f\\\"Error updating component: {e!s}\\\"\\n        return build_config\\n\\n    def get_dynamic_inputs(self, evaluator: dict[str, Any]):\\n        try:\\n            dynamic_inputs = {}\\n\\n            input_fields = [\\n                field\\n                for field in evaluator.get(\\\"requiredFields\\\", []) + evaluator.get(\\\"optionalFields\\\", [])\\n                if field not in {\\\"input\\\", \\\"output\\\"}\\n            ]\\n\\n            for field in input_fields:\\n                input_params = {\\n                    \\\"name\\\": field,\\n                    \\\"display_name\\\": field.replace(\\\"_\\\", \\\" \\\").title(),\\n                    \\\"required\\\": field in evaluator.get(\\\"requiredFields\\\", []),\\n                }\\n                if field == \\\"contexts\\\":\\n                    dynamic_inputs[field] = MultilineInput(**input_params, multiline=True)\\n                else:\\n                    dynamic_inputs[field] = MessageTextInput(**input_params)\\n\\n            settings = evaluator.get(\\\"settings\\\", {})\\n            for setting_name, setting_config in settings.items():\\n                schema = evaluator.get(\\\"settings_json_schema\\\", {}).get(\\\"properties\\\", {}).get(setting_name, {})\\n\\n                input_params = {\\n                    \\\"name\\\": setting_name,\\n                    \\\"display_name\\\": setting_name.replace(\\\"_\\\", \\\" \\\").title(),\\n                    \\\"info\\\": setting_config.get(\\\"description\\\", \\\"\\\"),\\n                    \\\"required\\\": False,\\n                }\\n\\n                if schema.get(\\\"type\\\") == \\\"object\\\":\\n                    input_type = NestedDictInput\\n                    input_params[\\\"value\\\"] = schema.get(\\\"default\\\", setting_config.get(\\\"default\\\", {}))\\n                elif schema.get(\\\"type\\\") == \\\"boolean\\\":\\n                    input_type = BoolInput\\n                    input_params[\\\"value\\\"] = schema.get(\\\"default\\\", setting_config.get(\\\"default\\\", False))\\n                elif schema.get(\\\"type\\\") == \\\"number\\\":\\n                    is_float = isinstance(schema.get(\\\"default\\\", setting_config.get(\\\"default\\\")), float)\\n                    input_type = FloatInput if is_float else IntInput\\n                    input_params[\\\"value\\\"] = schema.get(\\\"default\\\", setting_config.get(\\\"default\\\", 0))\\n                elif \\\"enum\\\" in schema:\\n                    input_type = DropdownInput\\n                    input_params[\\\"options\\\"] = schema[\\\"enum\\\"]\\n                    input_params[\\\"value\\\"] = schema.get(\\\"default\\\", setting_config.get(\\\"default\\\"))\\n                else:\\n                    input_type = MessageTextInput\\n                    default_value = schema.get(\\\"default\\\", setting_config.get(\\\"default\\\"))\\n                    input_params[\\\"value\\\"] = str(default_value) if default_value is not None else \\\"\\\"\\n\\n                dynamic_inputs[setting_name] = input_type(**input_params)\\n\\n        except (KeyError, AttributeError, ValueError, TypeError) as e:\\n            self.status = f\\\"Error creating dynamic inputs: {e!s}\\\"\\n            return {}\\n        return dynamic_inputs\\n\\n    async def evaluate(self) -> Data:\\n        if not self.api_key:\\n            return Data(data={\\\"error\\\": \\\"API key is required\\\"})\\n\\n        self.set_evaluators(os.getenv(\\\"LANGWATCH_ENDPOINT\\\", \\\"https://app.langwatch.ai\\\"))\\n        self.dynamic_inputs = {}\\n        if getattr(self, \\\"current_evaluator\\\", None) is None and self.evaluators:\\n            self.current_evaluator = next(iter(self.evaluators))\\n\\n        # Prioritize evaluator_name if it exists\\n        evaluator_name = getattr(self, \\\"evaluator_name\\\", None) or self.current_evaluator\\n\\n        if not evaluator_name:\\n            if self.evaluators:\\n                evaluator_name = next(iter(self.evaluators))\\n                await logger.ainfo(f\\\"No evaluator was selected. Using default: {evaluator_name}\\\")\\n            else:\\n                return Data(\\n                    data={\\\"error\\\": \\\"No evaluator selected and no evaluators available. Please choose an evaluator.\\\"}\\n                )\\n\\n        try:\\n            evaluator = self.evaluators.get(evaluator_name)\\n            if not evaluator:\\n                return Data(data={\\\"error\\\": f\\\"Selected evaluator '{evaluator_name}' not found.\\\"})\\n\\n            await logger.ainfo(f\\\"Evaluating with evaluator: {evaluator_name}\\\")\\n\\n            endpoint = f\\\"/api/evaluations/{evaluator_name}/evaluate\\\"\\n            url = f\\\"{os.getenv('LANGWATCH_ENDPOINT', 'https://app.langwatch.ai')}{endpoint}\\\"\\n\\n            headers = {\\\"Content-Type\\\": \\\"application/json\\\", \\\"X-Auth-Token\\\": self.api_key}\\n\\n            payload = {\\n                \\\"data\\\": {\\n                    \\\"input\\\": self.input,\\n                    \\\"output\\\": self.output,\\n                    \\\"expected_output\\\": self.expected_output,\\n                    \\\"contexts\\\": self.contexts.split(\\\",\\\") if self.contexts else [],\\n                },\\n                \\\"settings\\\": {},\\n            }\\n\\n            if self._tracing_service:\\n                tracer = self._tracing_service.get_tracer(\\\"langwatch\\\")\\n                if tracer is not None and hasattr(tracer, \\\"trace_id\\\"):\\n                    payload[\\\"settings\\\"][\\\"trace_id\\\"] = str(tracer.trace_id)\\n\\n            for setting_name in self.dynamic_inputs:\\n                payload[\\\"settings\\\"][setting_name] = getattr(self, setting_name, None)\\n\\n            async with httpx.AsyncClient(timeout=self.timeout) as client:\\n                response = await client.post(url, json=payload, headers=headers)\\n\\n            response.raise_for_status()\\n            result = response.json()\\n\\n            formatted_result = json.dumps(result, indent=2)\\n            self.status = f\\\"Evaluation completed successfully. Result:\\\\n{formatted_result}\\\"\\n            return Data(data=result)\\n\\n        except (httpx.RequestError, KeyError, AttributeError, ValueError) as e:\\n            error_message = f\\\"Evaluation error: {e!s}\\\"\\n            self.status = error_message\\n            return Data(data={\\\"error\\\": error_message})\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/litellm/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"cfb27050ff7c3f5af51e1774f42c5783980b252c450eada056ac48df80bd30fe\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from lfx_bundles.litellm.litellm_proxy import LiteLLMProxyComponent\\n\\n_dynamic_imports = {\\n    \\\"LiteLLMProxyComponent\\\": \\\"litellm_proxy\\\",\\n}\\n\\n__all__ = [\\\"LiteLLMProxyComponent\\\"]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import litellm components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/litellm/litellm_proxy.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"53e67dc8cb3e583a5b47d5d65e56ab8fe7e5df1fa58012cb4e4d24f7e90b8701\",\"content\":\"import httpx\\nfrom langchain_openai import ChatOpenAI\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.inputs import IntInput, SecretStrInput, SliderInput, StrInput\\nfrom lfx.utils.secrets import secret_value_to_str\\nfrom lfx.utils.ssrf_httpx import ssrf_protected_openai_clients_for_url, ssrf_safe_httpx_get\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n\\nclass LiteLLMProxyComponent(LCModelComponent):\\n    \\\"\\\"\\\"LiteLLM Proxy component for routing to multiple LLM providers.\\\"\\\"\\\"\\n\\n    display_name = \\\"LiteLLM Proxy\\\"\\n    description = \\\"Generate text using any LLM provider via a LiteLLM proxy with virtual key authentication.\\\"\\n    icon = \\\"LiteLLM\\\"\\n    name = \\\"LiteLLMProxyModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        StrInput(\\n            name=\\\"api_base\\\",\\n            display_name=\\\"LiteLLM Proxy URL\\\",\\n            value=\\\"http://localhost:4000/v1\\\",\\n            required=True,\\n            info=\\\"Base URL of the LiteLLM proxy.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Virtual Key\\\",\\n            value=\\\"LITELLM_API_KEY\\\",\\n            required=True,\\n            info=\\\"Virtual key for authentication.\\\",\\n        ),\\n        StrInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            required=True,\\n            info=\\\"Model name to use (e.g. gpt-4o, claude-3-opus).\\\",\\n        ),\\n        SliderInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.7,\\n            range_spec=RangeSpec(min=0, max=1, step=0.01),\\n            advanced=True,\\n            info=\\\"Controls randomness. Lower values are more deterministic.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            info=\\\"Maximum number of tokens to generate. Set to 0 for no limit.\\\",\\n            range_spec=RangeSpec(min=0, max=128000),\\n        ),\\n        IntInput(\\n            name=\\\"timeout\\\",\\n            display_name=\\\"Timeout (seconds)\\\",\\n            value=60,\\n            advanced=True,\\n            info=\\\"Request timeout in seconds.\\\",\\n        ),\\n        IntInput(\\n            name=\\\"max_retries\\\",\\n            display_name=\\\"Max Retries\\\",\\n            value=2,\\n            advanced=True,\\n            info=\\\"Maximum number of retries on failure.\\\",\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:\\n        \\\"\\\"\\\"Build the LiteLLM proxy model.\\\"\\\"\\\"\\n        api_key = secret_value_to_str(self.api_key) or \\\"\\\"\\n        ssrf_client_kwargs = ssrf_protected_openai_clients_for_url(self.api_base)\\n\\n        self._validate_proxy_connection(api_key)\\n\\n        return ChatOpenAI(\\n            base_url=self.api_base,\\n            api_key=api_key,\\n            model=self.model_name,\\n            temperature=self.temperature,\\n            max_tokens=self.max_tokens if self.max_tokens != 0 else None,\\n            timeout=self.timeout,\\n            max_retries=self.max_retries,\\n            streaming=self.stream,\\n            **ssrf_client_kwargs,\\n        )\\n\\n    def _validate_proxy_connection(self, api_key: str) -> None:\\n        \\\"\\\"\\\"Validate the proxy connection, API key, and model availability.\\\"\\\"\\\"\\n        base_url = self.api_base.rstrip(\\\"/\\\")\\n        models_url = f\\\"{base_url}/models\\\"\\n\\n        try:\\n            response = ssrf_safe_httpx_get(\\n                models_url,\\n                headers={\\\"Authorization\\\": f\\\"Bearer {api_key}\\\"},\\n                timeout=10,\\n            )\\n        except SSRFProtectionError as e:\\n            msg = f\\\"SSRF Protection: {e}\\\"\\n            raise ValueError(msg) from e\\n        except httpx.ConnectError as e:\\n            msg = (\\n                f\\\"Could not connect to LiteLLM Proxy at {base_url}. Verify the URL is correct and the proxy is running.\\\"\\n            )\\n            raise ValueError(msg) from e\\n        except httpx.TimeoutException as e:\\n            msg = f\\\"Connection to LiteLLM Proxy at {base_url} timed out.\\\"\\n            raise ValueError(msg) from e\\n\\n        http_unauthorized = 401\\n        if response.status_code == http_unauthorized:\\n            msg = \\\"Authentication failed. Check that your Virtual Key is valid and not expired.\\\"\\n            raise ValueError(msg)\\n\\n        response.raise_for_status()\\n\\n        data = response.json()\\n        available_models = [m.get(\\\"id\\\", \\\"\\\") for m in data.get(\\\"data\\\", [])]\\n        if available_models and self.model_name not in available_models:\\n            msg = (\\n                f\\\"Model '{self.model_name}' not found on the LiteLLM Proxy. \\\"\\n                f\\\"Available models: {', '.join(available_models)}\\\"\\n            )\\n            raise ValueError(msg)\\n\\n    def _get_exception_message(self, e: Exception) -> str | None:\\n        \\\"\\\"\\\"Extract meaningful error messages from OpenAI client exceptions.\\\"\\\"\\\"\\n        try:\\n            from openai import AuthenticationError, BadRequestError, NotFoundError\\n        except ImportError:\\n            return None\\n\\n        if isinstance(e, AuthenticationError):\\n            return \\\"Authentication failed. Check that your Virtual Key is valid and not expired.\\\"\\n        if isinstance(e, NotFoundError):\\n            return f\\\"Model '{self.model_name}' not found. Verify the model name.\\\"\\n        if isinstance(e, BadRequestError):\\n            message = e.body.get(\\\"message\\\") if isinstance(e.body, dict) else None\\n            if message:\\n                return message\\n        return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/lmstudio/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"06633c627bfc608092f5ea2a6acef26f25e91888b59caa55139b91e36f803f40\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from lfx_bundles.lmstudio.lmstudioembeddings import LMStudioEmbeddingsComponent\\n    from lfx_bundles.lmstudio.lmstudiomodel import LMStudioModelComponent\\n\\n_dynamic_imports = {\\n    \\\"LMStudioEmbeddingsComponent\\\": \\\"lmstudioembeddings\\\",\\n    \\\"LMStudioModelComponent\\\": \\\"lmstudiomodel\\\",\\n}\\n\\n__all__ = [\\\"LMStudioEmbeddingsComponent\\\", \\\"LMStudioModelComponent\\\"]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import lmstudio components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/lmstudio/lmstudioembeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"79e48a04731bd74491cfb809cde3cb5d4858e361b05d3153ac943832718b0b88\",\"content\":\"from typing import Any\\nfrom urllib.parse import urljoin\\n\\nfrom lfx.base.embeddings.model import LCEmbeddingsModel\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.inputs.inputs import DropdownInput, SecretStrInput\\nfrom lfx.io import FloatInput, MessageTextInput\\nfrom lfx.utils.ssrf_httpx import ssrf_safe_async_get, validate_url_for_ssrf_or_raise\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n\\nclass LMStudioEmbeddingsComponent(LCEmbeddingsModel):\\n    display_name: str = \\\"LM Studio Embeddings\\\"\\n    description: str = \\\"Generate embeddings using LM Studio.\\\"\\n    icon = \\\"LMStudio\\\"\\n\\n    async def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None):  # noqa: ARG002\\n        if field_name == \\\"model\\\":\\n            base_url_dict = build_config.get(\\\"base_url\\\", {})\\n            base_url_load_from_db = base_url_dict.get(\\\"load_from_db\\\", False)\\n            base_url_value = base_url_dict.get(\\\"value\\\")\\n            if base_url_load_from_db:\\n                base_url_value = await self.get_variables(base_url_value, field_name)\\n            elif not base_url_value:\\n                base_url_value = \\\"http://localhost:1234/v1\\\"\\n            build_config[\\\"model\\\"][\\\"options\\\"] = await self.get_model(base_url_value)\\n\\n        return build_config\\n\\n    @staticmethod\\n    async def get_model(base_url_value: str) -> list[str]:\\n        try:\\n            url = urljoin(base_url_value, \\\"/v1/models\\\")\\n            response = await ssrf_safe_async_get(url)\\n            response.raise_for_status()\\n            data = response.json()\\n\\n            return [model[\\\"id\\\"] for model in data.get(\\\"data\\\", [])]\\n        except SSRFProtectionError as e:\\n            msg = f\\\"SSRF Protection: {e}\\\"\\n            raise ValueError(msg) from e\\n        except Exception as e:\\n            msg = \\\"Could not retrieve models. Please, make sure the LM Studio server is running.\\\"\\n            raise ValueError(msg) from e\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"model\\\",\\n            display_name=\\\"Model\\\",\\n            advanced=False,\\n            refresh_button=True,\\n            required=True,\\n        ),\\n        MessageTextInput(\\n            name=\\\"base_url\\\",\\n            display_name=\\\"LM Studio Base URL\\\",\\n            refresh_button=True,\\n            value=\\\"http://localhost:1234/v1\\\",\\n            required=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"LM Studio API Key\\\",\\n            advanced=True,\\n            value=\\\"LMSTUDIO_API_KEY\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Model Temperature\\\",\\n            value=0.1,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        validate_url_for_ssrf_or_raise(self.base_url)\\n\\n        try:\\n            from langchain_nvidia_ai_endpoints import NVIDIAEmbeddings\\n        except ImportError as e:\\n            msg = \\\"Please install langchain-nvidia-ai-endpoints to use LM Studio Embeddings.\\\"\\n            raise ImportError(msg) from e\\n        try:\\n            output = NVIDIAEmbeddings(\\n                model=self.model,\\n                base_url=self.base_url,\\n                temperature=self.temperature,\\n                nvidia_api_key=self.api_key,\\n            )\\n        except Exception as e:\\n            msg = f\\\"Could not connect to LM Studio API. Error: {e}\\\"\\n            raise ValueError(msg) from e\\n        return output\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/lmstudio/lmstudiomodel.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"f27f7f4f9695d41a9e288a6ca91921ed7ecb68353fb1685eb78cb8913db0fc9c\",\"content\":\"from typing import Any\\nfrom urllib.parse import urljoin\\n\\nimport httpx\\nfrom langchain_openai import ChatOpenAI\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.inputs import DictInput, DropdownInput, FloatInput, IntInput, SecretStrInput, StrInput\\nfrom lfx.utils.ssrf_httpx import ssrf_protected_openai_clients_for_url, ssrf_safe_async_get\\nfrom lfx.utils.ssrf_protection import SSRFProtectionError\\n\\n\\nclass LMStudioModelComponent(LCModelComponent):\\n    display_name = \\\"LM Studio\\\"\\n    description = \\\"Generate text using LM Studio Local LLMs.\\\"\\n    icon = \\\"LMStudio\\\"\\n    name = \\\"LMStudioModel\\\"\\n\\n    async def update_build_config(self, build_config: dict, field_value: Any, field_name: str | None = None):  # noqa: ARG002\\n        if field_name == \\\"model_name\\\":\\n            base_url_dict = build_config.get(\\\"base_url\\\", {})\\n            base_url_load_from_db = base_url_dict.get(\\\"load_from_db\\\", False)\\n            base_url_value = base_url_dict.get(\\\"value\\\")\\n            if base_url_load_from_db:\\n                base_url_value = await self.get_variables(base_url_value, field_name)\\n            try:\\n                response = await ssrf_safe_async_get(urljoin(base_url_value, \\\"/v1/models\\\"), timeout=2.0)\\n                response.raise_for_status()\\n            except SSRFProtectionError as e:\\n                msg = f\\\"SSRF Protection: {e}\\\"\\n                raise ValueError(msg) from e\\n            except httpx.HTTPError:\\n                msg = \\\"Could not access the default LM Studio URL. Please, specify the 'Base URL' field.\\\"\\n                self.log(msg)\\n                return build_config\\n            build_config[\\\"model_name\\\"][\\\"options\\\"] = await self.get_model(base_url_value)\\n\\n        return build_config\\n\\n    @staticmethod\\n    async def get_model(base_url_value: str) -> list[str]:\\n        try:\\n            url = urljoin(base_url_value, \\\"/v1/models\\\")\\n            response = await ssrf_safe_async_get(url)\\n            response.raise_for_status()\\n            data = response.json()\\n\\n            return [model[\\\"id\\\"] for model in data.get(\\\"data\\\", [])]\\n        except SSRFProtectionError as e:\\n            msg = f\\\"SSRF Protection: {e}\\\"\\n            raise ValueError(msg) from e\\n        except Exception as e:\\n            msg = \\\"Could not retrieve models. Please, make sure the LM Studio server is running.\\\"\\n            raise ValueError(msg) from e\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            info=\\\"The maximum number of tokens to generate. Set to 0 for unlimited tokens.\\\",\\n            range_spec=RangeSpec(min=0, max=128000),\\n        ),\\n        DictInput(name=\\\"model_kwargs\\\", display_name=\\\"Model Kwargs\\\", advanced=True),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            advanced=False,\\n            refresh_button=True,\\n        ),\\n        StrInput(\\n            name=\\\"base_url\\\",\\n            display_name=\\\"Base URL\\\",\\n            advanced=False,\\n            info=\\\"Endpoint of the LM Studio API. Defaults to 'http://localhost:1234/v1' if not specified.\\\",\\n            value=\\\"http://localhost:1234/v1\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"LM Studio API Key\\\",\\n            info=\\\"The LM Studio API Key to use for LM Studio.\\\",\\n            advanced=True,\\n            value=\\\"LMSTUDIO_API_KEY\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.1,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"seed\\\",\\n            display_name=\\\"Seed\\\",\\n            info=\\\"The seed controls the reproducibility of the job.\\\",\\n            advanced=True,\\n            value=1,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        lmstudio_api_key = self.api_key\\n        temperature = self.temperature\\n        model_name: str = self.model_name\\n        max_tokens = self.max_tokens\\n        model_kwargs = self.model_kwargs or {}\\n        base_url = self.base_url or \\\"http://localhost:1234/v1\\\"\\n        seed = self.seed\\n\\n        ssrf_client_kwargs = ssrf_protected_openai_clients_for_url(base_url)\\n\\n        return ChatOpenAI(\\n            max_tokens=max_tokens or None,\\n            model_kwargs=model_kwargs,\\n            model=model_name,\\n            base_url=base_url,\\n            api_key=lmstudio_api_key,\\n            temperature=temperature if temperature is not None else 0.1,\\n            seed=seed,\\n            **ssrf_client_kwargs,\\n        )\\n\\n    def _get_exception_message(self, e: Exception):\\n        \\\"\\\"\\\"Get a message from an LM Studio exception.\\n\\n        Args:\\n            e (Exception): The exception to get the message from.\\n\\n        Returns:\\n            str: The message from the exception.\\n        \\\"\\\"\\\"\\n        try:\\n            from openai import BadRequestError\\n        except ImportError:\\n            return None\\n        if isinstance(e, BadRequestError):\\n            message = e.body.get(\\\"message\\\")\\n            if message:\\n                return message\\n        return None\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/maritalk/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"863ad0a14d294b5303b4fbe2730bb3635302d578f505f104c295c2266f8f3f29\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.components._importing import import_mod\\n\\nif TYPE_CHECKING:\\n    from lfx_bundles.maritalk.maritalk import MaritalkModelComponent\\n\\n_dynamic_imports = {\\n    \\\"MaritalkModelComponent\\\": \\\"maritalk\\\",\\n}\\n\\n__all__ = [\\\"MaritalkModelComponent\\\"]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import maritalk components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/maritalk/maritalk.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"0bf1e4019491fa68faf64b1a37b79fc751ac6acbb6ccb9c26e15a193423af5c2\",\"content\":\"from langchain_community.chat_models import ChatMaritalk\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.field_typing.range_spec import RangeSpec\\nfrom lfx.inputs.inputs import DropdownInput, FloatInput, IntInput, SecretStrInput\\n\\n\\nclass MaritalkModelComponent(LCModelComponent):\\n    display_name = \\\"MariTalk\\\"\\n    description = \\\"Generates text using MariTalk LLMs.\\\"\\n    icon = \\\"Maritalk\\\"\\n    name = \\\"Maritalk\\\"\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            value=512,\\n            info=\\\"The maximum number of tokens to generate. Set to 0 for unlimited tokens.\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            advanced=False,\\n            options=[\\\"sabia-2-small\\\", \\\"sabia-2-medium\\\"],\\n            value=[\\\"sabia-2-small\\\"],\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"MariTalk API Key\\\",\\n            info=\\\"The MariTalk API Key to use for authentication.\\\",\\n            advanced=False,\\n        ),\\n        FloatInput(name=\\\"temperature\\\", display_name=\\\"Temperature\\\", value=0.1, range_spec=RangeSpec(min=0, max=1)),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        # self.output_schea is a list of dictionarie s\\n        # let's convert it to a dictionary\\n        api_key = self.api_key\\n        temperature = self.temperature\\n        model_name: str = self.model_name\\n        max_tokens = self.max_tokens\\n\\n        return ChatMaritalk(\\n            max_tokens=max_tokens,\\n            model=model_name,\\n            api_key=api_key,\\n            temperature=temperature or 0.1,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/mem0/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"3702f918df987513d7654e58e7377d8694db071e9c3e354a1bff30c0819488db\",\"content\":\"from .mem0_chat_memory import Mem0MemoryComponent\\n\\n__all__ = [\\\"Mem0MemoryComponent\\\"]\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/mem0/mem0_chat_memory.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"e96892a9cf2ae0ffc7241e39b32077d6c3afbc4c391819771b88d2321214fbbf\",\"content\":\"import importlib\\nimport os\\nfrom typing import Any, Protocol\\n\\nfrom lfx.base.memory.model import LCChatMemoryComponent\\nfrom lfx.inputs.inputs import DictInput, HandleInput, MessageTextInput, NestedDictInput, SecretStrInput\\nfrom lfx.io import Output\\nfrom lfx.log.logger import logger\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.validate_cloud import raise_error_if_astra_cloud_disable_component\\n\\n# mem0 creates PostHog clients at import time. Keep that third-party telemetry\\n# disabled by default unless the deployer explicitly opts in.\\nos.environ.setdefault(\\\"MEM0_TELEMETRY\\\", \\\"False\\\")\\n\\n\\nclass Memory(Protocol):\\n    def add(self, message: str, *, user_id: str, metadata: dict[str, Any]) -> Any: ...\\n\\n    def search(self, *, query: str, filters: dict[str, str]) -> Any: ...\\n\\n    def get_all(self, *, filters: dict[str, str]) -> Any: ...\\n\\n\\ndisable_component_in_astra_cloud_msg = (\\n    \\\"Mem0 chat memory is not supported in Astra cloud environment. Please use local storage mode or mem0 cloud.\\\"\\n)\\n\\n\\nclass Mem0MemoryComponent(LCChatMemoryComponent):\\n    display_name = \\\"Mem0 Chat Memory\\\"\\n    description = \\\"Retrieves and stores chat messages using Mem0 memory storage.\\\"\\n    name = \\\"mem0_chat_memory\\\"\\n    icon: str = \\\"Mem0\\\"\\n    inputs = [\\n        NestedDictInput(\\n            name=\\\"mem0_config\\\",\\n            display_name=\\\"Mem0 Configuration\\\",\\n            info=\\\"\\\"\\\"Configuration dictionary for initializing Mem0 memory instance.\\n                    Example:\\n                    {\\n                        \\\"graph_store\\\": {\\n                            \\\"provider\\\": \\\"neo4j\\\",\\n                            \\\"config\\\": {\\n                                \\\"url\\\": \\\"neo4j+s://your-neo4j-url\\\",\\n                                \\\"username\\\": \\\"neo4j\\\",\\n                                \\\"password\\\": \\\"your-password\\\"\\n                            }\\n                        },\\n                        \\\"version\\\": \\\"v1.1\\\"\\n                    }\\\"\\\"\\\",\\n            input_types=[\\\"Data\\\", \\\"JSON\\\"],\\n        ),\\n        MessageTextInput(\\n            name=\\\"ingest_message\\\",\\n            display_name=\\\"Message to Ingest\\\",\\n            info=\\\"The message content to be ingested into Mem0 memory.\\\",\\n        ),\\n        HandleInput(\\n            name=\\\"existing_memory\\\",\\n            display_name=\\\"Existing Memory Instance\\\",\\n            input_types=[\\\"Memory\\\"],\\n            info=\\\"Optional existing Mem0 memory instance. If not provided, a new instance will be created.\\\",\\n        ),\\n        MessageTextInput(\\n            name=\\\"user_id\\\", display_name=\\\"User ID\\\", info=\\\"Identifier for the user associated with the messages.\\\"\\n        ),\\n        MessageTextInput(\\n            name=\\\"search_query\\\", display_name=\\\"Search Query\\\", info=\\\"Input text for searching related memories in Mem0.\\\"\\n        ),\\n        SecretStrInput(\\n            name=\\\"mem0_api_key\\\",\\n            display_name=\\\"Mem0 API Key\\\",\\n            info=\\\"API key for Mem0 platform. Leave empty to use the local version.\\\",\\n        ),\\n        DictInput(\\n            name=\\\"metadata\\\",\\n            display_name=\\\"Metadata\\\",\\n            info=\\\"Additional metadata to associate with the ingested message.\\\",\\n            advanced=True,\\n        ),\\n        SecretStrInput(\\n            name=\\\"openai_api_key\\\",\\n            display_name=\\\"OpenAI API Key\\\",\\n            required=False,\\n            info=\\\"API key for OpenAI. Required if using OpenAI Embeddings without a provided configuration.\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(name=\\\"memory\\\", display_name=\\\"Mem0 Memory\\\", method=\\\"ingest_data\\\"),\\n        Output(\\n            name=\\\"search_results\\\",\\n            display_name=\\\"Search Results\\\",\\n            method=\\\"build_search_results\\\",\\n        ),\\n    ]\\n\\n    def build_mem0(self) -> Memory:\\n        \\\"\\\"\\\"Initializes a Mem0 memory instance based on provided configuration and API keys.\\\"\\\"\\\"\\n        # Check if we're in Astra cloud environment and raise an error if we are.\\n        raise_error_if_astra_cloud_disable_component(disable_component_in_astra_cloud_msg)\\n\\n        # Pass the OpenAI key through mem0's config instead of writing os.environ.\\n        # os.environ is process-global and persists across requests, so in a shared\\n        # serving process (e.g. lfx serve) one caller's key would leak into other\\n        # concurrent requests. mem0's OpenAI llm/embedder read config.api_key before\\n        # falling back to OPENAI_API_KEY, so config injection keeps it request-scoped.\\n        config = dict(self.mem0_config) if self.mem0_config else {}\\n        if self.openai_api_key:\\n            for section in (\\\"llm\\\", \\\"embedder\\\"):\\n                sec = dict(config.get(section) or {})\\n                if sec.get(\\\"provider\\\", \\\"openai\\\") != \\\"openai\\\":\\n                    continue  # the OpenAI key is irrelevant to non-OpenAI providers\\n                sec[\\\"provider\\\"] = \\\"openai\\\"\\n                sec_config = dict(sec.get(\\\"config\\\") or {})\\n                sec_config.setdefault(\\\"api_key\\\", self.openai_api_key)\\n                sec[\\\"config\\\"] = sec_config\\n                config[section] = sec\\n\\n        try:\\n            mem0 = importlib.import_module(\\\"mem0\\\")\\n            if not self.mem0_api_key:\\n                return mem0.Memory.from_config(config_dict=config) if config else mem0.Memory()\\n            if self.mem0_config:\\n                return mem0.MemoryClient.from_config(api_key=self.mem0_api_key, config_dict=dict(self.mem0_config))\\n            return mem0.MemoryClient(api_key=self.mem0_api_key)\\n        except ImportError as e:\\n            msg = \\\"Mem0 is not properly installed. Please install it with 'pip install -U mem0ai'.\\\"\\n            raise ImportError(msg) from e\\n\\n    def ingest_data(self) -> Memory:\\n        \\\"\\\"\\\"Ingests a new message into Mem0 memory and returns the updated memory instance.\\\"\\\"\\\"\\n        # Check if we're in Astra cloud environment and raise an error if we are.\\n        raise_error_if_astra_cloud_disable_component(disable_component_in_astra_cloud_msg)\\n        mem0_memory = self.existing_memory or self.build_mem0()\\n\\n        if not self.ingest_message or not self.user_id:\\n            logger.warning(\\\"Missing 'ingest_message' or 'user_id'; cannot ingest data.\\\")\\n            return mem0_memory\\n\\n        metadata = self.metadata or {}\\n\\n        logger.info(\\\"Ingesting message for user_id: %s\\\", self.user_id)\\n\\n        try:\\n            mem0_memory.add(self.ingest_message, user_id=self.user_id, metadata=metadata)\\n        except Exception:\\n            logger.exception(\\\"Failed to add message to Mem0 memory.\\\")\\n            raise\\n\\n        return mem0_memory\\n\\n    def build_search_results(self) -> Data:\\n        \\\"\\\"\\\"Searches the Mem0 memory for related messages based on the search query and returns the results.\\\"\\\"\\\"\\n        # Check if we're in Astra cloud environment and raise an error if we are.\\n        raise_error_if_astra_cloud_disable_component(disable_component_in_astra_cloud_msg)\\n        mem0_memory = self.ingest_data()\\n        search_query = self.search_query\\n        user_id = self.user_id\\n\\n        logger.info(\\\"Search query: %s\\\", search_query)\\n\\n        try:\\n            if search_query:\\n                logger.info(\\\"Performing search with query.\\\")\\n                related_memories = mem0_memory.search(query=search_query, filters={\\\"user_id\\\": user_id})\\n            else:\\n                logger.info(\\\"Retrieving all memories for user_id: %s\\\", user_id)\\n                related_memories = mem0_memory.get_all(filters={\\\"user_id\\\": user_id})\\n        except Exception:\\n            logger.exception(\\\"Failed to retrieve related memories from Mem0.\\\")\\n            raise\\n\\n        logger.info(\\\"Related memories retrieved: %s\\\", related_memories)\\n        return related_memories\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/milvus/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"89e7bc44bad3ae8dc2de5a62001006d9ba04ef31bad1f81f032543db573f3639\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .milvus import MilvusVectorStoreComponent\\n\\n_dynamic_imports = {\\n    \\\"MilvusVectorStoreComponent\\\": \\\"milvus\\\",\\n}\\n\\n__all__ = [\\n    \\\"MilvusVectorStoreComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import Milvus components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/milvus/milvus.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"1b7d22570cacf3db292b80942cc93d7995ad547ef502646cff9e1a2019328c27\",\"content\":\"from lfx.base.vectorstores.model import LCVectorStoreComponent, check_cached_vector_store\\nfrom lfx.helpers.data import docs_to_data\\nfrom lfx.io import (\\n    BoolInput,\\n    DictInput,\\n    DropdownInput,\\n    FloatInput,\\n    HandleInput,\\n    IntInput,\\n    SecretStrInput,\\n    StrInput,\\n)\\nfrom lfx.schema.data import Data\\nfrom lfx.utils.ssrf_protection import validate_connector_url_for_ssrf\\n\\n\\nclass MilvusVectorStoreComponent(LCVectorStoreComponent):\\n    \\\"\\\"\\\"Milvus vector store with search capabilities.\\\"\\\"\\\"\\n\\n    display_name: str = \\\"Milvus\\\"\\n    description: str = \\\"Milvus vector store with search capabilities\\\"\\n    name = \\\"Milvus\\\"\\n    icon = \\\"Milvus\\\"\\n\\n    inputs = [\\n        StrInput(name=\\\"collection_name\\\", display_name=\\\"Collection Name\\\", value=\\\"langflow\\\"),\\n        StrInput(name=\\\"collection_description\\\", display_name=\\\"Collection Description\\\", value=\\\"\\\"),\\n        StrInput(\\n            name=\\\"uri\\\",\\n            display_name=\\\"Connection URI\\\",\\n            value=\\\"http://localhost:19530\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"password\\\",\\n            display_name=\\\"Milvus Token\\\",\\n            value=\\\"\\\",\\n            info=\\\"Ignore this field if no token is required to make connection.\\\",\\n        ),\\n        DictInput(name=\\\"connection_args\\\", display_name=\\\"Other Connection Arguments\\\", advanced=True),\\n        StrInput(name=\\\"primary_field\\\", display_name=\\\"Primary Field Name\\\", value=\\\"pk\\\"),\\n        StrInput(name=\\\"text_field\\\", display_name=\\\"Text Field Name\\\", value=\\\"text\\\"),\\n        StrInput(name=\\\"vector_field\\\", display_name=\\\"Vector Field Name\\\", value=\\\"vector\\\"),\\n        DropdownInput(\\n            name=\\\"consistency_level\\\",\\n            display_name=\\\"Consistencey Level\\\",\\n            options=[\\\"Bounded\\\", \\\"Session\\\", \\\"Strong\\\", \\\"Eventual\\\"],\\n            value=\\\"Session\\\",\\n            advanced=True,\\n        ),\\n        DictInput(name=\\\"index_params\\\", display_name=\\\"Index Parameters\\\", advanced=True),\\n        DictInput(name=\\\"search_params\\\", display_name=\\\"Search Parameters\\\", advanced=True),\\n        BoolInput(name=\\\"drop_old\\\", display_name=\\\"Drop Old Collection\\\", value=False, advanced=True),\\n        FloatInput(name=\\\"timeout\\\", display_name=\\\"Timeout\\\", advanced=True),\\n        *LCVectorStoreComponent.inputs,\\n        HandleInput(name=\\\"embedding\\\", display_name=\\\"Embedding\\\", input_types=[\\\"Embeddings\\\"]),\\n        IntInput(\\n            name=\\\"number_of_results\\\",\\n            display_name=\\\"Number of Results\\\",\\n            info=\\\"Number of results to return.\\\",\\n            value=4,\\n            advanced=True,\\n        ),\\n    ]\\n\\n    @check_cached_vector_store\\n    def build_vector_store(self):\\n        try:\\n            from langchain_milvus.vectorstores import Milvus as LangchainMilvus\\n        except ImportError as e:\\n            msg = \\\"Could not import Milvus integration package. Please install it with `pip install langchain-milvus`.\\\"\\n            raise ImportError(msg) from e\\n        # uri is tenant-controlled: block SSRF to internal/cloud-metadata hosts.\\n        validate_connector_url_for_ssrf(self.uri)\\n        self.connection_args.update(uri=self.uri, token=self.password)\\n        milvus_store = LangchainMilvus(\\n            embedding_function=self.embedding,\\n            collection_name=self.collection_name,\\n            collection_description=self.collection_description,\\n            connection_args=self.connection_args,\\n            consistency_level=self.consistency_level,\\n            index_params=self.index_params,\\n            search_params=self.search_params,\\n            drop_old=self.drop_old,\\n            auto_id=True,\\n            primary_field=self.primary_field,\\n            text_field=self.text_field,\\n            vector_field=self.vector_field,\\n            timeout=self.timeout,\\n        )\\n\\n        # Convert DataFrame to Data if needed using parent's method\\n        self.ingest_data = self._prepare_ingest_data()\\n\\n        documents = []\\n        for _input in self.ingest_data or []:\\n            if isinstance(_input, Data):\\n                documents.append(_input.to_lc_document())\\n            else:\\n                documents.append(_input)\\n\\n        if documents:\\n            milvus_store.add_documents(documents)\\n\\n        return milvus_store\\n\\n    def search_documents(self) -> list[Data]:\\n        vector_store = self.build_vector_store()\\n\\n        if self.search_query and isinstance(self.search_query, str) and self.search_query.strip():\\n            docs = vector_store.similarity_search(\\n                query=self.search_query,\\n                k=self.number_of_results,\\n            )\\n\\n            data = docs_to_data(docs)\\n            self.status = data\\n            return data\\n        return []\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/mistral/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"189dfa5bf11d2f451fd1acd2613308d3e922fab1102d68529f683e6d4e97a80b\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .mistral import MistralAIModelComponent\\n    from .mistral_embeddings import MistralAIEmbeddingsComponent\\n\\n_dynamic_imports = {\\n    \\\"MistralAIModelComponent\\\": \\\"mistral\\\",\\n    \\\"MistralAIEmbeddingsComponent\\\": \\\"mistral_embeddings\\\",\\n}\\n\\n__all__ = [\\n    \\\"MistralAIEmbeddingsComponent\\\",\\n    \\\"MistralAIModelComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import mistral components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no attribute '{attr_name}'\\\"\\n        raise AttributeError(msg)\\n    try:\\n        result = import_mod(attr_name, _dynamic_imports[attr_name], __spec__.parent)\\n    except (ModuleNotFoundError, ImportError, AttributeError) as e:\\n        msg = f\\\"Could not import '{attr_name}' from '{__name__}': {e}\\\"\\n        raise AttributeError(msg) from e\\n    globals()[attr_name] = result\\n    return result\\n\\n\\ndef __dir__() -> list[str]:\\n    return list(__all__)\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/mistral/mistral.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"8f59507f28903798705fac7f3af37f538fd40a95cb8822882a0ef7354e5a489f\",\"content\":\"from langchain_mistralai import ChatMistralAI\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import LanguageModel\\nfrom lfx.io import BoolInput, DropdownInput, FloatInput, IntInput, SecretStrInput, StrInput\\nfrom pydantic.v1 import SecretStr\\n\\n\\nclass MistralAIModelComponent(LCModelComponent):\\n    display_name = \\\"MistralAI\\\"\\n    description = \\\"Generates text using MistralAI LLMs.\\\"\\n    icon = \\\"MistralAI\\\"\\n    name = \\\"MistralModel\\\"\\n\\n    inputs = [\\n        *LCModelComponent.get_base_inputs(),\\n        IntInput(\\n            name=\\\"max_tokens\\\",\\n            display_name=\\\"Max Tokens\\\",\\n            advanced=True,\\n            info=\\\"The maximum number of tokens to generate. Set to 0 for unlimited tokens.\\\",\\n        ),\\n        DropdownInput(\\n            name=\\\"model_name\\\",\\n            display_name=\\\"Model Name\\\",\\n            advanced=False,\\n            options=[\\n                \\\"open-mixtral-8x7b\\\",\\n                \\\"open-mixtral-8x22b\\\",\\n                \\\"mistral-small-latest\\\",\\n                \\\"mistral-medium-latest\\\",\\n                \\\"mistral-large-latest\\\",\\n                \\\"codestral-latest\\\",\\n            ],\\n            value=\\\"codestral-latest\\\",\\n        ),\\n        StrInput(\\n            name=\\\"mistral_api_base\\\",\\n            display_name=\\\"Mistral API Base\\\",\\n            advanced=True,\\n            info=\\\"The base URL of the Mistral API. Defaults to https://api.mistral.ai/v1. \\\"\\n            \\\"You can change this to use other APIs like JinaChat, LocalAI and Prem.\\\",\\n        ),\\n        SecretStrInput(\\n            name=\\\"api_key\\\",\\n            display_name=\\\"Mistral API Key\\\",\\n            info=\\\"The Mistral API Key to use for the Mistral model.\\\",\\n            advanced=False,\\n            required=True,\\n            value=\\\"MISTRAL_API_KEY\\\",\\n        ),\\n        FloatInput(\\n            name=\\\"temperature\\\",\\n            display_name=\\\"Temperature\\\",\\n            value=0.1,\\n            advanced=True,\\n        ),\\n        IntInput(\\n            name=\\\"max_retries\\\",\\n            display_name=\\\"Max Retries\\\",\\n            advanced=True,\\n            value=5,\\n        ),\\n        IntInput(\\n            name=\\\"timeout\\\",\\n            display_name=\\\"Timeout\\\",\\n            advanced=True,\\n            value=60,\\n        ),\\n        IntInput(\\n            name=\\\"max_concurrent_requests\\\",\\n            display_name=\\\"Max Concurrent Requests\\\",\\n            advanced=True,\\n            value=3,\\n        ),\\n        FloatInput(\\n            name=\\\"top_p\\\",\\n            display_name=\\\"Top P\\\",\\n            advanced=True,\\n            value=1,\\n        ),\\n        IntInput(\\n            name=\\\"random_seed\\\",\\n            display_name=\\\"Random Seed\\\",\\n            value=1,\\n            advanced=True,\\n        ),\\n        BoolInput(\\n            name=\\\"safe_mode\\\",\\n            display_name=\\\"Safe Mode\\\",\\n            advanced=True,\\n            value=False,\\n        ),\\n    ]\\n\\n    def build_model(self) -> LanguageModel:  # type: ignore[type-var]\\n        try:\\n            return ChatMistralAI(\\n                model_name=self.model_name,\\n                mistral_api_key=SecretStr(self.api_key).get_secret_value() if self.api_key else None,\\n                endpoint=self.mistral_api_base or \\\"https://api.mistral.ai/v1\\\",\\n                max_tokens=self.max_tokens or None,\\n                temperature=self.temperature,\\n                max_retries=self.max_retries,\\n                timeout=self.timeout,\\n                max_concurrent_requests=self.max_concurrent_requests,\\n                top_p=self.top_p,\\n                random_seed=self.random_seed,\\n                safe_mode=self.safe_mode,\\n                streaming=self.stream,\\n            )\\n        except Exception as e:\\n            msg = \\\"Could not connect to MistralAI API.\\\"\\n            raise ValueError(msg) from e\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/mistral/mistral_embeddings.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"eae198eed8d2140b6891319a8be9791dd60b87efab2075239208c4b8a652f9d4\",\"content\":\"from langchain_mistralai import MistralAIEmbeddings\\nfrom lfx.base.models.model import LCModelComponent\\nfrom lfx.field_typing import Embeddings\\nfrom lfx.io import DropdownInput, IntInput, MessageTextInput, Output, SecretStrInput\\nfrom pydantic.v1 import SecretStr\\n\\n\\nclass MistralAIEmbeddingsComponent(LCModelComponent):\\n    display_name = \\\"MistralAI Embeddings\\\"\\n    description = \\\"Generate embeddings using MistralAI models.\\\"\\n    icon = \\\"MistralAI\\\"\\n    name = \\\"MistalAIEmbeddings\\\"\\n\\n    inputs = [\\n        DropdownInput(\\n            name=\\\"model\\\",\\n            display_name=\\\"Model\\\",\\n            advanced=False,\\n            options=[\\\"mistral-embed\\\"],\\n            value=\\\"mistral-embed\\\",\\n        ),\\n        SecretStrInput(name=\\\"mistral_api_key\\\", display_name=\\\"Mistral API Key\\\", required=True),\\n        IntInput(\\n            name=\\\"max_concurrent_requests\\\",\\n            display_name=\\\"Max Concurrent Requests\\\",\\n            advanced=True,\\n            value=64,\\n        ),\\n        IntInput(name=\\\"max_retries\\\", display_name=\\\"Max Retries\\\", advanced=True, value=5),\\n        IntInput(name=\\\"timeout\\\", display_name=\\\"Request Timeout\\\", advanced=True, value=120),\\n        MessageTextInput(\\n            name=\\\"endpoint\\\",\\n            display_name=\\\"API Endpoint\\\",\\n            advanced=True,\\n            value=\\\"https://api.mistral.ai/v1/\\\",\\n        ),\\n    ]\\n\\n    outputs = [\\n        Output(display_name=\\\"Embeddings\\\", name=\\\"embeddings\\\", method=\\\"build_embeddings\\\"),\\n    ]\\n\\n    def build_embeddings(self) -> Embeddings:\\n        if not self.mistral_api_key:\\n            msg = \\\"Mistral API Key is required\\\"\\n            raise ValueError(msg)\\n\\n        api_key = SecretStr(self.mistral_api_key).get_secret_value()\\n\\n        return MistralAIEmbeddings(\\n            api_key=api_key,\\n            model=self.model,\\n            endpoint=self.endpoint,\\n            max_concurrent_requests=self.max_concurrent_requests,\\n            max_retries=self.max_retries,\\n            timeout=self.timeout,\\n        )\\n\"},{\"record_type\":\"third_party_source_reference\",\"source_repository\":\"langflow-main\",\"source_path\":\"src/bundles/lfx-bundles/src/lfx_bundles/mongodb/__init__.py\",\"source_license\":\"MIT\",\"trust\":\"untrusted_reference_only\",\"retrieval_policy\":\"internal_reference_only\",\"source_sha256\":\"603880a0ad0cbbf0d746d32e94e1c580c7e49f5f4f4fd10ee235eeebcd0424ef\",\"content\":\"from __future__ import annotations\\n\\nfrom typing import TYPE_CHECKING, Any\\n\\nfrom lfx.utils.lazy_import import import_mod\\n\\nif TYPE_CHECKING:\\n    from .mongodb_atlas import MongoVectorStoreComponent\\n\\n_dynamic_imports = {\\n    \\\"MongoVectorStoreComponent\\\": \\\"mongodb_atlas\\\",\\n}\\n\\n__all__ = [\\n    \\\"MongoVectorStoreComponent\\\",\\n]\\n\\n\\ndef __getattr__(attr_name: str) -> Any:\\n    \\\"\\\"\\\"Lazily import MongoDB components on attribute access.\\\"\\\"\\\"\\n    if attr_name not in _dynamic_imports:\\n        msg = f\\\"module '{__name__}' has no att";
